-- DWA-A 138-1 · engineer hints on every field and equation (hint wave 2026-10-05). Each description now carries a German
-- hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form renders the part of the page locale).
-- Content authored from the English study book (verified against the printed PDF 2026-09-29) and the German transcript;
-- every number/limit/clause in a hint is traceable to those sources (authoring JSON with a source string per hint kept in the vault).
-- SAFETY: text only (fields.description, equations.description); no field, equation, gate, value or severity changes.
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261005110000_a138_field_equation_hints.sql
-- Rollback (restores the descriptions of 2026-10-05 before this block): scripts/migrations/rollback-20261005110000_a138_field_equation_hints.sql
BEGIN;
UPDATE fields f SET description = 'Bestätigung, dass das Vorhaben in den Anwendungsbereich fällt: Versickerung von gesammelt abfließendem Niederschlagswasser von bebauten oder befestigten Flächen (Abwasser nach § 54 WHG) innerhalb von Siedlungsgebieten. Das Tor A138-REQ-01 sperrt alle weiteren Arbeitsblätter, bis das Feld bestätigt ist. Außerörtliche Straßen und Gleisanlagen (REwS, RiStWag, Ril 836) und Einleitungen in oberirdische Gewässer (DWA-A/M 102) liegen außerhalb (§ 1).
[EN] Confirm that the project lies within the scope: infiltration of rainwater that runs off collected from built-up or paved surfaces (wastewater under § 54 WHG) inside settlement areas. Gate A138-REQ-01 blocks all further worksheets until this is confirmed. Roads and railways outside settlements (REwS, RiStWag, Ril 836) and discharges to surface waters (DWA-A/M 102) are outside the scope (§ 1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'a138_applicable';
UPDATE fields f SET description = 'Bestätigung, dass die Grundlagendaten der Ersteinschätzung (Boden, Grundwasser, Topografie, Restriktionen, technische Machbarkeit) mit Quelle dokumentiert sind, wie Tabelle 4 sie auflistet; die Dokumentation selbst erfolgt in A138-03. Tor A138-REQ-25 blockiert ohne Haken. Spalte-2-Kriterien der Tabelle 3 gelten nur als erfüllt, wenn sie durch Fachgutachten nachgewiesen sind (§ 5.1.2, Tab. 3 Zeile „Umsetzbarkeit“, Tab. 4).
[EN] Attest that the basic data of the initial assessment (soil, groundwater, topography, restrictions, technical feasibility) are documented with their source as listed in Table 4; the documentation itself is entered in A138-03. Gate A138-REQ-25 blocks until ticked. Column-2 criteria of Table 3 count as met only when proven by expert reports (§ 5.1.2, Tab. 3 row ''Umsetzbarkeit'', Tab. 4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'attest_a138_01_a138_req_25';
UPDATE fields f SET description = 'Bestätigung, dass die erforderliche Abstimmung mit der Wasserbehörde erfolgt oder eingeleitet ist. Das Arbeitsblatt verlangt sie u. a. bei Sohlabstand zum MHGW < 1 m (§ 5.2.1), in Wasserschutzgebieten vor Planungsbeginn (§ 4.3), bei Flächen der Gruppen D und S sowie Anlieferungs-/Ladeflächen (§ 5.2.3.2, Tab. 6/7 Anm. *) und bei k_f > 1·10⁻³ m/s (§ 5.3.1). Tor A138-REQ-27 blockiert ohne Haken; ob Abstimmung nötig ist, wird in A138-02 festgehalten.
[EN] Attest that the required coordination with the water authority has taken place or been initiated. The standard calls for it e.g. when the base is < 1 m above MHGW (§ 5.2.1), in water protection areas before planning starts (§ 4.3), for groups D and S and delivery/loading areas (§ 5.2.3.2, Tab. 6/7 note *), and when k_f > 1·10⁻³ m/s (§ 5.3.1). Gate A138-REQ-27 blocks until ticked; whether coordination is needed is recorded in A138-02.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'attest_a138_01_a138_req_27';
UPDATE fields f SET description = 'Bestätigung, dass die mitgeltenden Regelwerke für dieses Vorhaben identifiziert sind. Das Arbeitsblatt verweist u. a. auf DWA-A 117 (Bemessungsansätze, § 5.3.3.1), DWA-A 531/KOSTRA (Regendaten, § 5.3.3.5), DWA-A 118 und DIN EN 752/DIN 1986-100 (Häufigkeiten, Überflutungsnachweis, § 5.3.3.4/5.3.4), DWA-A/M 102 (Einleitung in Gewässer, § 1) und DWA-M 102-4 (Wasserhaushalt, § 4.1). Tor A138-REQ-29 blockiert ohne Haken.
[EN] Attest that the co-applicable standards for this project have been identified. The standard refers e.g. to DWA-A 117 (sizing approach, § 5.3.3.1), DWA-A 531/KOSTRA (rain data, § 5.3.3.5), DWA-A 118 and DIN EN 752/DIN 1986-100 (frequencies, flood proof, § 5.3.3.4/5.3.4), DWA-A/M 102 (discharge to surface waters, § 1) and DWA-M 102-4 (water balance, § 4.1). Gate A138-REQ-29 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'attest_a138_01_a138_req_29';
UPDATE fields f SET description = 'Ansprechperson auf Bauherrenseite, vom Bauherrn benannt. Reine Verwaltungsangabe; wird in Berichtsköpfe übernommen und in keiner Prüfung verwendet.
[EN] Contact person on the client''s side, named by the client. Administrative only; carried into report headers and not used by any check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'client_contact';
UPDATE fields f SET description = 'Rechtlicher Bauherr (Auftraggeber) des Vorhabens. Pflichtfeld für die Projektregistrierung; wird in Berichtsköpfe und Nachweise übernommen, keine fachliche Prüfung. Hinweis: Die Abwasserbeseitigungspflicht liegt in aller Regel zunächst bei den Kommunen (§ 5.1.3).
[EN] Legal client (Bauherr) of the project. Required for registration; carried into report headers and evidence documents, no technical check. Note: the duty of wastewater disposal lies as a rule first with the municipalities (§ 5.1.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'client_name';
UPDATE fields f SET description = 'Wahl zwischen Einfachem Verfahren (statistische Starkregen, z. B. KOSTRA) und Nachweisverfahren (Niederschlag-Abfluss-Langzeitsimulation) nach DWA-A 117. Das Einfache Verfahren gilt in der Regel für dezentrale Anlagen; seine Anwendungsbedingungen (A_E ≤ 200 ha oder t_f ≤ 15 min, n ≥ 0,1/a, q_S,AC ≥ 2 l/(s·ha)) prüft A138-08. Für zentrale und gekoppelte Systeme wird das Nachweisverfahren empfohlen; es braucht Regenreihen über mindestens zehn Jahre mit Auflösung ≤ 5 min (§ 5.3.3.1–5.3.3.3, Tab. 12).
[EN] Choose between the simple method (statistical heavy rain, e.g. KOSTRA) and the verification method (rainfall-runoff long-term simulation) per DWA-A 117. The simple method can as a rule be used for decentralised facilities; its conditions (A_E ≤ 200 ha or t_f ≤ 15 min, n ≥ 0.1/a, q_S,AC ≥ 2 l/(s·ha)) are checked in A138-08. For central and coupled systems the verification method is recommended; it needs rainfall series of at least ten years at ≤ 5 min resolution (§ 5.3.3.1–5.3.3.3, Tab. 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'design_method';
UPDATE fields f SET description = 'Kennung der KOSTRA-Rasterzelle, in der der Standort liegt; aus dem KOSTRA-DWD-Atlas des DWD anhand der Koordinaten ermittelt. Die Regenspenden r_D(n) in A138-04 müssen aus genau dieser Zelle stammen; Tor A138-REQ-05 verlangt Zelle und Tabelle gemeinsam. Das Arbeitsblatt bezieht sich auf KOSTRA-DWD-2020 (2023); alternativ gelten örtliche Starkregenauswertungen nach DWA-A 531 (§ 5.3.3.5).
[EN] Identifier of the KOSTRA grid cell containing the site, read from the DWD KOSTRA atlas using the coordinates. The rainfall intensities r_D(n) in A138-04 must come from exactly this cell; gate A138-REQ-05 requires cell and table together. The standard refers to KOSTRA-DWD-2020 (2023); local heavy-rain evaluations per DWA-A 531 are the alternative (§ 5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'kostra_grid_cell';
UPDATE fields f SET description = 'Planungsbüro, das die Versickerungsplanung verantwortet. Verwaltungsangabe für Berichtsköpfe; keine Prüfung. In Spalte-3-Fällen der Tabelle 3 müssen die Fachplanenden technische und planerische Maßnahmen aufzeigen (§ 5.1.2).
[EN] Engineering firm responsible for the infiltration design. Administrative, used in report headers; no check. In column-3 cases of Table 3 the specialist planners must show technical and planning measures (§ 5.1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'planner_firm';
UPDATE fields f SET description = 'Verantwortlicher Ingenieur (Engineer of Record) für die Nachweise dieses Projekts. Verwaltungsangabe; erscheint in Berichten und Nachweisen, keine Prüfung.
[EN] Engineer of record for the evidence produced in this project. Administrative; appears in reports and evidence documents, no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'planner_name';
UPDATE fields f SET description = 'HOAI-Leistungsphase des Projekts (Vor-, Entwurfs-, Ausführungs- oder Bestandsplanung); vom Planer gewählt. Steuert nur die Berichtsbeschriftung, keine Prüfung. Das Arbeitsblatt verlangt die Ersteinschätzung im frühen Planungsstadium und die Integration in die Bauleitplanung (§ 5.1.1, § 5.1.3); die überregnete Fläche A_VA darf je nach Planungsstand geschätzt oder aus Planunterlagen entnommen werden (§ 5.3.3.5).
[EN] HOAI service phase of the project (preliminary, design, execution or as-built planning); chosen by the planner. Only labels reports, no check. The standard wants the initial assessment at an early planning stage and integration into land-use planning (§ 5.1.1, § 5.1.3); the rained-on area A_VA may be estimated or taken from planning documents depending on the planning stage (§ 5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'planning_phase';
UPDATE fields f SET description = 'Projektbezeichnung, frei vergeben. Erscheint in allen Berichten und Nachweisen; keine Prüfung.
[EN] Project title, freely assigned. Appears in all reports and evidence documents; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'project_name';
UPDATE fields f SET description = 'Interne Projektnummer des Planungsbüros. Dient der Zuordnung von Berichten, Gutachten und Datenquellen (A138-03); keine Prüfung.
[EN] Internal project number of the engineering firm. Used to link reports, expert opinions and data sources (A138-03); no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'project_number';
UPDATE fields f SET description = 'Art des Vorhabens: Neuerschließung, Bestandsumbau, Nachrüstung oder Sonstiges; vom Planer gewählt. Nur Dokumentation. Das Arbeitsblatt hält Konzeptentwicklung und Vorplanung sowohl bei Neuerschließungen als auch im Bestand für unerlässlich (§ 5.1.3); bei Neuerschließungen liegen für die Belastungseinstufung meist nur allgemeine Kenntnisse vor (§ 5.2.2).
[EN] Kind of project: new development, conversion of existing stock, retrofit or other; chosen by the planner. Documentation only. The standard calls concept development and preliminary planning indispensable both for new developments and existing areas (§ 5.1.3); for new developments usually only general knowledge of pollutant loads is available for categorisation (§ 5.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'project_type';
UPDATE fields f SET description = 'Postanschrift des Grundstücks. Verwaltungsangabe für Berichte; fachlich maßgebend sind Koordinaten und KOSTRA-Rasterzelle. Katasterplan und Ortsbegehung gehören zu den Grundlagendaten der Ersteinschätzung (§ 5.1.2, Tab. 4).
[EN] Postal address of the site. Administrative, for reports; the technically relevant location is given by coordinates and KOSTRA grid cell. Cadastral map and site inspection are part of the basic data for the initial assessment (§ 5.1.2, Tab. 4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'site_address';
UPDATE fields f SET description = 'Bundesland des Standorts. Bestimmt, welche Landesbehörden (Geologischer Dienst, Landesumweltamt, untere Wasserbehörde) die Grundlagendaten nach Tabelle 4 liefern und welche Schutzgebietsverordnung gilt (§ 5.1.1, § 5.1.2). Keine Prüfung im Tool.
[EN] German federal state of the site. Determines which state authorities (geological survey, environment agency, lower water authority) supply the basic data of Table 4 and which protection-area ordinance applies (§ 5.1.1, § 5.1.2). No check in the tool.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'site_bundesland';
UPDATE fields f SET description = 'Geographische Breite des Standorts (WGS84, °N), aus Kataster oder Geoportal. Dient zusammen mit der Länge der Zuordnung der KOSTRA-Rasterzelle (A138-01) und dem Abruf von Boden-, Grundwasser- und Schutzgebietsdaten aus Geoportalen (§ 5.1.2, Tab. 4). Keine Prüfung.
[EN] Latitude of the site (WGS84, °N), from the cadastre or a geoportal. Together with the longitude it fixes the KOSTRA grid cell (A138-01) and the retrieval of soil, groundwater and protection-area data from geoportals (§ 5.1.2, Tab. 4). No check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'site_lat';
UPDATE fields f SET description = 'Geographische Länge des Standorts (WGS84, °E), aus Kataster oder Geoportal. Dient zusammen mit der Breite der Zuordnung der KOSTRA-Rasterzelle (A138-01) und dem Abruf von Grundlagendaten aus Geoportalen (§ 5.1.2, Tab. 4). Keine Prüfung.
[EN] Longitude of the site (WGS84, °E), from the cadastre or a geoportal. Together with the latitude it fixes the KOSTRA grid cell (A138-01) and the retrieval of basic data from geoportals (§ 5.1.2, Tab. 4). No check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'site_lon';
UPDATE fields f SET description = 'Gemeinde bzw. Kreis des Standorts. Legt die zuständige untere Wasser- und Bodenschutzbehörde fest, die Altlastenkataster und Bauleitpläne führt (§ 5.1.2, Tab. 4; § 5.1.3). Verwaltungsangabe, keine Prüfung.
[EN] Municipality or district of the site. Identifies the competent lower water and soil-protection authority that keeps the register of contaminated sites and the land-use plans (§ 5.1.2, Tab. 4; § 5.1.3). Administrative, no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'site_municipality';
UPDATE fields f SET description = 'Gesamtfläche des Grundstücks in m², aus Katasterplan oder Lageplan. Reine Bezugsgröße für Berichte; die Bemessung nutzt nicht die Grundstücksfläche, sondern die angeschlossenen Teilflächen A_E,b,a / A_E,nb,a und den Rechenwert A_C aus A138-07 (§ 5.3.3.5, Gl. 2). Nicht mit dem Einzugsgebiet A_E in A138-08 verwechseln.
[EN] Total property area in m², from the cadastral map or site plan. Reference value for reports only; sizing uses the connected sub-areas A_E,b,a / A_E,nb,a and the design value A_C from A138-07, not the plot area (§ 5.3.3.5, Eq. 2). Do not confuse with the catchment A_E in A138-08.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'site_total_area';
UPDATE fields f SET description = 'Zuständige Wasserbehörde (in der Regel untere Wasserbehörde des Kreises bzw. der Stadt). Versickerungsanlagen für gesammeltes Niederschlagswasser sind Abwasseranlagen nach §§ 57, 60 WHG; die Behörde entscheidet über Erlaubnis und Abstimmungen (§ 4.3, Anhang B). Abstimmung ist u. a. nötig bei Sohlabstand < 1 m zum MHGW, in Schutzgebieten vor Planungsbeginn, beim Durchstoßen stauender Schichten und bei k_f > 1·10⁻³ m/s (§ 5.2.1, § 4.3, § 5.3.1).
[EN] Competent water authority (usually the lower water authority of the district or city). Infiltration facilities for collected rainwater are wastewater facilities under §§ 57, 60 WHG; the authority decides on permits and agreements (§ 4.3, Annex B). Agreement is needed e.g. for a base < 1 m above MHGW, in protection areas before planning starts, for penetrating impermeable layers and for k_f > 1·10⁻³ m/s (§ 5.2.1, § 4.3, § 5.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'wasserbehoerde';
UPDATE fields f SET description = 'Lage des Standorts in einem Trinkwasserschutzgebiet (keine / Zone III / II / I), aus Schutzgebietskarte oder Umwelt-Geoportal (Tab. 4). Tor A138-REQ-COV-01 blockiert bei Zone I und II; in Zone III und Heilquellenschutzgebieten gelten höhere bzw. immissionsbezogene Anforderungen, Abstimmung vor Planungsbeginn. Nach § 4.3 ist Versickerung in Zone I und II in der Regel nicht zulässig; § 5.1.1 nennt Zone I unzulässig und Zone II/III stark eingeschränkt; maßgebend ist stets die Schutzgebietsverordnung (DVGW W 101).
[EN] Whether the site lies in a drinking-water protection area (none / zone III / II / I), from the protection-area map or environmental geoportal (Tab. 4). Gate A138-REQ-COV-01 blocks for zones I and II; zone III and medicinal-spring areas carry higher or immission-related requirements, agreed before planning starts. § 4.3: infiltration in zones I and II is as a rule not permitted; § 5.1.1: zone I not permitted, zones II/III strongly restricted; the protection-area ordinance always governs (DVGW W 101).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-01' AND f.symbol = 'water_protection_zone';
UPDATE fields f SET description = 'Festlegung, ob eine Abstimmung mit der Wasserbehörde erforderlich ist; vom Planer aus den Standortbefunden abgeleitet. Erforderlich u. a. bei Sohlabstand zum MHGW < 1 m (§ 5.1.1/§ 5.2.1), für horizontale Mindestabstände zu Altlasten (§ 5.1.1), in Trinkwasser- und Heilquellenschutzgebieten vor Planungsbeginn (§ 4.3), bei k_f > 1·10⁻³ m/s (§ 5.3.1) und für Spalte-3-Maßnahmen der Tabelle 3 (§ 5.1.2). Die Erledigung wird mit dem Nachweis A138-REQ-27 in A138-01 bestätigt.
[EN] Whether coordination with the water authority is required; derived by the planner from the site findings. Required e.g. for a base < 1 m above MHGW (§ 5.1.1/§ 5.2.1), for horizontal minimum distances to contaminated sites (§ 5.1.1), in drinking-water and medicinal-spring protection areas before planning (§ 4.3), for k_f > 1·10⁻³ m/s (§ 5.3.1) and for column-3 measures of Table 3 (§ 5.1.2). Completion is attested via A138-REQ-27 in A138-01.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'authority_coordination_required';
UPDATE fields f SET description = 'Zeile „Umfeld“ der Tabelle 3: Mindestabstände zu Gebäuden/Baugruben einhaltbar oder unkritisch (Spalte 2); nicht einhaltbar, bautechnische Sicherung wie weiße oder schwarze Wanne möglich (Spalte 3); nicht einhaltbar ohne mögliche Sicherung (Spalte 4). Grundlage ist die Abstandsprüfung nach Bild 4 (distance_to_building_check). Geht in Gleichung A138-02-D1 ein: „not_met_no_protection“ ergibt Code 3. Bei wasserdruckhaltender Abdichtung ist der Abstand unkritisch (§ 5.3.2, Tab. 3).
[EN] ''Surroundings'' row of Table 3: minimum distances to buildings/pits can be kept or are uncritical (column 2); cannot be kept but structural safeguards such as a white or black tank are possible (column 3); cannot be kept and no safeguard is possible (column 4). Base it on the Bild 4 distance check (distance_to_building_check). Feeds equation A138-02-D1: ''not_met_no_protection'' yields code 3. With pressure-water-tight sealing the distance is uncritical (§ 5.3.2, Tab. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'building_clearance_status';
UPDATE fields f SET description = 'Tiefe a der Baugrube des nächstgelegenen Gebäudes ohne wasserdruckhaltende Abdichtung, von Geländeoberkante bis Baugrubenfußpunkt, aus den Bauunterlagen des Gebäudes. Bei nicht unterkellerten Gebäuden gilt stattdessen die Fundamenttiefe. Das Tool berechnet daraus den Mindestabstand 1,5 · a für distance_to_building_check. Achtung: In § 5.3.2/Bild 4 ist a die Baugrubentiefe, in § 5.2.1 der Sohlabstand zum MHGW (§ 5.3.2, Bild 4).
[EN] Depth a of the building pit of the nearest building without pressure-water-tight sealing, from ground level to the pit foot, taken from the building''s construction documents. For buildings without a basement use the foundation depth instead. The tool derives the minimum distance 1.5 · a for distance_to_building_check. Note: in § 5.3.2/Bild 4 a is the pit depth, in § 5.2.1 it is the base-to-MHGW distance (§ 5.3.2, Bild 4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'building_pit_depth_a';
UPDATE fields f SET description = 'Zeile „Altlasten“ der Tabelle 3, aus Altlastenkataster und Gutachten der Bodenschutzbehörde (Tab. 4): keine Altlasten, altlastenverdächtigen Flächen oder schädlichen Bodenveränderungen (Spalte 2); örtlich begrenzt in der Nähe, Mobilisierung unwahrscheinlich oder beseitigbar (Spalte 3); im Boden vorhanden mit Mobilisierungsgefahr (Spalte 4). In Gleichung A138-02-D1 ergibt „present“ Code 3. Zu Altlasten ist ein horizontaler Mindestabstand einzuhalten, der mit der Behörde festzulegen ist (§ 5.1.1, § 5.2.1, Tab. 3).
[EN] ''Contaminated sites'' row of Table 3, from the register and reports of the soil-protection authority (Tab. 4): none present (column 2); locally limited sites nearby with mobilisation unlikely or removable (column 3); present in the soil with a risk of mobilisation (column 4). In equation A138-02-D1 ''present'' yields code 3. A horizontal minimum distance to contaminated sites must be kept, set case by case with the authority (§ 5.1.1, § 5.2.1, Tab. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'contaminated_land_status';
UPDATE fields f SET description = 'Tatsächlicher Abstand vom Rand der maximalen Ausdehnung der Versickerungsanlage (Volleinstau) bis zum Baugrubenfußpunkt des nächsten Gebäudes ohne wasserdruckhaltende Abdichtung, aus dem Lageplan. Wird in distance_to_building_check mit 1,5 · a verglichen. Zusätzlich sind ≥ 0,50 m von der Böschungsoberkante der Baugrube einzuhalten, damit Sickerwasser nicht direkt in die Verfüllzone gelangt; bei zentralen Becken muss der Abstand größer als die mittlere Beckenbreite sein (§ 5.3.2, Bild 4).
[EN] Actual distance from the edge of the facility''s maximum extent (full impoundment) to the pit foot of the nearest building without pressure-water-tight sealing, from the site plan. Compared with 1.5 · a in distance_to_building_check. Additionally keep ≥ 0.50 m from the top edge of the pit slope so seepage does not reach the backfill zone directly; for central basins the distance must exceed the mean basin width (§ 5.3.2, Bild 4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'distance_to_building_actual';
UPDATE fields f SET description = 'Ergebnis der Abstandsprüfung nach Bild 4: PASS, wenn distance_to_building_actual ≥ 1,5 · building_pit_depth_a; vom Tool gesetzt. Die Regel gilt für Gebäude ohne wasserdruckhaltende Abdichtung, wenn der Grundwasserstand dauerhaft unter der Kellersohle liegt; bei Abdichtung ist der Abstand unkritisch. Das Ergebnis begründet building_clearance_status; ein FAIL führt zu Spalte 3 (Sicherung möglich) oder Spalte 4 der Tabelle 3 (§ 5.3.2, Bild 4).
[EN] Result of the Bild 4 distance check: PASS if distance_to_building_actual ≥ 1.5 · building_pit_depth_a; set by the tool. The rule applies to buildings without pressure-water-tight sealing when the groundwater stays permanently below the basement floor; with sealing the distance is uncritical. The result supports building_clearance_status; a FAIL leads to column 3 (safeguard possible) or column 4 of Table 3 (§ 5.3.2, Bild 4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'distance_to_building_check';
UPDATE fields f SET description = 'Gesamtergebnis der Ersteinschätzung nach Tabelle 3: möglich (alle Spalte-2-Kriterien erfüllt und durch Fachgutachten nachgewiesen), bedingt möglich (mindestens ein Spalte-3-Kriterium; Fachplanende zeigen technische und planerische Maßnahmen auf, ggf. mit Behörde abgestimmt) oder nicht möglich (ein Spalte-4-Kriterium trifft zu oder Maßnahmen sind nicht möglich). Vom Planer festgelegt; feasibility_code liefert den Vorschlag. Tor A138-REQ-02 blockiert bei „nicht möglich“ (§ 5.1.2, Tab. 3).
[EN] Overall result of the initial assessment per Table 3: feasible (all column-2 criteria met and proven by expert reports), conditional (at least one column-3 criterion; the planners show technical and planning measures, agreed with the authority where needed) or not feasible (one column-4 criterion applies or measures are not possible). Set by the planner; feasibility_code gives the proposal. Gate A138-REQ-02 blocks on ''not feasible'' (§ 5.1.2, Tab. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'feasibility_determination';
UPDATE fields f SET description = 'Zeile „geotechnische Gefährdung“ der Tabelle 3, aus Baugrundgutachten und geologischer Karte (Tab. 4): Gefährdung durch die Anlage ausgeschlossen (Spalte 2); im näheren Umfeld möglich, nicht am Standort (Spalte 3); am Standort vorhanden (Spalte 4). Genannt: Bodenverflüssigung, Quellböden, Unterspülung, Karstgesteine. In Gleichung A138-02-D1 ergibt „at_site“ Code 3. In Gebieten mit Bodensetzungen, Erdfällen, Karst und Bergbau ist die Wirkung der Anlage auf den Untergrund mit Sachkunde zu prüfen (§ 5.1.1, § 5.3.1, Tab. 3).
[EN] ''Geotechnical hazard'' row of Table 3, from the geotechnical report and geological map (Tab. 4): hazard caused by the facility excluded (column 2); possible in the wider surroundings but not at the site (column 3); present at the site (column 4). Named: soil liquefaction, swelling soils, underwashing, karst rocks. In equation A138-02-D1 ''at_site'' yields code 3. In areas with settlement, sinkholes, karst or mining the effect on the subsoil must be checked with expertise (§ 5.1.1, § 5.3.1, Tab. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'geotech_hazards';
UPDATE fields f SET description = 'Abstand zwischen der Sohle der geplanten Anlage und dem maßgeblichen MHGW in m: Sohlhöhe (Planung) minus MHGW (A138-05; Messstellen/Gleichenplan, Tab. 4). Tor A138-REQ-04 blockiert unter 1,0 m; in Gleichung A138-02-D1 ist ≥ 1 m Voraussetzung für Code 1. Bei ≥ 1 m kann die Abstimmung mit der Behörde in der Regel entfallen; darunter ist der Abstand nach Belastung, Zuflussmenge und Bodeneigenschaften mit der Behörde festzulegen (Spalte 3, nicht Spalte 4). Schichtenwasser ist zu prüfen (§ 5.1.1, § 5.2.1, Tab. 3).
[EN] Distance between the base of the planned facility and the governing MHGW in m: base level (design) minus MHGW (A138-05; observation wells / contour map, Tab. 4). Gate A138-REQ-04 blocks below 1.0 m; in equation A138-02-D1 ≥ 1 m is a condition for code 1. At ≥ 1 m the agreement with the authority can as a rule be dispensed with; below it the distance is set with the authority according to load, inflow and soil properties (column 3, not column 4). Check for perched water too (§ 5.1.1, § 5.2.1, Tab. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'gw_clearance';
UPDATE fields f SET description = 'Vorläufiger k_f der aufnehmenden Bodenschicht in m/s, geschätzt aus Boden-/geologischer Karte oder Bodenansprache (Tab. 4; Bild 2). Geht in Gleichung A138-02-D1 ein, wo k_f ≥ 1·10⁻⁶ m/s Voraussetzung für Code 1 ist; der gemessene Bemessungswert folgt in A138-05. Für ausschließliche Versickerung soll k_f in der Regel mindestens 1·10⁻⁶ m/s betragen (§ 5.1.1, Tab. 3). Schätzwerte streuen über mehrere Größenordnungen und sind nur für die Ersteinschätzung, nicht für die Bemessung zulässig (Anh. A, Tab. A.1).
[EN] Preliminary k_f of the receiving soil layer in m/s, estimated from soil/geological maps or a soil description (Tab. 4; Bild 2). Feeds equation A138-02-D1, where k_f ≥ 1·10⁻⁶ m/s is a condition for code 1; the measured design value follows in A138-05. For exclusive infiltration k_f should as a rule be at least 1·10⁻⁶ m/s (§ 5.1.1, Tab. 3). Such estimates span several orders of magnitude and are admissible for the initial assessment only, not for design (Annex A, Tab. A.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'kf_initial_estimate';
UPDATE fields f SET description = 'Angabe, ob die oberirdische Anlage im Wohnumfeld liegt und zugänglich ist; vom Planer nach Lage und Nutzung festgelegt. Wenn ja, prüft das Tool in der Anlagengeometrie (Phase 3), dass die Wassertiefe inklusive Freibord maximal 40 cm beträgt (in Anlehnung an DIN 18034-1:2020) und die Zugänglichkeit auf Bereiche ohne große Strömungen beschränkt ist. Starke Strömungen sind bei dezentralen Anlagen unwahrscheinlich, bei zentralen Bauwerken möglich (§ 5.3.5).
[EN] Whether the above-ground facility lies in residential surroundings and is accessible; set by the planner from location and use. If TRUE, the tool checks in the facility geometry (phase 3) that the water depth including freeboard is at most 40 cm (following DIN 18034-1:2020) and that access is limited to areas without strong currents. Strong currents are unlikely in decentralised facilities but can occur in central structures (§ 5.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'residential_accessibility';
UPDATE fields f SET description = 'Zeile „Hang“ der Tabelle 3, aus topografischer Karte/Geländemodell und Baugrundgutachten (Tab. 4): Anlage nicht in Hangnähe (Spalte 2); in Hangnähe, aber Hangrutschung oder Wasseraustritt unwahrscheinlich bzw. nicht nachteilig (Spalte 3); Hangrutschung oder nachteiliger Wasseraustritt wahrscheinlich (Spalte 4). In Gleichung A138-02-D1 ergibt „probable“ Code 3. In topografisch stark bewegtem Gelände, besonders bei deutlich geschichtetem Untergrund, ist mit erheblichen Einschränkungen zu rechnen (§ 5.1.1, Tab. 3).
[EN] ''Slope'' row of Table 3, from topographic map / terrain model and geotechnical report (Tab. 4): facility not near a slope (column 2); near a slope but sliding or emergence of infiltrated water unlikely or not adverse (column 3); sliding or adverse emergence likely (column 4). In equation A138-02-D1 ''probable'' yields code 3. In strongly undulating terrain, especially with markedly layered subsoil, considerable restrictions must be expected (§ 5.1.1, Tab. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'slope_risk';
UPDATE fields f SET description = 'Angabe, ob Niederschlagswasser direkt in das Grundwasser eingeleitet werden soll, z. B. über Brunnen, die den Sickerraum umgehen; aus dem Anlagenkonzept. Tor A138-REQ-COV-02 blockiert bei „ja“. Das direkte Einleiten in das Grundwasser ist nicht zulässig; Abweichungen sind im Einzelfall mit der Wasserbehörde zu klären (§ 5.2.1).
[EN] Whether rainwater is to be discharged directly into the groundwater, e.g. via wells that bypass the seepage zone; from the facility concept. Gate A138-REQ-COV-02 blocks on TRUE. Direct discharge into groundwater is not permitted; deviations must be clarified with the water authority case by case (§ 5.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'direct_gw_injection';
UPDATE fields f SET description = 'Vom Tool berechneter Vorschlag für die Spaltenlogik der Tabelle 3 (Gleichung A138-02-D1) aus den sieben Kriterienfeldern: 1 = alle Spalte-2-Kriterien erfüllt, 3 = ein Spalte-4-Kriterium trifft zu, 2 = sonst (nicht nachgewiesen möglich). Code 2 ist nicht gleich Spalte 3: Schutzgebiet mit nicht vernachlässigbarem Risiko und k_f < 1·10⁻⁶ m/s ohne Anschluss/Ableitung sind Spalte-4-Fälle, die hier in Code 2 fallen und gesondert zu beurteilen sind. feasibility_determination bleibt Entscheidung des Planers (§ 5.1.2, Tab. 3).
[EN] Tool-computed proposal for the column logic of Table 3 (equation A138-02-D1) from the seven criterion fields: 1 = all column-2 criteria met, 3 = a column-4 criterion applies, 2 = otherwise (not proven possible). Code 2 is not identical to column 3: a protection area with non-negligible risk and k_f < 1·10⁻⁶ m/s without connection/discharge are column-4 cases that land in code 2 and need separate judgement. feasibility_determination remains the planner''s decision (§ 5.1.2, Tab. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND f.symbol = 'feasibility_code';
UPDATE equations e SET description = 'Spaltenlogik der Tabelle 3 als Code: 1, wenn alle sieben Kriterien in Spalte 2 liegen (Sohlabstand ≥ 1 m, keine Altlasten, kein Schutzgebiet, k_f ≥ 1·10⁻⁶ m/s, keine geotechnische Gefährdung, Gebäudeabstand eingehalten, kein Hang); 3 bei einem Spalte-4-Kriterium; sonst 2. Vorschlag für feasibility_determination: Spalte 2 gilt nur mit Fachgutachten, Spalte 3 verlangt aufgezeigte Maßnahmen, Spalte 4 heißt in der Regel unzulässig (§ 5.1.2, Tab. 3).
[EN] Column logic of Table 3 as a code: 1 if all seven criteria fall in column 2 (base ≥ 1 m above MHGW, no contamination, no protection area, k_f ≥ 1·10⁻⁶ m/s, no geotechnical hazard, building distance kept, no slope); 3 for a column-4 criterion; otherwise 2. Proposal for feasibility_determination: column 2 counts only with expert reports, column 3 requires measures to be shown, column 4 means as a rule not permissible (§ 5.1.2, Tab. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-02' AND e.equation_number = 'A138-02-D1';
UPDATE fields f SET description = 'Bewertung, ob die Grundlagendaten nach Tabelle 4 (Boden/Untergrund inkl. k_f; Grundwasser inkl. Flurabstand und Fließrichtung; Topografie; Restriktionen wie Bauleitpläne, Altlastenkataster, Schutzgebiete; technische Machbarkeit wie Kataster- und Leitungsplan) vollständig, teilweise oder unzureichend vorliegen; vom Planer festgelegt. Steuert den Eintritt in Phase 2 und die Bewertung in A138-09. Spalte-2-Kriterien der Tabelle 3 gelten nur als nachgewiesen, wenn Fachgutachten vorliegen (§ 5.1.2, Tab. 3, Tab. 4).
[EN] Assessment of whether the basic data of Table 4 (soil/subsoil incl. k_f; groundwater incl. depth and flow direction; topography; restrictions such as land-use plans, contaminated-site register, protected areas; technical feasibility such as cadastral and utility plans) are complete, partial or insufficient; set by the planner. Controls entry to phase 2 and the assessment in A138-09. Column-2 criteria of Table 3 count as proven only with expert reports (§ 5.1.2, Tab. 3, Tab. 4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-03' AND f.symbol = 'data_completeness';
UPDATE fields f SET description = 'Methodenfaktor f_Methode nach Tabelle 11, aus permeability_test_method: Testgrube ≥ 1 m² = 1; Testgrube < 1 m² oder Doppelzylinder-Infiltrometer = 0,9; Open-End-Test = 0,8; Labor mit ungestörten Proben = 0,7; gestörte Proben/Sieblinie (Sandböden) = 0,1. Geht in A138-11 in f_K = f_Ort · f_Methode ≤ 1 (Gl. 6) und k_i = k_f · f_K (Gl. 5) ein. Für eine bewachsene Bodenzone nach § 5.2.3.2, angesetzt mit k_f 1·10⁻⁵ bis 5·10⁻⁵ m/s, entfällt f_Methode (§ 5.3.3.6, Tab. 11).
[EN] Method factor f_Methode per Table 11, from permeability_test_method: test pit ≥ 1 m² = 1; pit < 1 m² or double-cylinder infiltrometer = 0.9; open-end test = 0.8; laboratory on undisturbed samples = 0.7; disturbed samples / grading curve (sandy soils) = 0.1. Used in A138-11 in f_K = f_Ort · f_Methode ≤ 1 (Eq. 6) and k_i = k_f · f_K (Eq. 5). For a vegetated soil zone meeting § 5.2.3.2, set at k_f 1·10⁻⁵ to 5·10⁻⁵ m/s, f_Methode is neglected (§ 5.3.3.6, Tab. 11).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-03' AND f.symbol = 'f_methode';
UPDATE fields f SET description = 'Methode der k_f-Bestimmung (Feldversuch, Laborversuch, Korngrößenanalyse oder Literaturwert), aus dem Bodengutachten. Bestimmt f_Methode (Tab. 11); Tor A138-REQ-03 verlangt sie gemeinsam mit k_f. Nach Tab. A.1: Feldversuche (Doppelzylinder-Infiltrometer für oberirdische Anlagen, Bohrlochmethode für Rigolen/Schächte, Testgruben) mittlere bis hohe, Laborverfahren niedrige bis mittlere Ergebnisqualität; Sieblinien nur für Sandböden; Karten/Bodenansprache nur für die Ersteinschätzung, nicht für die Bemessung (Anh. A, Tab. A.1).
[EN] Method of k_f determination (field test, laboratory test, grain-size analysis or literature value), from the soil report. Determines f_Methode (Tab. 11); gate A138-REQ-03 requires it together with k_f. Per Tab. A.1: field tests (double-cylinder infiltrometer for above-ground facilities, borehole method for trenches/shafts, test pits) medium to high result quality, laboratory methods low to medium; grading curves for sandy soils only; maps/soil description for the initial assessment only, not for design (Annex A, Tab. A.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-03' AND f.symbol = 'permeability_test_method';
UPDATE fields f SET description = 'Bestätigung, dass die Regendaten zum gewählten Bemessungsverfahren passen: Einfaches Verfahren mit statistischen Starkregen (KOSTRA-DWD-2020 bzw. DWA-A 531, exakte DWD-Werte) und Regenhäufigkeit = Bemessungshäufigkeit; Nachweisverfahren mit kontinuierlichen Regenreihen ≥ 10 Jahre, Auflösung ≤ 5 min, Länge M ≥ 3 · T_n (Gl. 1). Tor A138-REQ-28 blockiert ohne Haken (§ 5.3.3.2, § 5.3.3.3, § 5.3.3.5, Tab. 12).
[EN] Attest that the rain data match the chosen design method: simple method with statistical heavy rain (KOSTRA-DWD-2020 or DWA-A 531, exact DWD values) and rain frequency = design frequency; verification method with continuous rainfall series ≥ 10 years, resolution ≤ 5 min, length M ≥ 3 · T_n (Eq. 1). Gate A138-REQ-28 blocks until ticked (§ 5.3.3.2, § 5.3.3.3, § 5.3.3.5, Tab. 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-04' AND f.symbol = 'attest_a138_04_a138_req_28';
UPDATE fields f SET description = 'Veröffentlichungs- bzw. Abrufdatum des verwendeten KOSTRA-Datensatzes, aus dem DWD-Atlas oder dem Datentool. Dokumentiert die Aktualität der Regenspenden in r_D_n_table; keine Rechenverwendung. Es sind KOSTRA-Datensätze in der jeweils gültigen Fassung zu verwenden; das Arbeitsblatt (2024) bezieht sich auf KOSTRA-DWD-2020 (2023) (§ 5.3.3.5).
[EN] Publication or retrieval date of the KOSTRA data set used, from the DWD atlas or the data tool. Documents how current the rainfall intensities in r_D_n_table are; not used in calculations. KOSTRA data sets must be used in their currently valid version; the standard (2024) refers to KOSTRA-DWD-2020 (2023) (§ 5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-04' AND f.symbol = 'kostra_data_date';
UPDATE fields f SET description = 'Tabelle der Regenspenden r_D(n) in l/(s·ha) je Dauerstufe D und Häufigkeit n für die KOSTRA-Rasterzelle des Standorts, aus KOSTRA-DWD-2020 oder örtlicher Auswertung nach DWA-A 531. Liefert r_D(n) für den Zufluss Q_zu = r_D(n) · (A_C + A_VA) · 10⁻⁴ (Gl. 3, A138-10) und die Iteration über alle Dauerstufen nach Gl. 8; der Überflutungsnachweis braucht r_D(30) (Gl. 10). Tor A138-REQ-05 verlangt Tabelle und Rasterzelle. Klimawandel ist in KOSTRA nicht abgebildet; ein Zuschlagsfaktor wird derzeit nicht vorgeschlagen (§ 5.3.3.5).
[EN] Table of rainfall intensities r_D(n) in l/(s·ha) per duration D and frequency n for the site''s KOSTRA grid cell, from KOSTRA-DWD-2020 or a local evaluation per DWA-A 531. Supplies r_D(n) for the inflow Q_zu = r_D(n) · (A_C + A_VA) · 10⁻⁴ (Eq. 3, A138-10) and for the iteration over all durations per Eq. 8; the flood proof needs r_D(30) (Eq. 10). Gate A138-REQ-05 requires table and grid cell. Climate change is not represented in KOSTRA; no surcharge factor is currently proposed (§ 5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-04' AND f.symbol = 'r_D_n_table';
UPDATE fields f SET description = 'Version des verwendeten KOSTRA-DWD-Atlas (z. B. KOSTRA-DWD-2020), wie vom DWD ausgewiesen. Dokumentationsfeld ohne Rechenverwendung. DWA-A 138-1:2024 bezieht sich auf KOSTRA-DWD-2020 (2023); zu verwenden ist die jeweils gültige Fassung (§ 5.3.3.5).
[EN] Version of the KOSTRA-DWD atlas used (e.g. KOSTRA-DWD-2020), as stated by the DWD. Documentation field, not used in calculations. DWA-A 138-1:2024 refers to KOSTRA-DWD-2020 (2023); the currently valid version must be used (§ 5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-04' AND f.symbol = 'a138_KOSTRA_DWD_Atlas';
UPDATE fields f SET description = 'Wiederkehrzeit T in Jahren, für die die Regenspende ausgelesen wird; Kehrwert der Bemessungshäufigkeit n aus A138-08 (T = 1/n, z. B. n = 0,2/a → T = 5 a). Dient dem Nachschlagen in r_D_n_table; im Einfachen Verfahren wird die Regenhäufigkeit gleich der Bemessungshäufigkeit gesetzt. Das Einfache Verfahren ist auf n ≥ 0,1/a, also T ≤ 10 a, begrenzt (§ 3.1 Begriffe; § 5.3.3.2, § 5.3.3.4).
[EN] Return period T in years for which the rainfall intensity is read; the reciprocal of the design frequency n from A138-08 (T = 1/n, e.g. n = 0.2/a → T = 5 a). Used to look up r_D_n_table; in the simple method the rain frequency is set equal to the design frequency. The simple method is limited to n ≥ 0.1/a, i.e. T ≤ 10 a (§ 3.1 terms; § 5.3.3.2, § 5.3.3.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-04' AND f.symbol = 'a138_jaehrlichkeit_T';
UPDATE fields f SET description = 'Dauerstufe D des Bemessungsregens in min, für die eine einzelne Regenspende ausgelesen wird. Für Anlagen mit Speicherfunktion ist D nicht frei wählbar, sondern wird iterativ bestimmt: Gl. (8) wird für alle Wertepaare D / r_D,n gerechnet, bis das eindeutige Maximum des Speichervolumens gefunden ist (A138-10 ff.). Bei Flächenversickerung ohne Speicherung gilt in der Regel D = 10 min, bei großen, flach geneigten Anschlussflächen bis 15 min; Behandlungsanlagen werden mit r_5,1 (D = 5 min) geprüft (§ 5.3.3.5, § 5.3.3.7, § 6.2.2).
[EN] Duration step D of the design rain in minutes for which a single rainfall intensity is read. For facilities with storage, D is not chosen freely but found by iteration: Eq. (8) is evaluated for all pairs D / r_D,n until the unique maximum of the storage volume is found (A138-10 ff.). For area infiltration without storage D = 10 min as a rule, up to 15 min for large, gently sloping connected areas; treatment units are checked with r_5,1 (D = 5 min) (§ 5.3.3.5, § 5.3.3.7, § 6.2.2, Tab. 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-04' AND f.symbol = 'a138_dauerstufe_D';
UPDATE fields f SET description = 'Regenspende r_D,T in l/(s·ha) für die gewählte Dauerstufe D und Wiederkehrzeit T, aus r_D_n_table (KOSTRA, exakte DWD-Werte) abgelesen. Dient als Kontroll- und Berichtswert; die Bemessung selbst liest r_D(n) für jede Dauerstufe aus der Tabelle (Gl. 3, Gl. 8). Die Regenspende fällt mit zunehmender Dauer; deshalb hat das erforderliche Volumen über D ein Maximum, das die maßgebende Dauer bestimmt (§ 5.3.3.5, § 5.3.3.7).
[EN] Rainfall intensity r_D,T in l/(s·ha) for the chosen duration D and return period T, read from r_D_n_table (KOSTRA, exact DWD values). Serves as a control and report value; the sizing itself reads r_D(n) for every duration from the table (Eq. 3, Eq. 8). Intensity decreases with duration, which is why the required volume over D has a maximum that defines the critical duration (§ 5.3.3.5, § 5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-04' AND f.symbol = 'a138_regenspende_r_DT';
UPDATE fields f SET description = 'Erforderlicher Mindestabstand a zwischen Anlagensohle und maßgeblichem MHGW in m, mit der Behörde festgelegt oder als Regelwert 1 m; Sollwert für gw_clearance (A138-02, Tor A138-REQ-04 ≥ 1,0 m). Festlegung nach Belastung und Menge des Zuflusses sowie Bodeneigenschaften; bei ≥ 1 m kann die Abstimmung in der Regel entfallen, in Trinkwasser-/Heilquellenschutzgebieten gelten weitergehende Anforderungen. Bei Bodenaustausch nach Bild 3 darf a ab Oberkante der ausgetauschten bzw. bewachsenen Bodenschicht gemessen werden (§ 5.2.1, § 5.3.1).
[EN] Required minimum distance a between facility base and governing MHGW in m, agreed with the authority or taken as the standard value of 1 m; target for gw_clearance (A138-02, gate A138-REQ-04 ≥ 1.0 m). Set according to load and quantity of inflow and soil properties; at ≥ 1 m the agreement can as a rule be omitted, in drinking-water/medicinal-spring protection areas further requirements apply. After soil replacement per Bild 3, a may be measured from the top of the replaced or vegetated soil layer (§ 5.2.1, § 5.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'clearance_a';
UPDATE fields f SET description = 'Durchlässigkeitsbeiwert k_f der maßgeblichen Bodenschicht (Anlagensohle) in m/s, aus Versuchen nach Anhang A; im Einfachen Verfahren der kleinste gemessene Wert (vgl. k_f_sites_min). Geht in k_i = k_f · f_K (Gl. 5, A138-11) ein; Tor A138-REQ-03 verlangt k_f mit Methode. Vollständige Versickerung in der Regel bei 1·10⁻⁶ bis 1·10⁻³ m/s; darunter ergänzende Ableitung oder Anschluss an durchlässige Schichten, darüber Stoffrückhalt mit der Behörde prüfen. Oberirdisch ist die geringere Durchlässigkeit von bewachsener Bodenzone und Untergrund maßgebend (§ 5.3.1, § 5.3.3.6).
[EN] Permeability coefficient k_f in m/s of the governing soil layer (facility base), from tests per Annex A; in the simple method the minimum measured value (see k_f_sites_min). Feeds k_i = k_f · f_K (Eq. 5, A138-11); gate A138-REQ-03 requires k_f with its method. Full infiltration as a rule at 1·10⁻⁶ to 1·10⁻³ m/s; below, add a supplementary discharge or connection to permeable layers; above, check substance retention with the authority. Above ground, the lower permeability of vegetated soil zone and subsoil governs (§ 5.3.1, § 5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'k_f';
UPDATE fields f SET description = 'Vom Tool gesetzt: PASS, wenn kf_test_sites_count die Mindestanzahl nach § 5.3.3.6 erreicht: mindestens ein Versuchsstandort je 150 m² Sohlenfläche; bei Anlagenlänge über 10 m und heterogenem Boden mindestens ein weiterer; bei größeren Anlagen mindestens alle 25 m Anlagenlänge. Standorte so verteilen, dass unterschiedliche Untergrundverhältnisse erfasst werden; bei großer Heterogenität Abstand verringern. Das Ergebnis stützt die Wahl von f_Ort in A138-08 (Tab. 10: Anzahl der Versuche vs. Variabilität) (§ 5.3.3.6).
[EN] Set by the tool: PASS if kf_test_sites_count meets the minimum of § 5.3.3.6: at least one test location per 150 m² of base area; if the facility is longer than 10 m in heterogeneous soil at least one more; for larger facilities at least every 25 m of facility length. Distribute locations to capture different subsoil conditions; with high heterogeneity reduce the spacing. The result supports the choice of f_Ort in A138-08 (Tab. 10: number of tests vs. variability) (§ 5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'kf_test_density_check';
UPDATE fields f SET description = 'Anzahl der Versuchsstandorte/Probenahmestellen für k_f, aus dem Bodengutachten. Wird in kf_test_density_check mit den Mindestanforderungen verglichen: ≥ 1 je 150 m² Sohlenfläche, ≥ 1 weiterer bei Länge > 10 m und heterogenem Boden, mindestens alle 25 m Anlagenlänge. Die Zahl der Versuche im Verhältnis zur Variabilität des Bodens ist ein Kriterium der Tabelle 10 für f_Ort (0,3 bis 1,0) (§ 5.3.3.6, Tab. 10).
[EN] Number of k_f test locations / sampling points, from the soil report. Compared in kf_test_density_check with the minimum requirements: ≥ 1 per 150 m² of base area, ≥ 1 more if length > 10 m in heterogeneous soil, at least every 25 m of facility length. The number of tests relative to the soil''s variability is a Table 10 criterion for f_Ort (0.3 to 1.0) (§ 5.3.3.6, Tab. 10).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'kf_test_sites_count';
UPDATE fields f SET description = 'Vom Tool gesetzt: TRUE, wenn k_f > 1·10⁻³ m/s. Über dieser Grenze ist Versickerung möglich, aber die Notwendigkeit zusätzlicher Maßnahmen zum Stoffrückhalt ist im Einzelfall zu prüfen und mit der Genehmigungsbehörde abzustimmen (authority_coordination_required). Beim Sickerschacht Typ B wechselt die Bemessung dann auf Gl. (40) mit der Filtersandschicht (§ 5.3.1, § 6.7.2). Nach Bild 2 liegen Kies und Teile sandiger Kiese in diesem Bereich.
[EN] Set by the tool: TRUE if k_f > 1·10⁻³ m/s. Above this limit infiltration is possible, but the need for additional measures to retain substances must be checked case by case and agreed with the approving authority (authority_coordination_required). For infiltration shaft type B the design then switches to Eq. (40) with the filter sand layer (§ 5.3.1, § 6.7.2). Per Bild 2, gravel and parts of sandy gravel lie in this range.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'kf_too_high_flag';
UPDATE fields f SET description = 'Mittlerer höchster Grundwasserstand MHGW in m NHN: arithmetisches Mittel der Jahreshöchstwerte mehrerer Jahre mit Angabe des Zeitraums; aus Grundwassermessstellen, Gleichenplänen oder hydrogeologischen Gutachten der Fachbehörden und Wasserversorger (Tab. 4). Das Tool bildet daraus gw_clearance = Sohlhöhe − MHGW (A138-02, Tor ≥ 1,0 m). Eine Einzelmessung ersetzt den MHGW nicht; Beobachtungen Februar bis April sind besonders wertvoll, Schichtenwasser ist zu prüfen (§ 3.1, § 5.1.1).
[EN] Mean highest groundwater level MHGW in m NHN: arithmetic mean of the annual maxima of several years with the period stated; from observation wells, contour maps or hydrogeological reports of the specialist authorities and water suppliers (Tab. 4). The tool forms gw_clearance = base level − MHGW (A138-02, gate ≥ 1.0 m). A single reading does not replace the MHGW; observations from February to April are especially valuable, and perched water must be checked (§ 3.1, § 5.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'mhgw';
UPDATE fields f SET description = 'Bodenart/Bodenklassifikation der maßgeblichen Schicht nach Bodenkarte (z. B. BÜK 50) bzw. Bodenansprache nach DIN EN ISO 14688-1 / DIN 18196, aus dem Bodengutachten. Dokumentiert, welche Schicht k_f beschreibt, und erlaubt die Plausibilitätsprüfung gegen Bild 2 (Durchlässigkeitsbereiche von Ton bis Kies). Eine Zuordnung allein aus der Bodenansprache ist als Grundlage für den Bemessungswert ausgeschlossen (Unsicherheit mehrere Größenordnungen) (§ 5.3.1, Anh. A, Tab. A.1).
[EN] Soil type / classification of the governing layer per soil map (e.g. BÜK 50) or soil description per DIN EN ISO 14688-1 / DIN 18196, from the soil report. Documents which layer k_f describes and allows a plausibility check against Bild 2 (permeability ranges from clay to gravel). A value assigned from the soil description alone is excluded as the basis for the design value (uncertainty of several orders of magnitude) (§ 5.3.1, Annex A, Tab. A.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'soil_classification';
UPDATE fields f SET description = 'Register der k_f-Versuchsstandorte: je Zeile Lage/Tiefe, Verfahren nach Tabelle 11 und gemessener k_f. Das Tool bildet daraus mit Gleichung A138-05-D1 das Minimum k_f_sites_min; die Anzahl der Zeilen entspricht kf_test_sites_count. Versuche sind in der Schicht durchzuführen, durch die das Wasser versickert (Anlagensohle), und über den Standort so zu verteilen, dass unterschiedliche Untergrundverhältnisse erfasst werden (§ 5.3.3.6, Anh. A).
[EN] Register of k_f test locations: per row position/depth, method per Table 11 and measured k_f. The tool derives the minimum k_f_sites_min with equation A138-05-D1; the number of rows corresponds to kf_test_sites_count. Tests must be made in the layer through which the water infiltrates (facility base) and distributed over the site to capture different subsoil conditions (§ 5.3.3.6, Annex A).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'kf_test_sites';
UPDATE fields f SET description = 'Register des geschichteten Bodenprofils: je Zeile Tiefe, Bodenart, k_f und Kennzeichen, ob es die bewachsene Bodenzone ist. Das Tool bildet mit Gleichung A138-05-D3 das Minimum k_f_layer_min. Bei geschichteten Profilen sind die maßgeblichen Bodenschichten zur Festlegung der Bemessungs-Infiltrationsrate zu wählen; für zentrale Anlagen im Bodengutachten auszuweisen, für dezentrale empfohlen. Bei oberirdischen Anlagen ist die bewachsene Bodenzone einzubeziehen; die jeweils geringere Durchlässigkeit ist maßgebend (§ 5.3.1).
[EN] Register of the layered soil profile: per row depth, soil type, k_f and a flag for the vegetated soil zone. The tool derives the minimum k_f_layer_min with equation A138-05-D3. For layered profiles the governing soil layers must be chosen to fix the design infiltration rate; stated in a soil report for central facilities, recommended for decentralised ones. For above-ground facilities the vegetated soil zone must be included; the lower permeability governs (§ 5.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'soil_layers';
UPDATE fields f SET description = 'Vom Tool berechnet (A138-05-D1): kleinster gemessener k_f über alle Zeilen von kf_test_sites in m/s. Im Einfachen Verfahren wird auf der sicheren Seite der minimale Wert als k_f angesetzt; die Übernahme in k_f ist derzeit nicht automatisiert. Weicht ein Standort stark ab, deutet das auf Heterogenität hin: Versuchsabstand verringern und f_Ort entsprechend niedriger wählen (§ 5.3.3.6, Tab. 10).
[EN] Computed by the tool (A138-05-D1): lowest measured k_f over all rows of kf_test_sites in m/s. In the simple method the minimum value is used as k_f on the safe side; transfer into k_f is not yet automated. A strongly deviating location indicates heterogeneity: reduce test spacing and choose a lower f_Ort accordingly (§ 5.3.3.6, Tab. 10).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'k_f_sites_min';
UPDATE fields f SET description = 'Vom Tool berechnet (A138-05-D3): geringste Durchlässigkeit über alle Zeilen von soil_layers in m/s. Kandidat für die maßgebliche Bodenschicht: Das Wasser muss alle Schichten nacheinander passieren, die geringste Durchlässigkeit ist maßgebend; bei oberirdischen Anlagen ist das häufig die bewachsene Bodenzone (ansetzbar mit 1·10⁻⁵ bis 5·10⁻⁵ m/s ohne f_Methode, wenn § 5.2.3.2 und Bild 1 erfüllt sind). Mit f_K ergibt sich daraus k_i (Gl. 5, A138-11) (§ 5.3.1, § 5.3.3.6).
[EN] Computed by the tool (A138-05-D3): lowest permeability over all rows of soil_layers in m/s. Candidate for the governing soil layer: water must pass all layers in series and the lower permeability governs; for above-ground facilities this is often the vegetated soil zone (may be set at 1·10⁻⁵ to 5·10⁻⁵ m/s without f_Methode if § 5.2.3.2 and Bild 1 are met). With f_K it gives k_i (Eq. 5, A138-11) (§ 5.3.1, § 5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND f.symbol = 'k_f_layer_min';
UPDATE equations e SET description = 'Minimum des gemessenen k_f über alle Versuchsstandorte des Registers kf_test_sites. Das Ergebnis ist der auf der sicheren Seite liegende Bodenwert für das Einfache Verfahren (der minimale Wert der Infiltrationsrate wird als k_f-Wert angesetzt) und soll mit k_f übereinstimmen; es ist noch kein Bemessungswert – dieser entsteht erst mit f_K in Gl. (5) (§ 5.3.3.6).
[EN] Minimum of the measured k_f over all test locations in the kf_test_sites register. The result is the safe-side soil value for the simple method (the minimum infiltration rate is used as the k_f value) and should match k_f; it is not yet the design value, which arises only with f_K in Eq. (5) (§ 5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND e.equation_number = 'A138-05-D1';
UPDATE equations e SET description = 'Minimum der Durchlässigkeit über alle Schichten des Registers soil_layers. Das Ergebnis benennt die maßgebliche Bodenschicht nach § 5.3.1: Die jeweils geringere Durchlässigkeit von bewachsener Bodenzone und Untergrund ist maßgebend, da das Wasser alle Schichten in Reihe durchströmen muss. Es soll ≥ 1·10⁻⁶ m/s liegen, damit vollständige Versickerung in der Regel möglich ist; sonst Anschluss an durchlässige Schichten (Bild 3) oder ergänzende Ableitung (§ 5.3.1).
[EN] Minimum permeability over all layers of the soil_layers register. The result names the governing soil layer per § 5.3.1: the lower permeability of vegetated soil zone and subsoil governs, since water must pass all layers in series. It should be ≥ 1·10⁻⁶ m/s for full infiltration to be possible as a rule; otherwise connect to permeable layers (Bild 3) or add a supplementary discharge (§ 5.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-05' AND e.equation_number = 'A138-05-D3';
UPDATE fields f SET description = 'Vom Tool gesetzt: PASS, wenn der k_f der bewachsenen Bodenzone (BBZ) ≤ 1·10⁻⁴ m/s ist (Bestimmung nach Anhang A, Tab. A.1). Die Obergrenze ist eine Qualitätsgrenze: Bei höherer Durchlässigkeit ist die Kontaktzeit in der 20–30 cm dicken Schicht zu kurz für Filtration und Adsorption. Die Mindestdurchlässigkeit ergibt sich aus § 5.3.1 bzw. der hydraulischen Bemessung; die BBZ darf mit k_f 1·10⁻⁵ bis 5·10⁻⁵ m/s angesetzt werden, wenn § 5.2.3.2 und Bild 1 erfüllt sind (§ 5.2.3.2, § 5.3.3.6).
[EN] Set by the tool: PASS if the k_f of the vegetated soil zone (BBZ) is ≤ 1·10⁻⁴ m/s (determined per Annex A, Tab. A.1). The upper limit is a quality limit: at higher permeability the contact time in the 20–30 cm layer is too short for filtration and adsorption. The minimum permeability follows from § 5.3.1 or the hydraulic sizing; the BBZ may be set at k_f 1·10⁻⁵ to 5·10⁻⁵ m/s if § 5.2.3.2 and Bild 1 are met (§ 5.2.3.2, § 5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'bbz_kf_max_check';
UPDATE fields f SET description = 'Massenanteil organischer Substanz des BBZ-Bodens in %, bestimmt nach DIN EN 17685-1:2023 (Laboranalyse des vorgesehenen Oberbodens; Oberboden vom Standort soll bevorzugt verwendet werden). Das Tool prüft den empfohlenen Bereich 1 % bis 4 %. Der Humusgehalt ist nach § 5.2.1 neben Ton-/Schluffanteil und pH ein wesentlicher Faktor für den Rückhalt gelöster Stoffe durch Adsorption (§ 5.2.1, § 5.2.3.2).
[EN] Organic matter mass fraction of the BBZ soil in %, determined per DIN EN 17685-1:2023 (laboratory analysis of the intended topsoil; on-site topsoil should be used where possible). The tool checks the recommended range 1 % to 4 %. Per § 5.2.1 the humus content is, with clay/silt content and pH, a key factor for retaining dissolved substances by adsorption (§ 5.2.1, § 5.2.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'bbz_organisch';
UPDATE fields f SET description = 'pH-Wert des BBZ-Bodens, bestimmt nach DIN EN ISO 10390:2022 (Laboranalyse). Das Tool prüft den empfohlenen Bereich pH 6 bis 8. Der pH ist nach § 5.2.1 neben Humus- und Ton-/Schluffanteil ein wesentlicher Einflussfaktor für den Rückhalt gelöster Stoffe (§ 5.2.1, § 5.2.3.2).
[EN] pH value of the BBZ soil, determined per DIN EN ISO 10390:2022 (laboratory analysis). The tool checks the recommended range pH 6 to 8. Per § 5.2.1 the pH is, alongside humus and clay/silt content, a key factor for retaining dissolved substances (§ 5.2.1, § 5.2.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'bbz_ph';
UPDATE fields f SET description = 'Schlämmkornanteil (Ton + Schluff, < 0,063 mm) des BBZ-Bodens in Massen-%, aus der Körnungsanalyse. Das Tool prüft ≤ 20 % (entspricht dem Punkt 20 % bei 0,063 mm des Bands in Bild 1). Zusätzlich muss die gesamte Sieblinie im maßgebenden Band liegen: Band 1 für BK III, BF, BL und SD1; Band 2 zusätzlich für BK I, VW2, V2 und BG2 (§ 5.2.3.2, Bild 1).
[EN] Fines content (clay + silt, < 0.063 mm) of the BBZ soil in mass %, from the grain-size analysis. The tool checks ≤ 20 % (the 20 % point at 0.063 mm of the Bild 1 band). In addition the whole grading curve must lie within the relevant band: band 1 for BK III, BF, BL and SD1; band 2 additionally for BK I, VW2, V2 and BG2 (§ 5.2.3.2, Bild 1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'bbz_schlaemmkorn';
UPDATE fields f SET description = 'Mächtigkeit der bewachsenen Bodenzone in m, gemessen nach Setzung der Schicht (nach Abschluss der Bauarbeiten); aus Planung bzw. Abnahme. Das Tool prüft die Mindestmächtigkeit nach Tabelle 6 (≥ 20 cm oder ≥ 30 cm) und wählt damit die Spalte für die zulässige Flächenbelastung A_C/A_S,m: BK II ≤ 30 (20 cm) bzw. ≤ 50 (30 cm); BL, V3, BG3 ≤ 15 bzw. ≤ 30; BK I ohne Anforderung an A_C/A_S,m. Filterstabilität zur nächsten Bodenschicht sicherstellen; vor Inbetriebnahme begrünen (§ 5.2.3.2, Tab. 6).
[EN] Thickness of the vegetated soil zone in m, measured after settlement of the layer (after completion of construction); from design or acceptance. The tool checks the minimum thickness per Table 6 (≥ 20 cm or ≥ 30 cm) and uses it to select the column for the permitted load ratio A_C/A_S,m: BK II ≤ 30 (20 cm) or ≤ 50 (30 cm); BL, V3, BG3 ≤ 15 or ≤ 30; BK I no requirement on A_C/A_S,m. Ensure filter stability to the next soil layer; green the zone before commissioning (§ 5.2.3.2, Tab. 6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'bbz_thickness';
UPDATE fields f SET description = 'Belastungskategorie nach Tabelle 5 (Referenzparameter AFS63): BK I gering (D, VW1, V1, BG1), BK II mäßig (VW2, V2, BF, BL, BG2, SD1), BK III stark (V3, SD2, SV/SVW, SF, SL, BG3, SG, SA). Wird aus flaechengruppe gefüllt, nicht getippt; Tor A138-REQ-07 verlangt die Zuordnung; bei mehreren Flächen an einer Anlage gilt die strengste. Wählt die Zeile in Tabelle 6 (Mächtigkeit, A_C/A_S,m) bzw. Tabelle 7 (Wirkungsgrade). Abweichungen von Tabelle 5 sind zu begründen; die Einschätzung bedarf der Prüfung durch die Wasserbehörde (§ 5.2.2, Tab. 5).
[EN] Pollution category per Table 5 (reference parameter AFS63): BK I slight (D, VW1, V1, BG1), BK II moderate (VW2, V2, BF, BL, BG2, SD1), BK III heavy (V3, SD2, SV/SVW, SF, SL, BG3, SG, SA). Filled from flaechengruppe, not typed; gate A138-REQ-07 requires the assignment; with several surfaces on one facility the strictest applies. Selects the row in Table 6 (thickness, A_C/A_S,m) or Table 7 (efficiencies). Deviations from Table 5 need justification; the assessment needs the water authority''s check (§ 5.2.2, Tab. 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'belastungskategorie';
UPDATE fields f SET description = 'Gesamtwirkungsgrad der dezentralen Behandlungsanlage für AFS63 (abfiltrierbare Stoffe 0,45–63 µm) in %, bei Bemessung und Betrieb; aus der bauaufsichtlichen Zulassung (DIBt) oder einem DIBt-vergleichbaren Test einer anerkannten Prüfstelle, mit Konformitätsbescheinigung. Erforderlich bei unterirdischen Anlagen; Vergleich mit eta_afs63_required (Tab. 7: BK I 40 %, BK II 70 %, BL/V3/BG3 80 %). Bezug ist r_krit = 25 l/(s·ha); DIBt-zugelassene Anlagen erreichen rechnerisch ca. 80 % (§ 5.2.3.3, Tab. 7).
[EN] Overall efficiency of the decentralised treatment unit for AFS63 (filterable solids 0.45–63 µm) in %, at design and in operation; from the building-authority approval (DIBt) or a DIBt-comparable test by a recognised test body, with a declaration of conformity. Required for underground facilities; compared with eta_afs63_required (Tab. 7: BK I 40 %, BK II 70 %, BL/V3/BG3 80 %). Reference is r_krit = 25 l/(s·ha); DIBt-approved units reach about 80 % by calculation (§ 5.2.3.3, Tab. 7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'eta_AFS63';
UPDATE fields f SET description = 'Gesamtwirkungsgrad der Behandlungsanlage für gelöste Stoffe in %, ausschließlich bezogen auf die Referenzparameter Kupfer und Zink (Tab. 7, Anm. **); aus Zulassung oder anerkanntem Test wie bei eta_AFS63. Erforderlich bei unterirdischen Anlagen; Vergleich mit eta_geloest_required (BK I 50 %, BK II 65 %, BL/V3/BG3 75 %). Bei Flächen der Gruppen B und S sind neben partikulären besonders gelöste Schadstoffe zu berücksichtigen (Tab. 5, Anm. 10) (§ 5.2.3.3, Tab. 7).
[EN] Overall efficiency of the treatment unit for dissolved substances in %, referring exclusively to the reference parameters copper and zinc (Tab. 7, note **); from approval or recognised test as for eta_AFS63. Required for underground facilities; compared with eta_geloest_required (BK I 50 %, BK II 65 %, BL/V3/BG3 75 %). For surfaces of groups B and S, dissolved pollutants must be considered in particular besides particle-bound ones (Tab. 5, note 10) (§ 5.2.3.3, Tab. 7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'eta_geloest';
UPDATE fields f SET description = 'Kritische Regenspende für die Bemessung der dezentralen Behandlungsanlage in l/(s·ha); Festwert 25 l/(s·ha) analog DIBt 2017, auf den sich die Wirkungsgrade der Tabelle 7 beziehen. Mit A_C ergibt sich daraus der Bemessungszufluss der Behandlung. Im Betrieb soll die Anlage eine höhere hydraulische Leistung (z. B. 100 l/(s·ha) oder r_5,1) ohne Remobilisierung zurückgehaltener Stoffe gewährleisten; höhere Zuflüsse sind über Rückstau, Leitungsdimensionierung, Vorspeicher oder erkennbaren Notüberlauf zu regeln (§ 5.2.3.3).
[EN] Critical rainfall intensity for sizing the decentralised treatment unit in l/(s·ha); fixed value 25 l/(s·ha) analogous to DIBt 2017, to which the Table 7 efficiencies refer. With A_C it yields the design flow of the treatment unit. In operation the unit should ensure a higher hydraulic capacity (e.g. 100 l/(s·ha) or r_5,1) without remobilising retained substances; higher inflows must be controlled by backwater, pipe sizing, upstream storage or a noticeable emergency overflow (§ 5.2.3.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'r_krit';
UPDATE fields f SET description = 'Vom Tool gesetzt: PASS, wenn eta_AFS63 ≥ eta_afs63_required und eta_geloest ≥ eta_geloest_required für die maßgebende Belastungskategorie (Tab. 7); gilt für unterirdische Anlagen mit vorgeschalteter dezentraler Behandlung. Für D, SD1, SD2, SV, SVW, SF, SL, SG und SA (Anm. *) gelten die rechtlichen Vorgaben, abzustimmen mit der Behörde; die Prüfung liefert dann kein Ergebnis. Flächen mit unterschiedlichen Anforderungen an dieselbe Behandlungsanlage anzuschließen ist in der Regel nicht sinnvoll (§ 5.2.3.3, Tab. 7).
[EN] Set by the tool: PASS if eta_AFS63 ≥ eta_afs63_required and eta_geloest ≥ eta_geloest_required for the governing pollution category (Tab. 7); applies to underground facilities with an upstream decentralised treatment unit. For D, SD1, SD2, SV, SVW, SF, SL, SG and SA (note *) the legal provisions apply, agreed with the authority; the check then gives no result. Connecting surfaces with different requirements to the same treatment unit is as a rule not sensible (§ 5.2.3.3, Tab. 7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'treatment_efficiency_check';
UPDATE fields f SET description = 'Festlegung, ob eine Niederschlagswasserbehandlung erforderlich ist; vom Planer aus Anlagentyp und Belastungskategorie abgeleitet. Bei oberirdischen Anlagen gilt die Versickerung durch die bewachsene Bodenzone selbst als Behandlungsmaßnahme (Tab. 6: Mächtigkeit, A_C/A_S,m); bei unterirdischen Anlagen sind dezentrale Behandlungsanlagen vorzuschalten (Tab. 7). Oberirdische Anlagen sind grundsätzlich vorzuziehen. Steuert, welche der Felder bbz_* bzw. eta_* das Tool prüft (§ 5.2.3.2, § 5.2.3.3).
[EN] Whether rainwater treatment is required; derived by the planner from facility type and pollution category. For above-ground facilities, infiltration through the vegetated soil zone itself counts as the treatment measure (Tab. 6: thickness, A_C/A_S,m); for underground facilities decentralised treatment units must be installed upstream (Tab. 7). Above-ground facilities are to be preferred in principle. Controls which of the bbz_* or eta_* fields the tool checks (§ 5.2.3.2, § 5.2.3.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'treatment_required';
UPDATE fields f SET description = 'Flächengruppe nach Tabelle 5 für die maßgebende angeschlossene Fläche: D Dächer; VW1/VW2 Hof- und Wegeflächen; V1/V2/V3 Verkehrsflächen nach DTV (V1 ≤ 300 Kfz/d; V2 300–15 000 Kfz/d außerhalb bzw. ≤ 2 000 innerhalb von Misch-/Gewerbe-/Industriegebieten; V3 darüber); BG Gleise; BF Flughafen; BL Landwirtschaft; SD1/SD2 Dächer mit 20–70 % bzw. > 70 % belastender Materialien (inkl. Rinnen, Fallrohre); S-Gruppen mit besonderer Belastung. Füllt belastungskategorie und a138_tier. Nicht aufgeführte Flächen analog einstufen (§ 5.2.2, Tab. 5).
[EN] Surface group per Table 5 for the governing connected surface: D roofs; VW1/VW2 yard and path areas; V1/V2/V3 traffic areas by DTV (V1 ≤ 300 veh/d; V2 300–15 000 veh/d outside or ≤ 2 000 inside mixed/commercial/industrial areas; V3 above); BG tracks; BF airport; BL agriculture; SD1/SD2 roofs with 20–70 % or > 70 % polluting materials (incl. gutters, downpipes); S groups with special loads. Fills belastungskategorie and a138_tier. Classify surfaces not listed analogously (§ 5.2.2, Tab. 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'flaechengruppe';
UPDATE fields f SET description = 'Anforderungsstufe für die Zeilenwahl in Tabelle 6 und 7, vom Tool aus flaechengruppe gefüllt, nie getippt: tier1_none = VW1, V1, BG1 (BK I: keine Anforderung an A_C/A_S,m; η 40 %/50 %); tier2 = VW2, V2, BF, BG2 (A_C/A_S,m ≤ 30/50; η 70 %/65 %); tier3 = BL, V3, BG3 (A_C/A_S,m ≤ 15/30; η 80 %/75 %); authority = D, SD1, SD2, SV/SVW, SF, SL, SG, SA (Anm. *: rechtliche Vorgaben, Abstimmung mit der Behörde). BL ist BK II, steht in Tab. 6/7 aber in der strengeren Zeile (§ 5.2.3.2, Tab. 6; § 5.2.3.3, Tab. 7).
[EN] Requirement tier for selecting the row in Tables 6 and 7, filled by the tool from flaechengruppe, never typed: tier1_none = VW1, V1, BG1 (BK I: no requirement on A_C/A_S,m; η 40 %/50 %); tier2 = VW2, V2, BF, BG2 (A_C/A_S,m ≤ 30/50; η 70 %/65 %); tier3 = BL, V3, BG3 (A_C/A_S,m ≤ 15/30; η 80 %/75 %); authority = D, SD1, SD2, SV/SVW, SF, SL, SG, SA (note *: legal provisions, agree with the authority). BL is BK II but sits in the stricter row of Tab. 6/7 (§ 5.2.3.2, Tab. 6; § 5.2.3.3, Tab. 7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'a138_tier';
UPDATE fields f SET description = 'Erforderlicher Gesamtwirkungsgrad η_AFS63 nach Tabelle 7, vom Tool aus a138_tier gefüllt: VW1/V1/BG1 40 %, VW2/V2/BF/BG2 70 %, BL/V3/BG3 80 %; D- und S-Gruppen (Anm. *) nach rechtlichen Vorgaben/Behörde. Sollwert für eta_AFS63 bei unterirdischen Anlagen (Prüfung in treatment_efficiency_check); Bezug r_krit = 25 l/(s·ha). Bei BK I gilt ein Sickerschacht Typ B mit Filtersandschicht und vorgeschaltetem Absetzschacht (Oberflächenbeschickung 10 m/h, Horizontalgeschwindigkeit 0,05 m/s) als nachgewiesen (§ 5.2.3.3, Tab. 7).
[EN] Required overall efficiency η_AFS63 per Table 7, filled by the tool from a138_tier: VW1/V1/BG1 40 %, VW2/V2/BF/BG2 70 %, BL/V3/BG3 80 %; D and S groups (note *) follow legal provisions/authority. Target for eta_AFS63 in underground facilities (checked in treatment_efficiency_check); reference r_krit = 25 l/(s·ha). For BK I a type B shaft with filter sand layer and upstream settling shaft (surface loading 10 m/h, horizontal velocity 0.05 m/s) counts as proven (§ 5.2.3.3, Tab. 7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'eta_afs63_required';
UPDATE fields f SET description = 'Erforderlicher Gesamtwirkungsgrad für gelöste Stoffe (nur Referenzparameter Kupfer und Zink) nach Tabelle 7, vom Tool aus a138_tier gefüllt: VW1/V1/BG1 50 %, VW2/V2/BF/BG2 65 %, BL/V3/BG3 75 %; D- und S-Gruppen (Anm. *) nach rechtlichen Vorgaben/Behörde. Sollwert für eta_geloest bei unterirdischen Anlagen (Prüfung in treatment_efficiency_check). Ab BK II z. B. Behandlungsanlage mit bauaufsichtlicher Zulassung (DIBt); Sicherheitsaspekte wie Tauchwand, Absperrschieber, Beprobung im Einzelfall mit der Behörde (§ 5.2.3.3, Tab. 7).
[EN] Required overall efficiency for dissolved substances (reference parameters copper and zinc only) per Table 7, filled by the tool from a138_tier: VW1/V1/BG1 50 %, VW2/V2/BF/BG2 65 %, BL/V3/BG3 75 %; D and S groups (note *) follow legal provisions/authority. Target for eta_geloest in underground facilities (checked in treatment_efficiency_check). From BK II e.g. a unit with building-authority approval (DIBt); safety aspects such as submerged baffle, shut-off valve, sampling case by case with the authority (§ 5.2.3.3, Tab. 7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-06' AND f.symbol = 'eta_geloest_required';
UPDATE fields f SET description = 'Vom Tool gesetzt: TRUE, wenn der Rechenwert A_C als Summe aller abflusswirksamen Flächen des Grundstücks > 800 m² ist. Dann ist für innerörtliche Grundstücke ein Überflutungsnachweis nach DIN 1986-100 zu führen (Gl. 10 in A138-26; in der Regel T_n = 30 a, bei > 70 % Dach- und nicht überflutbaren Flächen T_n = 100 a) mit schadlosem Verbleib der Rückhaltemenge auf dem Grundstück. Bei A_C ≤ 800 m² ist kein rechnerischer Nachweis nötig, dafür gilt in Tabelle 8 die strengere Bemessungshäufigkeit (Anm. a) (§ 5.3.4.1, § 5.3.3.4).
[EN] Set by the tool: TRUE if the design value A_C, as the sum of all runoff-effective areas of the plot, exceeds 800 m². Then a flood proof per DIN 1986-100 is required for plots inside settlements (Eq. 10 in A138-26; as a rule T_n = 30 a, T_n = 100 a if > 70 % roofs and non-floodable areas) and harmless retention on the plot must be shown. At A_C ≤ 800 m² no calculated proof is needed, but Table 8 then applies the stricter design frequency (note a) (§ 5.3.4.1, § 5.3.3.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND f.symbol = 'flood_check_trigger';
UPDATE fields f SET description = 'Verzeichnis aller angeschlossenen Teilflächen: je Zeile Art (befestigt/unbefestigt), Nutzung, Fläche in m², Abflussbeiwert C_i (C_m nach Tab. 9, für Gl. 2) und Spitzenbeiwert C_s (Überflutungsnachweis, Gl. 10). Das Tool bildet daraus A_C, C_m, A_E,b,a, A_E,nb,a und die reduzierten Flächen; Tor A138-REQ-06 verlangt das Verzeichnis. Beiwerte an Ort und Bemessungshäufigkeit anpassen; für durchlässige Flächen je nach Untergrund und Gefälle Abweichung von Tab. 9 zulässig. Nur Flächen zählen, die potenziell zur Anlage entwässern (§ 5.3.3.5, Tab. 9 Anm. a).
[EN] Inventory of all connected sub-areas: per row kind (paved/unpaved), use, area in m², runoff coefficient C_i (C_m per Tab. 9, for Eq. 2) and peak coefficient C_s (flood proof, Eq. 10). The tool derives A_C, C_m, A_E,b,a, A_E,nb,a and the reduced areas; gate A138-REQ-06 requires the inventory. Adapt coefficients to site and design frequency; for permeable surfaces deviation from Tab. 9 is allowed depending on subsoil and slope. Only areas that potentially drain to the facility count (§ 5.3.3.5, Tab. 9 note a).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND f.symbol = 'surface_inventory';
UPDATE fields f SET description = 'Vom Tool berechnet (Gl. 2): Rechenwert A_C in m² – alle angeschlossenen Teilflächen, gewichtet mit ihren Abflussbeiwerten. Geht in den Zufluss Q_zu (Gl. 3, A138-10), die Bemessungsgleichung (Gl. 8), q_S,AC (Gl. 9), die Flächenbelastung A_C/A_S,m (Tab. 6, A138-12) und die Spaltenwahl in Tabelle 8 (≤/> 800 m²) ein; A_C > 800 m² löst den Überflutungsnachweis aus (§ 5.3.3.5, § 5.3.4.1). Für oberirdische Anlagen kommt im Zufluss die überregnete Fläche A_VA hinzu (Gl. 3).
[EN] Computed by the tool (Eq. 2): design value A_C in m² – all connected sub-areas weighted by their runoff coefficients. Feeds the inflow Q_zu (Eq. 3, A138-10), the sizing equation (Eq. 8), q_S,AC (Eq. 9), the load ratio A_C/A_S,m (Tab. 6, A138-12) and the column choice in Table 8 (≤/> 800 m²); A_C > 800 m² triggers the flood proof (§ 5.3.3.5, § 5.3.4.1). For above-ground facilities the rained-on area A_VA is added in the inflow (Eq. 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND f.symbol = 'A_C';
UPDATE fields f SET description = 'Vom Tool berechnet (Gl. 2c): flächengewichteter mittlerer Abflussbeiwert aller angeschlossenen Flächen, dimensionslos. Kontrollwert: Er zeigt, wie stark versiegelt das Einzugsgebiet im Mittel ist, und muss zwischen dem kleinsten und größten C_i des Verzeichnisses liegen. Die Bemessung mit dem mittleren Abflussbeiwert ist im Einfachen Verfahren in der Regel bis zu Bemessungshäufigkeiten ≥ 0,1/a möglich (§ 3.1 Begriffe; § 5.3.3.5, Tab. 9).
[EN] Computed by the tool (Eq. 2c): area-weighted mean runoff coefficient of all connected surfaces, dimensionless. Control value: it shows how strongly the catchment is sealed on average and must lie between the smallest and largest C_i of the inventory. Sizing with the mean runoff coefficient is as a rule possible in the simple method up to design frequencies ≥ 0.1/a (§ 3.1 terms; § 5.3.3.5, Tab. 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND f.symbol = 'C_m';
UPDATE fields f SET description = 'Vom Tool berechnet (Gl. 2d): Summe der befestigten, angeschlossenen Teilflächen A_E,b,a in m² (Zeilen der Art „befestigt“), ohne Abflussbeiwert. Erster Schritt des Ablaufschemas Bild 5 (angeschlossene Flächen A_E,b,a und A_E,nb,a ermitteln und bewerten); dient dem Abgleich mit dem Lageplan und der Flächenbilanz. Mit den Beiwerten ergibt sich daraus A_C_sealed (Gl. 2f) (§ 5.3.3.5, Tab. 2, Bild 5).
[EN] Computed by the tool (Eq. 2d): sum of the paved, connected sub-areas A_E,b,a in m² (rows of kind ''paved''), without runoff coefficient. First step of the Bild 5 flow chart (determine and evaluate connected areas A_E,b,a and A_E,nb,a); used to reconcile with the site plan and the area balance. With the coefficients it yields A_C_sealed (Eq. 2f) (§ 5.3.3.5, Tab. 2, Bild 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND f.symbol = 'A_E_ba';
UPDATE fields f SET description = 'Vom Tool berechnet (Gl. 2e): Summe der nicht befestigten, angeschlossenen Teilflächen A_E,nb,a in m² (Zeilen der Art „unbefestigt“), ohne Abflussbeiwert. Nur Flächen, die potenziell zur Anlage entwässern, zählen (Tab. 9, Anm. a). Mit den Beiwerten ergibt sich daraus A_C_unsealed (Gl. 2g); durchlässige Flächen tragen nach Tabelle 9 mit C_m 0,1 (flach) bis 0,2 (steil) bei (§ 5.3.3.5, Tab. 2, Tab. 9).
[EN] Computed by the tool (Eq. 2e): sum of the unpaved, connected sub-areas A_E,nb,a in m² (rows of kind ''unpaved''), without runoff coefficient. Only areas that potentially drain to the facility count (Tab. 9, note a). With the coefficients it yields A_C_unsealed (Eq. 2g); permeable surfaces contribute with C_m 0.1 (flat) to 0.2 (steep) per Table 9 (§ 5.3.3.5, Tab. 2, Tab. 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND f.symbol = 'A_E_nba';
UPDATE fields f SET description = 'Vom Tool berechnet (Gl. 2f): reduzierte Fläche der befestigten Teilflächen in m², also der befestigte Anteil von A_C (A_C_sealed + A_C_unsealed = A_C). Zeigt, welcher Teil des Rechenwerts aus Dächern und Verkehrsflächen stammt. Nach Tabelle 9 liegt C_m für Dächer und Asphalt bei 0,9, für Pflaster mit Sickerfugen bei 0,25 – Entsiegelung senkt diesen Anteil direkt und steht in der Prioritätenfolge vor der Versickerung (§ 5.3.3.5, Tab. 9; § 4.1).
[EN] Computed by the tool (Eq. 2f): reduced area of the paved sub-areas in m², i.e. the paved share of A_C (A_C_sealed + A_C_unsealed = A_C). Shows which part of the design value comes from roofs and traffic areas. Per Table 9, C_m is 0.9 for roofs and asphalt and 0.25 for pavers with infiltration joints – unsealing lowers this share directly and ranks before infiltration in the order of priorities (§ 5.3.3.5, Tab. 9; § 4.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND f.symbol = 'A_C_sealed';
UPDATE fields f SET description = 'Vom Tool berechnet (Gl. 2g): reduzierte Fläche der unbefestigten Teilflächen in m², also der unbefestigte Anteil von A_C. Für durchlässige Flächen (Parks, Rasen, Gärten) gibt Tabelle 9 C_m 0,1 (flaches Gelände) bzw. 0,2 (steiles Gelände); der Beiwert darf je nach Durchlässigkeit des Untergrunds und Gefälle abweichen. Dauerhaft eingestaute Wasserflächen zählen mit 1,0 (§ 5.3.3.5, Tab. 9).
[EN] Computed by the tool (Eq. 2g): reduced area of the unpaved sub-areas in m², i.e. the unpaved share of A_C. For permeable surfaces (parks, lawns, gardens) Table 9 gives C_m 0.1 (flat terrain) or 0.2 (steep terrain); the coefficient may deviate depending on subsoil permeability and slope. Permanently impounded water surfaces count with 1.0 (§ 5.3.3.5, Tab. 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND f.symbol = 'A_C_unsealed';
UPDATE equations e SET description = 'Rechenwert A_C in m² nach Gl. (2): alle befestigten und unbefestigten angeschlossenen Teilflächen, jeweils mit ihrem Abflussbeiwert C_i (Tab. 9) gewichtet. A_C ist die Bezugsgröße der gesamten Bemessung: Zufluss Q_zu (Gl. 3), Speichervolumen (Gl. 8), q_S,AC ≥ 2 l/(s·ha) (Gl. 9), Flächenbelastung A_C/A_S,m (Tab. 6) und Spaltenwahl in Tabelle 8. Im Einfachen Verfahren wird mit dem mittleren Abflussbeiwert gerechnet, in der Regel bis n ≥ 0,1/a (§ 5.3.3.5, Tab. 9).
[EN] Design value A_C in m² per Eq. (2): all paved and unpaved connected sub-areas, each weighted by its runoff coefficient C_i (Tab. 9). A_C is the reference quantity of the whole sizing: inflow Q_zu (Eq. 3), storage volume (Eq. 8), q_S,AC ≥ 2 l/(s·ha) (Eq. 9), load ratio A_C/A_S,m (Tab. 6) and column choice in Table 8. In the simple method the mean runoff coefficient is used, as a rule up to n ≥ 0.1/a (§ 5.3.3.5, Tab. 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND e.equation_number = '2';
UPDATE equations e SET description = 'Mittlerer Abflussbeiwert C_m des Einzugsgebiets (Gl. 2c, Hilfsgröße des Tools): Verhältnis des Rechenwerts A_C zur Summe der angeschlossenen Flächen. Begriff nach § 3.1: Verhältnis von Abflussvolumen zu Niederschlagsvolumen als Mittelwert über einen Zeitraum. Plausibilitätsgröße ohne eigene Grenze; sie muss zwischen Minimum und Maximum der C_i liegen (§ 3.1; § 5.3.3.5).
[EN] Mean runoff coefficient C_m of the catchment (Eq. 2c, tool auxiliary): ratio of the design value A_C to the sum of connected areas. Term per § 3.1: ratio of runoff volume to precipitation volume as a mean over a period. Plausibility value without its own limit; it must lie between the minimum and maximum of the C_i (§ 3.1; § 5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND e.equation_number = '2c';
UPDATE equations e SET description = 'Summe der befestigten, angeschlossenen Teilflächen A_E,b,a (Gl. 2d, Hilfsgröße des Tools; Formelzeichen nach Tab. 2). Entspricht Schritt 1 des Ablaufschemas Bild 5; Vergleichswert zum Lageplan. Erst mit den Abflussbeiwerten wird daraus der befestigte Anteil von A_C (Gl. 2, Gl. 2f) (§ 5.3.3.5, Bild 5, Tab. 2).
[EN] Sum of the paved, connected sub-areas A_E,b,a (Eq. 2d, tool auxiliary; symbol per Tab. 2). Corresponds to step 1 of the Bild 5 flow chart; comparison value against the site plan. Only with the runoff coefficients does it become the paved share of A_C (Eq. 2, Eq. 2f) (§ 5.3.3.5, Bild 5, Tab. 2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND e.equation_number = '2d';
UPDATE equations e SET description = 'Summe der nicht befestigten, angeschlossenen Teilflächen A_E,nb,a (Gl. 2e, Hilfsgröße des Tools; Formelzeichen nach Tab. 2). Nur Flächen zählen, die potenziell zur Anlage entwässern (Tab. 9, Anm. a). Erst mit den Abflussbeiwerten (Tab. 9, Gruppe 3: 0,1–0,2) wird daraus der unbefestigte Anteil von A_C (Gl. 2, Gl. 2g) (§ 5.3.3.5, Tab. 2, Tab. 9).
[EN] Sum of the unpaved, connected sub-areas A_E,nb,a (Eq. 2e, tool auxiliary; symbol per Tab. 2). Only areas that potentially drain to the facility count (Tab. 9, note a). Only with the runoff coefficients (Tab. 9, group 3: 0.1–0.2) does it become the unpaved share of A_C (Eq. 2, Eq. 2g) (§ 5.3.3.5, Tab. 2, Tab. 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND e.equation_number = '2e';
UPDATE equations e SET description = 'Befestigter Anteil des Rechenwerts A_C (Gl. 2f, Hilfsgröße des Tools): Summe der befestigten Teilflächen mal Abflussbeiwert – der erste Summand von Gl. (2). Zusammen mit Gl. 2g ergibt sich A_C; dient der Nachvollziehbarkeit der Flächenbilanz im Bericht (§ 5.3.3.5, Gl. 2).
[EN] Paved share of the design value A_C (Eq. 2f, tool auxiliary): sum of paved sub-areas times runoff coefficient – the first summand of Eq. (2). Together with Eq. 2g it gives A_C; serves the traceability of the area balance in the report (§ 5.3.3.5, Eq. 2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND e.equation_number = '2f';
UPDATE equations e SET description = 'Unbefestigter Anteil des Rechenwerts A_C (Gl. 2g, Hilfsgröße des Tools): Summe der unbefestigten Teilflächen mal Abflussbeiwert – der zweite Summand von Gl. (2). Zusammen mit Gl. 2f ergibt sich A_C. Für durchlässige Flächen darf der Beiwert je nach Durchlässigkeit des Untergrunds und Gefälle von Tabelle 9 abweichen (§ 5.3.3.5, Gl. 2, Tab. 9).
[EN] Unpaved share of the design value A_C (Eq. 2g, tool auxiliary): sum of unpaved sub-areas times runoff coefficient – the second summand of Eq. (2). Together with Eq. 2f it gives A_C. For permeable surfaces the coefficient may deviate from Table 9 depending on subsoil permeability and slope (§ 5.3.3.5, Eq. 2, Tab. 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-07' AND e.equation_number = '2g';
UPDATE fields f SET description = 'Fläche des gesamten Einzugsgebiets bis zur betrachteten Versickerungsanlage in ha, aus Flächenverzeichnis bzw. Lageplan (alle Teilflächen, nicht mit Abflussbeiwerten reduziert). Erste Anwendungsbedingung des Einfachen Verfahrens: A_E ≤ 200 ha oder Fließzeit t_f ≤ 15 min; das Tool prüft dies in simple_method_applicable. Bei Überschreitung ist das Nachweisverfahren (Langzeitsimulation) zu verwenden (§ 5.3.3.2, Bild 5; Tab. 2).
[EN] Area of the whole catchment up to the infiltration facility considered, in ha, from the surface inventory or site plan (all sub-areas, not reduced by runoff coefficients). First application condition of the simple method: A_E ≤ 200 ha or flow time t_f ≤ 15 min; the tool checks this in simple_method_applicable. If exceeded, use the verification method (long-term simulation) (§ 5.3.3.2, Bild 5; Tab. 2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'A_E';
UPDATE fields f SET description = 'Abminderungsfaktor f_A nach DWA-A 117 für Abflusskonzentrationsvorgänge im Einfachen Verfahren; vom Planer gewählt. Geht in die Bemessungsgleichung V_VA = (Q_zu − Q_S − Q_Dr) · D · 60 · f_Z · f_A · 10⁻³ (Gl. 8) und in Gl. 41 (Becken) ein. Für Versickerungsanlagen ist in der Regel f_A ≅ 1 anzusetzen; bei dezentralen Anlagen kann die Abflusskonzentration in der Regel vernachlässigt werden (§ 5.3.3.7, § 5.3.3.3, Tab. 12).
[EN] Reduction factor f_A per DWA-A 117 for runoff concentration in the simple method; chosen by the planner. Enters the sizing equation V_VA = (Q_zu − Q_S − Q_Dr) · D · 60 · f_Z · f_A · 10⁻³ (Eq. 8) and Eq. 41 (basin). For infiltration facilities f_A ≅ 1 as a rule; for decentralised facilities runoff concentration can as a rule be neglected (§ 5.3.3.7, § 5.3.3.3, Tab. 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'f_A';
UPDATE fields f SET description = 'Lagekorrekturfaktor f_Ort für örtliche Einflüsse auf den Durchlässigkeitswert (Variabilität des Bodens, Umfang/Anzahl der Versuchsstandorte, Baueinfluss, Sachkunde); vom Planer im Wertebereich 0,3 bis 1,0 begründet zu wählen, Kriterien in Tabelle 10. Hohe Werte sind möglich bei ausreichenden Bodeninformationen und fundiert abgestimmten Versuchsstandorten. Geht in f_K = f_Ort · f_Methode ≤ 1 (Gl. 6) und k_i = k_f · f_K (Gl. 5) in A138-11 ein; Begründung dokumentieren (§ 5.3.3.6, Tab. 10).
[EN] Site correction factor f_Ort for local influences on the permeability value (soil variability, extent/number of test locations, construction influence, expertise); chosen by the planner with reasons in the range 0.3 to 1.0, criteria in Table 10. High values are possible with sufficient soil information and soundly matched test locations. Enters f_K = f_Ort · f_Methode ≤ 1 (Eq. 6) and k_i = k_f · f_K (Eq. 5) in A138-11; document the reasoning (§ 5.3.3.6, Tab. 10).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'f_ort';
UPDATE fields f SET description = 'Zuschlagsfaktor f_Z gegen Unterbemessung im Einfachen Verfahren, das in der Regel kleinere Volumina liefert als das Nachweisverfahren; vom Planer nach Risikomaß (DWA-A 117) zwischen 1,1 und 1,2 gewählt. Bei kleiner spezifischer Versickerungs-/Abflussleistung q_S,AC ≤ 5 l/(s·ha) ist f_Z = 1,2 zwingend; Tor A138-REQ-15 in A138-10 prüft dies. Geht in Gl. 8 und alle anlagenspezifischen Bemessungsgleichungen (Gl. 14, 19, 28, 35, 41) ein (§ 5.3.3.7, Gl. 9).
[EN] Surcharge factor f_Z against under-sizing in the simple method, which as a rule yields smaller volumes than the verification method; chosen by the planner by risk measure (DWA-A 117) between 1.1 and 1.2. With a small specific infiltration/outflow capacity q_S,AC ≤ 5 l/(s·ha), f_Z = 1.2 is required; gate A138-REQ-15 in A138-10 checks this. Enters Eq. 8 and all facility-specific sizing equations (Eq. 14, 19, 28, 35, 41) (§ 5.3.3.7, Eq. 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'f_Z';
UPDATE fields f SET description = 'Bemessungshäufigkeit n in 1/a (Kehrwert der Wiederkehrzeit T_n): Ereignisse, die im langjährigen Mittel pro Jahr erreicht oder überschritten werden. Vom Planer nach Tabelle 8 aus Schutzkategorie und Spalte A_C ≤ / > 800 m² gewählt (Obergrenze = n_limit). Tor A138-REQ-08 akzeptiert 0,1, 0,2, 0,33 oder 0,5. Bei n darf kein Überlauf auftreten; das Einfache Verfahren gilt nur für n ≥ 0,1/a; n ersetzt den Überflutungsnachweis nach § 5.3.4 nicht (§ 3.1; § 5.3.3.2; § 5.3.3.4, Tab. 8).
[EN] Design frequency n in 1/a (reciprocal of the return period T_n): events per year reached or exceeded in the long-term mean. Chosen by the planner from Table 8 by protection category and column A_C ≤ / > 800 m² (upper bound = n_limit). Gate A138-REQ-08 accepts 0.1, 0.2, 0.33 or 0.5. No overflow may occur at n; the simple method applies only for n ≥ 0.1/a; n does not replace the flood proof of § 5.3.4 (§ 3.1; § 5.3.3.2; § 5.3.3.4, Tab. 8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'n';
UPDATE fields f SET description = 'Vom Tool gesetzt: TRUE, wenn alle Anwendungsbedingungen des Einfachen Verfahrens erfüllt sind: A_E ≤ 200 ha oder t_f ≤ 15 min; n ≥ 0,1/a (T_n ≤ 10 a); q_S,AC ≥ 2 l/(s·ha) (Gl. 9, geprüft in A138-10, Tor A138-REQ-15); Regenhäufigkeit = Bemessungshäufigkeit. Die Einhaltung ist in der Bemessung nachzuweisen. Ist eine Bedingung verletzt, führt Bild 5 zum Nachweisverfahren (Langzeitsimulation) oder zu einem anderen Anlagentyp (§ 5.3.3.2, Bild 5).
[EN] Set by the tool: TRUE if all application conditions of the simple method hold: A_E ≤ 200 ha or t_f ≤ 15 min; n ≥ 0.1/a (T_n ≤ 10 a); q_S,AC ≥ 2 l/(s·ha) (Eq. 9, checked in A138-10, gate A138-REQ-15); rain frequency = design frequency. Compliance must be demonstrated in the design. If a condition fails, Bild 5 leads to the verification method (long-term simulation) or another facility type (§ 5.3.3.2, Bild 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'simple_method_applicable';
UPDATE fields f SET description = 'Fließzeit t_f des Wassers bis zur Versickerungsanlage in min; vom Planer aus Fließwegen und -geschwindigkeiten im Einzugsgebiet abgeschätzt. Zweite Hälfte der ersten Anwendungsbedingung des Einfachen Verfahrens: t_f ≤ 15 min oder A_E ≤ 200 ha (simple_method_applicable). Das Einfache Verfahren vernachlässigt Verzögerungseffekte der Abflusskonzentration (Gl. 3); bei langen Fließzeiten ist das Nachweisverfahren zu wählen (§ 5.3.3.2, § 5.3.3.5).
[EN] Flow time t_f of the water to the infiltration facility in min; estimated by the planner from flow paths and velocities in the catchment. Second half of the first application condition of the simple method: t_f ≤ 15 min or A_E ≤ 200 ha (simple_method_applicable). The simple method neglects delay effects of runoff concentration (Eq. 3); for long flow times choose the verification method (§ 5.3.3.2, § 5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 't_f';
UPDATE fields f SET description = 'Statistische Wiederkehrzeit T_n in Jahren: mittlere Zeitspanne, in der ein Ereignis einen Wert erreicht oder überschreitet; Kehrwert der Bemessungshäufigkeit n, vom Tool gebildet (n = 0,2/a → T_n = 5 a). Das Einfache Verfahren gilt für T_n ≤ 10 a; im Nachweisverfahren soll die Regenreihe M ≥ 3 · T_n Jahre lang sein (Gl. 1), mindestens zehn Jahre. Der Überflutungsnachweis rechnet mit T_n = 30 a (Gl. 10) (§ 3.1; § 5.3.3.2; § 5.3.3.3; § 5.3.4.1).
[EN] Statistical return period T_n in years: mean time span in which an event reaches or exceeds a value; reciprocal of the design frequency n, formed by the tool (n = 0.2/a → T_n = 5 a). The simple method applies for T_n ≤ 10 a; in the verification method the rainfall series should be M ≥ 3 · T_n years long (Eq. 1), at least ten years. The flood proof uses T_n = 30 a (Eq. 10) (§ 3.1; § 5.3.3.2; § 5.3.3.3; § 5.3.4.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'T_n';
UPDATE fields f SET description = 'Schutzkategorie nach Tabelle 8; vom Planer nach dem Schadenspotenzial bei Versagen der Anlage gewählt (in Anlehnung an DIN EN 752): (1) gering – z. B. offene Flächen abseits von Gebäuden; (2) mäßig – z. B. Wohn-/Mischgebiete ohne genutzte Untergeschosse, Parkplätze; (3) stark – z. B. Stadtzentren, genutzte Untergeschosse, Gewerbe/Industrie, Tiefgaragen, starkes Gefälle; (4) sehr stark – kritische Infrastruktur, U-Bahn-Zugänge, Unterführungen. Schlüssel für n_limit zusammen mit A_C ≤/> 800 m² (§ 5.3.3.4, Tab. 8).
[EN] Protection category per Table 8; chosen by the planner from the damage potential if the facility fails (following DIN EN 752): (1) low – e.g. open areas away from buildings; (2) moderate – e.g. residential/mixed areas without used basements, car parks; (3) high – e.g. town centres, used basements, commercial/industrial areas, underground car parks, steep terrain; (4) very high – critical infrastructure, metro entrances, underpasses. Key for n_limit together with A_C ≤/> 800 m² (§ 5.3.3.4, Tab. 8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'schutzkategorie';
UPDATE fields f SET description = 'Vom Tool berechnet (A138-08-D1): zulässige Obergrenze der Bemessungshäufigkeit nach Tabelle 8 aus schutzkategorie und A_C-Band: gering 0,33/a (A_C ≤ 800 m²) bzw. 0,5/a (> 800 m²); mäßig 0,2/a bzw. 0,33/a; stark 0,2/a; sehr stark 0,1/a. Die gewählte Bemessungshäufigkeit n muss ≤ n_limit sein (seltener oder gleich). Bei A_C ≤ 800 m² darf die Spalte für A_C > 800 m² genutzt werden, wenn ein Überflutungsnachweis geführt wird (Tab. 8, Anm. a) (§ 5.3.3.4, Tab. 8).
[EN] Computed by the tool (A138-08-D1): permitted upper bound of the design frequency per Table 8 from schutzkategorie and A_C band: low 0.33/a (A_C ≤ 800 m²) or 0.5/a (> 800 m²); moderate 0.2/a or 0.33/a; high 0.2/a; very high 0.1/a. The chosen design frequency n must be ≤ n_limit (rarer or equal). For A_C ≤ 800 m² the column for A_C > 800 m² may be used if a flood proof is carried out (Tab. 8, note a) (§ 5.3.3.4, Tab. 8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND f.symbol = 'n_limit';
UPDATE equations e SET description = 'Nachschlagen der zulässigen Bemessungshäufigkeit in Tabelle 8 nach Schutzkategorie und Spalte (Grundstücksentwässerung mit A_C ≤ 800 m², oder A_C > 800 m² und öffentliche Entwässerung). Das Ergebnis n_limit ist die obere Grenze (häufigster zulässiger Fall): gering 0,33 / 0,5; mäßig 0,2 / 0,33; stark 0,2; sehr stark 0,1 (je 1/a). Die gewählte Häufigkeit n muss ≤ n_limit und zugleich ≥ 0,1/a (Einfaches Verfahren) sein; bei n darf kein Überlauf der Anlage auftreten (§ 5.3.3.4, Tab. 8; § 5.3.3.2).
[EN] Look-up of the permitted design frequency in Table 8 by protection category and column (plot drainage with A_C ≤ 800 m², or A_C > 800 m² and public drainage). The result n_limit is the upper bound (most frequent permitted case): low 0.33 / 0.5; moderate 0.2 / 0.33; high 0.2; very high 0.1 (all 1/a). The chosen frequency n must be ≤ n_limit and at the same time ≥ 0.1/a (simple method); no overflow of the facility may occur at n (§ 5.3.3.4, Tab. 8; § 5.3.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-08' AND e.equation_number = 'A138-08-D1';
UPDATE fields f SET description = 'Zusammenfassendes Ergebnis der Phase 2 (Standort- und Eingangsdaten): PASS, CONDITIONAL oder FAIL; vom Planer aus den Teilergebnissen festgelegt. Tor A138-REQ-09 lässt nur PASS und CONDITIONAL in die Bemessung (Phase 3). Voraussetzungen: Umsetzbarkeit nach Tabelle 3, k_f nach Anhang A, Sohlabstand ≥ 1 m zum MHGW bzw. Behördenabstimmung, Regendaten (KOSTRA-DWD-2020/DWA-A 531), Belastungskategorie und Behandlungskonzept, Flächenverzeichnis mit A_C, Bemessungshäufigkeit nach Tabelle 8 (§ 5.1.2, § 5.2, § 5.3).
[EN] Summary result of phase 2 (site and input data): PASS, CONDITIONAL or FAIL; set by the planner from the partial results. Gate A138-REQ-09 admits only PASS and CONDITIONAL to sizing (phase 3). Prerequisites: feasibility per Table 3, k_f per Annex A, base ≥ 1 m above MHGW or authority agreement, rain data (KOSTRA-DWD-2020/DWA-A 531), pollution category and treatment concept, surface inventory with A_C, design frequency per Table 8 (§ 5.1.2, § 5.2, § 5.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'phase_2_gate_result';
UPDATE fields f SET description = 'Bestätigung, dass die Regendaten vollständig vorliegen: KOSTRA-Rasterzelle (A138-01), Tabelle r_D(n) für alle Dauerstufen und die Bemessungshäufigkeit sowie Datenstand (A138-04). Für die Iteration nach Gl. (8) werden alle Dauerstufen, für den Überflutungsnachweis zusätzlich r_D(30) gebraucht; zu verwenden sind KOSTRA-DWD-2020 (exakte DWD-Werte) oder Auswertungen nach DWA-A 531 (§ 5.3.3.5, § 5.3.3.7, § 5.3.4.1).
[EN] Confirmation that the rain data are complete: KOSTRA grid cell (A138-01), r_D(n) table for all durations and the design frequency, plus data vintage (A138-04). The iteration per Eq. (8) needs all durations, the flood proof additionally r_D(30); use KOSTRA-DWD-2020 (exact DWD values) or evaluations per DWA-A 531 (§ 5.3.3.5, § 5.3.3.7, § 5.3.4.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'kostra_data_complete';
UPDATE fields f SET description = 'Bestätigung, dass der k_f-Wert aus A138-05 belastbar ist: bestimmt nach Anhang A in der maßgeblichen Schicht (Anlagensohle), Methode mit f_Methode nach Tabelle 11, Mindestanzahl der Versuchsstandorte (≥ 1 je 150 m² Sohlenfläche, Längenregel) eingehalten, Auswertung durch Fachkundige (Bodenkunde/Geologie) empfohlen; für zentrale Anlagen im Bodengutachten ausgewiesen. Schätzwerte aus Karten oder Bodenansprache genügen nicht für die Bemessung (§ 5.3.1, § 5.3.3.6, Anh. A).
[EN] Confirmation that the k_f value from A138-05 is reliable: determined per Annex A in the governing layer (facility base), method with f_Methode per Table 11, minimum number of test locations (≥ 1 per 150 m² of base area, length rule) met, evaluation by soil-science/geology experts recommended; stated in a soil report for central facilities. Estimates from maps or soil description are not sufficient for design (§ 5.3.1, § 5.3.3.6, Annex A).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'kf_value_certified';
UPDATE fields f SET description = 'Bestätigung, dass die Standortdaten der Ersteinschätzung vollständig sind: Grundwasser (MHGW, Schichtenwasser), Altlasten, Schutzgebiete, Untergrund (k_f, Schichtung, geotechnische Gefährdung), Gebäudeabstände nach Bild 4 und Hanglage, jeweils mit Quelle nach Tabelle 4 und – für Spalte 2 der Tabelle 3 – durch Fachgutachten belegt. Grundlage für feasibility_determination (A138-02) (§ 5.1.1, § 5.1.2, Tab. 3, Tab. 4).
[EN] Confirmation that the site data of the initial assessment are complete: groundwater (MHGW, perched water), contaminated sites, protection areas, subsoil (k_f, layering, geotechnical hazards), building distances per Bild 4 and slope, each with its source per Table 4 and – for column 2 of Table 3 – proven by expert reports. Basis for feasibility_determination (A138-02) (§ 5.1.1, § 5.1.2, Tab. 3, Tab. 4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'site_data_complete';
UPDATE fields f SET description = 'Bestätigung, dass jeder angeschlossenen Fläche eine Flächengruppe und Belastungskategorie nach Tabelle 5 zugeordnet ist (A138-06) und bei gemeinsamer Anlage die strengste Anforderung angesetzt wurde. Flächen zum Umgang mit wassergefährdenden Stoffen (AwSV) sind in Tabelle 5 nicht eingestuft; die Einschätzung bedarf im Einzelfall der Prüfung durch die Wasserbehörde (§ 5.2.2, Tab. 5; § 5.2.3.2).
[EN] Confirmation that every connected surface has been assigned a surface group and pollution category per Table 5 (A138-06) and that, for a shared facility, the strictest requirement was applied. Areas handling substances hazardous to water (AwSV) are not categorised in Table 5; the assessment needs a case-by-case check by the water authority (§ 5.2.2, Tab. 5; § 5.2.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'belastungskategorie_assigned';
UPDATE fields f SET description = 'Bestätigung, dass das Behandlungskonzept festgelegt ist: oberirdisch über die bewachsene Bodenzone (Tabelle 6: Mindestmächtigkeit ≥ 20/30 cm, A_C/A_S,m, Bodeneigenschaften nach § 5.2.3.2) oder unterirdisch mit vorgeschalteter dezentraler Behandlungsanlage (Tabelle 7: η_AFS63 und η_gelöst, Bemessung mit 25 l/(s·ha)). Für D- und S-Gruppen sowie Anlieferungs-/Ladeflächen ist die Abstimmung mit der Behörde erforderlich. Oberirdische Anlagen sind vorzuziehen (§ 4.1, § 5.2.3).
[EN] Confirmation that the treatment concept is decided: above ground via the vegetated soil zone (Table 6: minimum thickness ≥ 20/30 cm, A_C/A_S,m, soil properties per § 5.2.3.2) or underground with an upstream decentralised treatment unit (Table 7: η_AFS63 and η_dissolved, designed for 25 l/(s·ha)). For D and S groups and delivery/loading areas, agreement with the authority is required. Above-ground facilities are to be preferred (§ 4.1, § 5.2.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'treatment_concept_decided';
UPDATE fields f SET description = 'Datum, an dem die Grundlagenermittlung (Tabelle 4) abgeschlossen wurde. Dokumentationsfeld für die Nachvollziehbarkeit; zusammen mit kostra_data_date und dem Zeitraum des MHGW belegt es den Datenstand. Keine Prüfung (§ 5.1.2).
[EN] Date on which the basic data collection (Table 4) was completed. Documentation field for traceability; together with kostra_data_date and the MHGW period it records the data vintage. No check (§ 5.1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'data_collection_completion_date';
UPDATE fields f SET description = 'Gesamtbewertung der Datenqualität (hoch/mittel/gering/unzureichend); vom Planer festgelegt. Sie soll die Begründung des Lagekorrekturfaktors f_Ort (A138-08) stützen: Tabelle 10 nennt Informationsstand zu den Bodenverhältnissen, Anzahl der Versuche vs. Variabilität, Baueinfluss und Sachkunde als Kriterien zwischen 0,3 und 1,0. „Unzureichend“ sollte zu FAIL im Phase-2-Tor führen (§ 5.3.3.6, Tab. 10).
[EN] Overall assessment of data quality (high/medium/low/insufficient); set by the planner. It should support the reasoning for the site correction factor f_Ort (A138-08): Table 10 names the state of information on soil conditions, number of tests vs. variability, construction influence and expertise as criteria between 0.3 and 1.0. ''Insufficient'' should lead to FAIL in the phase-2 gate (§ 5.3.3.6, Tab. 10).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'data_quality_assessment';
UPDATE fields f SET description = 'Freitext: offene Datenlücken und wie sie geschlossen werden (z. B. fehlende MHGW-Reihe → Abfrage der Fachbehörden oder qualifizierte Untersuchung, ggf. zusammen mit der k_f-Bestimmung; unbekannte Schichtung → Sondierbohrungen; Kriterium in Spalte 3 der Tabelle 3 → genauere Prüfung). Grundlage für CONDITIONAL im Phase-2-Tor (§ 5.1.1, § 5.1.2).
[EN] Free text: open data gaps and how they will be closed (e.g. missing MHGW series → query of the specialist authorities or qualified investigation, possibly together with the k_f determination; unknown layering → exploratory borings; a criterion in column 3 of Table 3 → closer examination). Basis for CONDITIONAL in the phase-2 gate (§ 5.1.1, § 5.1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-09' AND f.symbol = 'data_gaps_documented';
UPDATE fields f SET description = 'Überregnete Fläche einer oberirdischen Anlage (Mulde, Becken, Fläche): der Regen, der direkt in die Anlage fällt. Anzusetzen ist die maximale Versickerungsfläche A_S,max, je nach Planungsstand geschätzt oder aus der geplanten Geometrie. Das Tool addiert sie in Gl. (3) zu A_C: Q_zu = r_D(n)·(A_C+A_VA)·10⁻⁴. Nur oberirdische Anlagen haben A_VA; für Rigole und Schacht 0 eintragen (§5.3.3.5).
[EN] Rained-on area of an above-ground facility (swale, basin, infiltration area): the rain that falls directly into the facility. Use the maximum infiltration area A_S,max, estimated or taken from the planned geometry depending on the planning stage. The tool adds it to A_C in Eq. (3): Q_zu = r_D(n)·(A_C+A_VA)·10⁻⁴. Only above-ground facilities have A_VA; enter 0 for trenches and shafts (§5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-10' AND f.symbol = 'A_VA';
UPDATE fields f SET description = 'Zufluss zur Anlage während der Dauerstufe D in l/s; das Tool berechnet ihn nach Gl. (3) aus r_D(n), A_C (Gl. 2) und A_VA. Er ist der Zuflussterm der Bemessungsgleichung Gl. (8) in A138-13 und wird dort für jede Dauerstufe neu gebildet. Gl. (3) gilt nur im Einfachen Verfahren und vernachlässigt die Abflusskonzentration; Regendaten nach DWA-A 531 oder aktuellem KOSTRA-DWD-Datensatz (§5.3.3.5).
[EN] Inflow to the facility during duration D in l/s; the tool computes it per Eq. (3) from r_D(n), A_C (Eq. 2) and A_VA. It is the inflow term of the sizing equation Eq. (8) in A138-13, where it is recomputed for every duration step. Eq. (3) applies to the simple method only and neglects runoff concentration; rain data from DWA-A 531 or the current KOSTRA-DWD data set (§5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-10' AND f.symbol = 'Q_zu';
UPDATE equations e SET description = 'Gl. (3) bestimmt den Zufluss Q_zu zur Anlage für eine Dauerstufe D. r_D(n) = Regenspende für Dauer D und Bemessungshäufigkeit n in l/(s·ha); A_C = Rechenwert nach Gl. (2); A_VA = überregnete Fläche der oberirdischen Anlage; 10⁻⁴ rechnet m² in ha um. Q_zu geht in Gl. (8) ein. Gilt nur im Einfachen Verfahren ohne Abflusskonzentration; bei Anlagen mit Speicher werden D und r_D(n) iterativ bestimmt (§5.3.3.5).
[EN] Eq. (3) determines the inflow Q_zu to the facility for one duration D. r_D(n) = rainfall intensity for duration D and design frequency n in l/(s·ha); A_C = design value per Eq. (2); A_VA = rained-on area of an above-ground facility; 10⁻⁴ converts m² to ha. Q_zu enters Eq. (8). Simple method only, neglecting runoff concentration; for facilities with storage, D and r_D(n) are found iteratively (§5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-10' AND e.equation_number = '3';
UPDATE fields f SET description = 'Resultierender Korrekturfaktor; das Tool bildet ihn nach Gl. (6) aus f_Ort (Standortfaktor, Tab. 10, begründet zwischen 0,3 und 1,0) und f_Methode (Tab. 11: Testgrube ≥ 1 m² 1,0; Doppelzylinder 0,9; Open-End 0,8; Labor ungestört 0,7; Sieblinie 0,1) und begrenzt auf ≤ 1. Er reduziert k_f zu k_i (Gl. 5). Wird für die bewachsene Bodenzone der Pauschalwert 1–5·10⁻⁵ m/s angesetzt, entfällt f_Methode (§5.3.3.6).
[EN] Combined correction factor; the tool forms it per Eq. (6) from f_Ort (local factor, Tab. 10, reasoned choice between 0.3 and 1.0) and f_Methode (Tab. 11: test pit ≥ 1 m² 1.0; double-ring 0.9; open-end 0.8; lab undisturbed 0.7; grading curve 0.1), capped at ≤ 1. It reduces k_f to k_i (Eq. 5). If the vegetated soil zone is set at the default 1–5·10⁻⁵ m/s, f_Methode is neglected (§5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-11' AND f.symbol = 'f_K';
UPDATE fields f SET description = 'Bemessungsrelevante Infiltrationsrate; das Tool berechnet sie nach Gl. (5) als k_f · f_K und hält sie im Einfachen Verfahren konstant. Sie steuert Q_S (Gl. 4, A138-12), V_VA und q_S,AC (Gl. 8/9, A138-13) sowie die Flächenversickerung (Gl. 12/13, A138-16). Maßgebend ist die geringer durchlässige Schicht; bei oberirdischen Anlagen ist die bewachsene Bodenzone zu berücksichtigen (§5.3.1, §5.3.3.6). k_i ist der entscheidende Eingangsparameter.
[EN] Design infiltration rate; the tool computes it per Eq. (5) as k_f · f_K and keeps it constant in the simple method. It drives Q_S (Eq. 4, A138-12), V_VA and q_S,AC (Eq. 8/9, A138-13) and area infiltration (Eq. 12/13, A138-16). The less permeable layer governs; for above-ground facilities the vegetated soil zone must be considered (§5.3.1, §5.3.3.6). The standard calls k_i the decisive input parameter.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-11' AND f.symbol = 'k_i';
UPDATE fields f SET description = 'Kleinster gemessener k_f-Wert aus Feldversuchen bzw. Bodengutachten (Anhang A). Im Einfachen Verfahren wird auf der sicheren Seite die minimale Infiltrationsrate als k_f-Wert verwendet; sie geht in Gl. (5) ein. Mindestanzahl Versuche: 1 je 150 m² Sohlfläche; bei Anlagen über 10 m Länge und heterogenem Boden ein weiterer, bei größeren Anlagen alle 25 m (§5.3.3.6). Vollständige Versickerung in der Regel bei k_f 1·10⁻⁶ bis 1·10⁻³ m/s (§5.3.1).
[EN] Smallest measured k_f from the field tests or soil report (Annex A). In the simple method the minimum infiltration rate is used as the k_f value, on the safe side; this value enters Eq. (5). Minimum number of tests: 1 per 150 m² of base area; for facilities longer than 10 m with heterogeneous soil at least one more, for larger facilities every 25 m (§5.3.3.6). Complete infiltration as a rule needs k_f between 1·10⁻⁶ and 1·10⁻³ m/s (§5.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-11' AND f.symbol = 'a138_k_f_min';
UPDATE fields f SET description = 'Der für die Bemessung angesetzte k_f-Wert der maßgeblichen Bodenschicht. In der Regel gleich dem k_f-Minimum; bei geschichtetem Boden ist die geringer durchlässige Schicht maßgebend, bei oberirdischen Anlagen die bewachsene Bodenzone (k_f 1·10⁻⁵ bis 5·10⁻⁵ m/s ansetzbar, wenn §5.2.3.2 und Bild 1 erfüllt). Dieser Wert wird mit f_K zu k_i (Gl. 5). Für zentrale Anlagen ist die maßgebliche Schicht im Bodengutachten auszuweisen (§5.3.1, §5.3.3.6).
[EN] The k_f value of the governing soil layer adopted for design. Normally equal to the k_f minimum; in layered soil the less permeable layer governs, for above-ground facilities the vegetated soil zone (may be set at 1·10⁻⁵ to 5·10⁻⁵ m/s if §5.2.3.2 and Bild 1 are met). This value is multiplied by f_K to give k_i (Eq. 5). For central facilities the governing layer must be stated in a soil report (§5.3.1, §5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-11' AND f.symbol = 'a138_k_f_design';
UPDATE equations e SET description = 'Gl. (5) bestimmt die bemessungsrelevante Infiltrationsrate k_i. k_f = Durchlässigkeitsbeiwert des Bodens in m/s (im Einfachen Verfahren der Minimalwert); f_K = resultierender Korrekturfaktor nach Gl. (6). k_i wird konstant angenommen und steuert Q_S (Gl. 4), V_VA (Gl. 8), q_S,AC (Gl. 9) und die Flächenversickerung (Gl. 12/13). Veränderung über die Betriebsdauer sinnvoll abschätzen; Frostperioden sind in der Regel nicht relevant (§5.3.3.6).
[EN] Eq. (5) determines the design infiltration rate k_i. k_f = permeability coefficient of the soil in m/s (the minimum value in the simple method); f_K = combined correction factor per Eq. (6). k_i is assumed constant and drives Q_S (Eq. 4), V_VA (Eq. 8), q_S,AC (Eq. 9) and area infiltration (Eq. 12/13). Make sensible assumptions about its change over the operating period; frost periods are as a rule not relevant (§5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-11' AND e.equation_number = '5';
UPDATE equations e SET description = 'Gl. (6) bestimmt den resultierenden Korrekturfaktor f_K als Produkt f_Ort · f_Methode, begrenzt auf ≤ 1. f_Ort erfasst Variabilität des Bodens und Umfang der Untersuchungen (Tab. 10, begründet 0,3–1,0); f_Methode die Unsicherheit der Bestimmungsmethode (Tab. 11, 1,0 bis 0,1, Feldversuche bevorzugt). f_K reduziert k_f zu k_i in Gl. (5). Bei Ansatz des Pauschalwerts für die bewachsene Bodenzone entfällt f_Methode (§5.3.3.6).
[EN] Eq. (6) determines the combined correction factor f_K as the product f_Ort · f_Methode, capped at ≤ 1. f_Ort covers soil variability and extent of investigation (Tab. 10, reasoned choice 0.3–1.0); f_Methode the uncertainty of the test method (Tab. 11, 1.0 down to 0.1, field tests preferred). f_K reduces k_f to k_i in Eq. (5). When the default value for the vegetated soil zone is used, f_Methode is neglected (§5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-11' AND e.equation_number = '6';
UPDATE fields f SET description = 'Versickerungswirksame Fläche der Anlage in m², abhängig von Anlagentyp und Geometrie (Sohle, mittlere Fläche, Seitenflächen; Abschnitt 6 legt je Typ fest, welche Fläche zählt). Für oberirdische Anlagen darf die Horizontalprojektion der Wasserspiegelfläche angesetzt werden (Bild 6). Das Tool berechnet daraus Q_S nach Gl. (4). Für Varianten ist der Ansatz der versickerungswirksamen Fläche nachvollziehbar zu dokumentieren (§5.3.3.6, §6.1).
[EN] Effective infiltration area of the facility in m², depending on facility type and geometry (base, mean area, side faces; Section 6 defines per type which area counts). For above-ground facilities the horizontal projection of the water surface may be used (Bild 6). The tool computes Q_S from it per Eq. (4). For variants, the effective area used must be documented traceably (§5.3.3.6, §6.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'A_S';
UPDATE fields f SET description = 'Mittlere Versickerungsfläche; das Tool berechnet sie nach Gl. (7) aus A_S,min und A_S,max, oder sie wird nach Tab. 13 bzw. manuell vorgegeben (siehe Bestimmungsmethode). Sie macht Q_S im Einfachen Verfahren konstant, geht in q_S,AC (Gl. 9) ein und ist Bezugsgröße der Flächenbelastung A_C/A_S,m nach Tab. 6. Bei Mulden kann näherungsweise A_VA = A_S,m gesetzt werden (§5.3.3.6, §6.3.2).
[EN] Mean infiltration area; the tool computes it per Eq. (7) from A_S,min and A_S,max, or it is set from Tab. 13 or manually (see determination method). It makes Q_S constant in the simple method, enters q_S,AC (Eq. 9) and is the reference for the loading ratio A_C/A_S,m of Tab. 6. For swales, A_VA = A_S,m may be used as an approximation (§5.3.3.6, §6.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'A_S_m';
UPDATE fields f SET description = 'Maximale Versickerungsfläche bei Volleinstau (Bemessungseinstau), aus der geplanten Geometrie als Horizontalprojektion der Wasserspiegelfläche (Bild 6). Das Tool nutzt sie in Gl. (7) für A_S,m; außerdem ist sie bei oberirdischen Anlagen als überregnete Fläche A_VA anzusetzen (A138-10). Je nach Planungsstand geschätzt oder aus Planunterlagen (§5.3.3.5, §5.3.3.6).
[EN] Maximum infiltration area at full (design) impoundment, taken from the planned geometry as the horizontal projection of the water surface (Bild 6). The tool uses it in Eq. (7) for A_S,m; for above-ground facilities it is also the rained-on area A_VA (A138-10). Estimated or taken from planning documents depending on the planning stage (§5.3.3.5, §5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'A_S_max';
UPDATE fields f SET description = 'Minimale Versickerungsfläche, in der Regel die Sohlenfläche der Anlage, aus der geplanten Geometrie. Das Tool nutzt sie in Gl. (7) für A_S,m. Die Sohlfläche bestimmt auch die Mindestanzahl der Versuchsstandorte: mindestens ein Versuch je 150 m² Sohlfläche (§5.3.3.6).
[EN] Minimum infiltration area, as a rule the base area of the facility, from the planned geometry. The tool uses it in Eq. (7) for A_S,m. The base area also sets the minimum number of test locations: at least one test per 150 m² of base area (§5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'A_S_min';
UPDATE fields f SET description = 'Hydraulische und stoffliche Flächenbelastung der bewachsenen Bodenzone; das Tool berechnet den Quotienten aus A_C (Gl. 2) und A_S,m (Gl. 7) und prüft ihn gegen den Tab.-6-Grenzwert der maßgebenden Flächengruppe (Tab. 5). Die Versickerung über die bewachsene Bodenzone gilt als Behandlungsmaßnahme; Tab. 6 begrenzt dafür A_C/A_S,m, z. B. ≤ 30 (≥ 20 cm) bzw. ≤ 50 (≥ 30 cm) für VW2/V2/BF/BG2 (§5.2.3.2). Das Verhältnis ist nachzuweisen (§6.3.2).
[EN] Hydraulic and pollutant loading of the vegetated soil zone; the tool computes the quotient of A_C (Eq. 2) and A_S,m (Eq. 7) and checks it against the Tab. 6 limit of the governing area group (Tab. 5). Infiltration through the vegetated soil zone counts as a treatment measure; Tab. 6 therefore limits A_C/A_S,m, e.g. ≤ 30 (≥ 20 cm) or ≤ 50 (≥ 30 cm) for VW2/V2/BF/BG2 (§5.2.3.2). The ratio must be demonstrated (§6.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'ac_as_ratio';
UPDATE fields f SET description = 'Ergebnis der Flächenbelastungs-Prüfung, vom Tool gesetzt: pass, wenn A_C/A_S,m den Tab.-6-Grenzwert für Flächengruppe und Mächtigkeit der bewachsenen Bodenzone einhält; fail, wenn überschritten; not_applicable bei Gruppen ohne Anforderung (VW1/V1/BG1) oder mit behördlicher Abstimmung (D, S-Gruppen, Sternchen); indeterminate, wenn Flächengruppe oder Eingaben fehlen. Bei gemeinsam angeschlossenen Flächen gilt die strengste Anforderung (§5.2.3.2).
[EN] Result of the loading-ratio check, set by the tool: pass if A_C/A_S,m is within the Tab. 6 limit for the area group and vegetated-soil-zone thickness; fail if exceeded; not_applicable for groups without a requirement (VW1/V1/BG1) or requiring agreement with the authority (D, S groups, asterisk); indeterminate if the area group or inputs are missing. For jointly connected areas the strictest requirement applies (§5.2.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'ac_as_ratio_check';
UPDATE fields f SET description = 'Zulässiges Verhältnis A_C/A_S,m nach Tab. 6, vom Tool aus der maßgebenden Flächengruppe (Tab. 5) und der Mindestmächtigkeit der bewachsenen Bodenzone (≥ 20 cm / ≥ 30 cm) gewählt: VW2/V2/BF/BG2 ≤ 30 bzw. ≤ 50; BL/V3/BG3 ≤ 15 bzw. ≤ 30; VW1/V1/BG1 keine Anforderung; D und S-Gruppen behördlich abzustimmen. Schlüssel ist die Flächengruppe, nicht die Belastungskategorie. Die Mächtigkeit gilt nach Setzung der Schicht (§5.2.3.2).
[EN] Permitted ratio A_C/A_S,m per Tab. 6, selected by the tool from the governing area group (Tab. 5) and the minimum thickness of the vegetated soil zone (≥ 20 cm / ≥ 30 cm): VW2/V2/BF/BG2 ≤ 30 or ≤ 50; BL/V3/BG3 ≤ 15 or ≤ 30; VW1/V1/BG1 no requirement; D and S groups to be agreed with the authority. The key is the area group, not the pollution category. The thickness applies after settlement of the layer (§5.2.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'ac_as_ratio_limit';
UPDATE fields f SET description = 'Versickerungsleistung der Anlage in l/s; das Tool berechnet sie nach Gl. (4) aus k_i (A138-11) und der versickerungswirksamen Fläche A_S (im Einfachen Verfahren in der Regel A_S,m, daher konstant). Sie ist der Abflussterm der Bemessungsgleichung Gl. (8) in A138-13. Liegt Q_S unter dem Zufluss Q_zu, muss die Differenz gespeichert werden; nur bei Flächenversickerung muss Q_S den Zufluss jederzeit aufnehmen (§5.3.3.6, §5.3.3.7).
[EN] Infiltration capacity of the facility in l/s; the tool computes it per Eq. (4) from k_i (A138-11) and the effective infiltration area A_S (as a rule A_S,m in the simple method, hence constant). It is the outflow term of the sizing equation Eq. (8) in A138-13. If Q_S is below the inflow Q_zu the difference must be stored; only area infiltration must take the inflow at every moment (§5.3.3.6, §5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'Q_S';
UPDATE fields f SET description = 'Vom Tool erzeugte Begründung zum Prüfergebnis der Flächenbelastung: welche Flächengruppe (Tab. 5), welche Mächtigkeit der bewachsenen Bodenzone und welcher Tab.-6-Grenzwert angesetzt wurden bzw. warum keine Prüfung möglich war. Dient der Nachvollziehbarkeit des Nachweises A_C/A_S,m (§5.2.3.2); keine Eingabe erforderlich.
[EN] Reason text generated by the tool for the loading-ratio result: which area group (Tab. 5), which vegetated-soil-zone thickness and which Tab. 6 limit were applied, or why the check could not be made. It documents the A_C/A_S,m proof (§5.2.3.2); no input required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'ac_as_ratio_check_reason';
UPDATE fields f SET description = 'Wie A_S,m bestimmt wird. geometry: aus A_S,min/A_S,max nach Gl. (7); direct: direkt als versickerungswirksame Fläche eingegeben; soil_estimate: Größenordnung nach Tab. 13 unabhängig von der Geometrie (Mittel-/Feinsand 0,10·A_C, schluffige Böden 0,20·A_C); manual: eigener Wert mit Herkunftsangabe. Im Einfachen Verfahren darf A_S,m aus der Geometrie oder vereinfacht vorgegeben werden; im Simulationsverfahren ist die Geometrie zu verwenden (§6.3.2).
[EN] How A_S,m is determined. geometry: from A_S,min/A_S,max per Eq. (7); direct: entered directly as the effective infiltration area; soil_estimate: order of magnitude from Tab. 13 regardless of geometry (medium/fine sand 0.10·A_C, silty soils 0.20·A_C); manual: own value with stated provenance. In the simple method A_S,m may come from the geometry or be set in simplified form; in the simulation method the geometry must be used (§6.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'a_s_m_determination_method';
UPDATE fields f SET description = 'Herkunft eines manuell eingegebenen A_S,m: Planunterlage, Gutachten oder Berechnung mit Datum nennen. Der Ansatz der versickerungswirksamen Fläche ist nachvollziehbar zu dokumentieren, insbesondere bei Varianten der Standardanlagen (§6.1). Das Tool prüft den Text nicht; er erscheint im Nachweis.
[EN] Provenance of a manually entered A_S,m: name the plan, report or calculation with its date. The effective infiltration area used must be documented traceably, especially for variants of the standard facilities (§6.1). The tool does not validate the text; it appears in the proof.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'a_s_m_provenance';
UPDATE fields f SET description = 'Vom Tool gesetzt, wenn nach Festlegung von A_S,m der Anlagentyp gewechselt wurde. Welche Fläche versickerungswirksam ist, hängt vom Anlagentyp ab (Sohle, mittlere Fläche, Seitenflächen); ein übernommener Wert kann daher falsch sein. A_S,m prüfen, ggf. neu bestimmen und das Kennzeichen zurücksetzen (§5.3.3.6, §6.1).
[EN] Set by the tool when the facility type was changed after A_S,m was fixed. Which area infiltrates depends on the facility type (base, mean area, side faces), so a carried-over value may be wrong. Check A_S,m, redetermine it if needed and clear the flag (§5.3.3.6, §6.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'a_s_m_needs_reconfirmation';
UPDATE fields f SET description = 'Bodenart für die Abschätzung von A_S,m nach Tab. 13, nur bei Bestimmungsmethode soil_estimate; aus dem Bodengutachten entnehmen. Das Tool setzt dann A_S,m = 0,10·A_C bei Mittel-/Feinsand bzw. 0,20·A_C bei schluffigem Sand, sandigem Schluff oder Schluff. Tab. 13 gibt Größenordnungen unabhängig von der Anlagengeometrie; das Verhältnis A_C/A_S,m nach Tab. 6 ist trotzdem nachzuweisen (§6.3.2).
[EN] Soil type for estimating A_S,m per Tab. 13, only with determination method soil_estimate; take it from the soil report. The tool then sets A_S,m = 0.10·A_C for medium/fine sand or 0.20·A_C for silty sand, sandy silt or silt. Tab. 13 gives orders of magnitude independent of the facility geometry; the ratio A_C/A_S,m per Tab. 6 must still be demonstrated (§6.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND f.symbol = 'soil_bodenart_tab13';
UPDATE equations e SET description = 'Gl. (4) bestimmt die Versickerungsleistung Q_S in l/s. k_i = bemessungsrelevante Infiltrationsrate nach Gl. (5) in m/s; A_S = versickerungswirksame Fläche, anlagenspezifisch nach Abschnitt 6; 10³ rechnet m³/s in l/s um. Q_S ist der Abflussterm in Gl. (8) und bestimmt zusammen mit Q_zu das Speichervolumen. Für Varianten ist die angesetzte Fläche nachvollziehbar zu dokumentieren (§5.3.3.6, §6.1).
[EN] Eq. (4) determines the infiltration capacity Q_S in l/s. k_i = design infiltration rate per Eq. (5) in m/s; A_S = effective infiltration area, facility-specific per Section 6; 10³ converts m³/s to l/s. Q_S is the outflow term in Eq. (8) and, with Q_zu, determines the storage volume. For variants, the area used must be documented traceably (§5.3.3.6, §6.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND e.equation_number = '4';
UPDATE equations e SET description = 'Gl. (7) bestimmt die mittlere Versickerungsfläche A_S,m als Mittel aus A_S,min (in der Regel Sohlenfläche) und A_S,max (Fläche bei Volleinstau, Horizontalprojektion nach Bild 6). Im Einfachen Verfahren wird damit die Versickerungsleistung konstant angenommen; A_S,m geht in Gl. (4), Gl. (9) und die Tab.-6-Prüfung ein. Im Nachweisverfahren ist A_S stattdessen je Zeitschritt aus dem Wasserstand zu berechnen (§5.3.3.6).
[EN] Eq. (7) determines the mean infiltration area A_S,m as the average of A_S,min (as a rule the base area) and A_S,max (area at full impoundment, horizontal projection per Bild 6). In the simple method this makes the infiltration capacity constant; A_S,m enters Eq. (4), Eq. (9) and the Tab. 6 check. In the verification method A_S must instead be recalculated per time step from the water level (§5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-12' AND e.equation_number = '7';
UPDATE fields f SET description = 'Spezifische Versickerungs-/Abflussleistung bezogen auf A_C; das Tool berechnet sie nach Gl. (9) aus k_i, A_S,m, Q_Dr und A_C. Sie prüft die Anwendungsbedingung des Einfachen Verfahrens: q_S,AC ≥ 2 l/(s·ha) ist einzuhalten (Gate A138-REQ-15); bei q_S,AC ≤ 5 l/(s·ha) ist f_Z = 1,2 erforderlich. Bei Unterschreitung: Abmessungen anpassen, anderer Anlagentyp (z. B. mit Drosselabfluss) oder Nachweisverfahren (§5.3.3.2, §5.3.3.7, Bild 5).
[EN] Specific infiltration/outflow capacity related to A_C; the tool computes it per Eq. (9) from k_i, A_S,m, Q_Dr and A_C. It checks the application condition of the simple method: q_S,AC ≥ 2 l/(s·ha) must be met (gate A138-REQ-15); at q_S,AC ≤ 5 l/(s·ha), f_Z = 1.2 is required. If below the limit: adjust dimensions, choose another facility type (e.g. with throttled outflow) or use the verification method (§5.3.3.2, §5.3.3.7, Bild 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND f.symbol = 'q_S_AC';
UPDATE fields f SET description = 'Erforderliches Speichervolumen; das Tool berechnet es nach Gl. (8) für alle Dauerstufen D mit zugehöriger Regenspende r_D(n) und übernimmt das eindeutige Maximum (maßgebende Dauerstufe). Bemessungszielgröße für alle Anlagen außer Flächenversickerung; mit dem Volumen der gewählten Geometrie abgleichen (Bild 5), sonst Abmessungen anpassen und neu rechnen. Für die Bemessungshäufigkeit n darf kein Überlauf auftreten (§5.3.3.4, §5.3.3.7).
[EN] Required storage volume of the facility; the tool computes it per Eq. (8) for all duration steps D with their rainfall intensity r_D(n) and takes the unique maximum (governing duration). It is the design target for all facilities except area infiltration and is compared with the volume of the chosen geometry (Bild 5); if it does not fit, adjust the dimensions and recalculate. No overflow may occur at the design frequency n (§5.3.3.4, §5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND f.symbol = 'V_VA';
UPDATE fields f SET description = 'Quelle der verwendeten Regenspenden r_D(n): Rasterfeld und Version des KOSTRA-DWD-Datensatzes oder die örtliche Starkregenauswertung nach DWA-A 531. Das Tool dokumentiert die Angabe im Nachweis; die Iteration über D (Gl. 8) nutzt diese Tabelle. Es sind aktuelle KOSTRA-Daten in der gültigen Fassung zu verwenden; die exakten DWD-Werte dürfen angesetzt werden (§5.3.3.5).
[EN] Source of the rainfall intensities r_D(n) used: grid cell and version of the KOSTRA-DWD data set, or the local heavy-rain evaluation per DWA-A 531. The tool records it in the proof; the iteration over D (Eq. 8) uses this table. Current KOSTRA data in the valid version must be used; the exact DWD values may be applied (§5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = 'Tatsächlich vorhandenes Speichervolumen der gewählten Anlagengeometrie in m³ (aus der Geometrie bzw. den anlagenspezifischen Blättern A138-16 ff.). Das Tool vergleicht es mit dem erforderlichen Volumen V_VA (Gl. 8): Abgleich gewählte mit berechneten Abmessungen nach Bild 5. Ist es kleiner, Abmessungen anpassen und die Berechnung wiederholen, da sich mit der Geometrie auch Q_S und A_VA ändern (§5.3.3.2, Bild 5).
[EN] Storage volume actually provided by the chosen facility geometry in m³ (from the geometry or the facility-specific sheets A138-16 ff.). The tool compares it with the required volume V_VA (Eq. 8): the comparison of chosen and calculated dimensions in Bild 5. If smaller, adjust the dimensions and repeat the calculation, since Q_S and A_VA change with the geometry (§5.3.3.2, Bild 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND f.symbol = 'a138_V_Sp_vorhanden';
UPDATE fields f SET description = 'Erforderliches Speichervolumen in m³, vom Tool als Maximum von Gl. (8) über alle Dauerstufen übernommen (identisch mit V_VA). Dient dem Abgleich mit dem vorhandenen Speichervolumen und wird in die Zusammenfassung A138-14 übernommen. Bemessungszielgröße für alle Anlagen außer der Flächenversickerung (§5.3.3.7).
[EN] Required storage volume in m³, taken by the tool as the maximum of Eq. (8) over all duration steps (identical to V_VA). Used for the comparison with the provided storage volume and carried into the summary A138-14. Design target for all facilities except area infiltration (§5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND f.symbol = 'a138_V_Sp_erforderlich';
UPDATE fields f SET description = 'Regenspende der maßgebenden Dauerstufe, vom Tool aus der Iteration von Gl. (8) ermittelt: der r_D(n)-Wert für Bemessungshäufigkeit n (Tab. 8) und die Dauerstufe D, bei der V_VA maximal wird. Für Anlagen mit Speicher werden D und r_D(n) iterativ bestimmt (§5.3.3.5); der Wert stammt aus der angegebenen Niederschlagstabelle. Die Regenhäufigkeit wird gleich der Bemessungshäufigkeit gesetzt (§5.3.3.2).
[EN] Rainfall intensity of the governing duration, found by the tool in the iteration of Eq. (8): the r_D(n) value for design frequency n (Tab. 8) and the duration D at which V_VA is maximal. For facilities with storage, D and r_D(n) are determined iteratively (§5.3.3.5); the value comes from the stated rainfall table. The rain frequency is set equal to the design frequency (§5.3.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND f.symbol = 'r_D_n';
UPDATE fields f SET description = 'Maßgebende Dauerstufe des Bemessungsregens in min, vom Tool als diejenige Dauerstufe bestimmt, bei der Gl. (8) das eindeutige Maximum von V_VA liefert. Die Dauer muss im Einfachen Verfahren schrittweise über die Wertepaare D / r_D,n gefunden werden (§5.3.3.7). Für Flächenversickerung gilt stattdessen fest D = 10 bis 15 min (Tab. 12).
[EN] Governing duration of the design rain in min, determined by the tool as the duration step at which Eq. (8) yields the unique maximum of V_VA. In the simple method the duration must be found step by step over the pairs D / r_D,n (§5.3.3.7). For area infiltration a fixed D = 10 to 15 min applies instead (Tab. 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND f.symbol = 'D_min';
UPDATE fields f SET description = 'Vom Tool gesetzt, wenn die Bemessungsprüfung erfüllt ist: q_S,AC ≥ 2 l/(s·ha) nach Gl. (9), f_Z = 1,2 bei q_S,AC ≤ 5 l/(s·ha), und das vorhandene Speichervolumen deckt das erforderliche V_VA (Gl. 8). Das Ergebnis geht in das Phase-3-Tor (A138-14) ein. Nicht bestanden heißt nach Bild 5: Abmessungen anpassen, anderer Anlagentyp oder Nachweisverfahren (§5.3.3.2, §5.3.3.7).
[EN] Set by the tool when the design check is met: q_S,AC ≥ 2 l/(s·ha) per Eq. (9), f_Z = 1.2 where q_S,AC ≤ 5 l/(s·ha), and the provided storage volume covers the required V_VA (Eq. 8). The result feeds the phase 3 gate (A138-14). Not passed means per Bild 5: adjust dimensions, choose another facility type or use the verification method (§5.3.3.2, §5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND f.symbol = 'a138_bemessung_bestanden';
UPDATE equations e SET description = 'Gl. (1) gibt die empfohlene Mindestlänge M der Niederschlagsreihe für das Nachweisverfahren (Langzeitsimulation): M ≥ 3 · T_n, T_n = statistische Wiederkehrzeit in Jahren. Nur relevant, wenn statt des Einfachen Verfahrens simuliert wird (z. B. zentrale oder vernetzte Anlagen, n < 0,1/a). Pflicht: mindestens 10 Jahre kontinuierliche Reihe, Zeitschritt ≤ 5 min; fehlen lange Reihen, sind synthetische Regenreihen zu bevorzugen (§5.3.3.3).
[EN] Eq. (1) gives the recommended minimum length M of the rainfall series for the verification method (long-term simulation): M ≥ 3 · T_n, T_n = statistical return period in years. Relevant only when a simulation replaces the simple method (e.g. central or networked facilities, n < 0.1/a). Mandatory: at least 10 years of continuous series, time step ≤ 5 min; where long records are missing, synthetic rainfall series are preferable (§5.3.3.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND e.equation_number = '1';
UPDATE equations e SET description = 'Gl. (8) bestimmt das erforderliche Speichervolumen V_VA in m³. Q_zu = Zufluss während D (Gl. 3); Q_S = Versickerungsleistung (Gl. 4); Q_Dr = mittlerer Drosselabfluss (nur bei Anlagen mit Ableitung, sonst 0); D = Dauerstufe in min; f_Z = Zuschlagsfaktor 1,1–1,2 (1,2 erforderlich bei q_S,AC ≤ 5 l/(s·ha)); f_A = Abminderungsfaktor, in der Regel 1. Für alle D rechnen und das Maximum nehmen; Flächenversickerung ausgenommen (§5.3.3.7).
[EN] Eq. (8) determines the required storage volume V_VA in m³. Q_zu = inflow during D (Eq. 3); Q_S = infiltration capacity (Eq. 4); Q_Dr = mean throttled outflow (only for facilities with discharge, else 0); D = duration in min; f_Z = surcharge factor 1.1–1.2 (1.2 required at q_S,AC ≤ 5 l/(s·ha)); f_A = reduction factor, as a rule 1 for infiltration facilities. Evaluate for all D and take the maximum; area infiltration excepted (§5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND e.equation_number = '8';
UPDATE equations e SET description = 'Gl. (9) bestimmt die spezifische Versickerungs-/Abflussleistung q_S,AC in l/(s·ha). k_i = bemessungsrelevante Infiltrationsrate; A_S,m = mittlere Versickerungsfläche; Q_Dr = mittlerer Drosselabfluss (nur bei ausgewählten Anlagen); A_C = Rechenwert nach Gl. (2); 1000 und 10⁴ rechnen m³/s in l/s und m² in ha um. Ergebnis muss ≥ 2 l/(s·ha) sein (Anwendungsbedingung, Gate A138-REQ-15); bei ≤ 5 l/(s·ha) f_Z = 1,2 (§5.3.3.2, §5.3.3.7).
[EN] Eq. (9) determines the specific infiltration/outflow capacity q_S,AC in l/(s·ha). k_i = design infiltration rate; A_S,m = mean infiltration area; Q_Dr = mean throttled outflow (only for selected facilities); A_C = design value per Eq. (2); 1000 and 10⁴ convert m³/s to l/s and m² to ha. The result must be ≥ 2 l/(s·ha) (application condition of the simple method, gate A138-REQ-15); at ≤ 5 l/(s·ha) use f_Z = 1.2 (§5.3.3.2, §5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-13' AND e.equation_number = '9';
UPDATE fields f SET description = 'Ergebnis des Phase-3-Tors, vom Tool aus den allgemeinen Berechnungen (A138-10 bis 13) abgeleitet: PASS, wenn alle Anwendungsbedingungen des Einfachen Verfahrens und q_S,AC ≥ 2 l/(s·ha) erfüllt sind; CONDITIONAL, wenn Nachweise offen bleiben; FAIL, wenn eine Bedingung verletzt ist. Nur PASS oder CONDITIONAL öffnen Phase 4 (Bemessung nach Abschnitt 6, Gate A138-REQ-16). Die Einhaltung der Bedingungen ist in der Planung nachzuweisen (§5.3.3.2).
[EN] Result of the phase 3 gate, derived by the tool from the general calculations (A138-10 to 13): PASS if all application conditions of the simple method and q_S,AC ≥ 2 l/(s·ha) are met; CONDITIONAL if proofs remain open; FAIL if a condition is violated. Only PASS or CONDITIONAL open phase 4 (facility-specific design per Section 6, gate A138-REQ-16). Compliance with the conditions must be demonstrated in the design (§5.3.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'phase_3_gate_result';
UPDATE fields f SET description = 'Rechenwert A_C für die Bemessung, vom Tool nach Gl. (2) als Summe aller angeschlossenen Teilflächen mal zugehörigem Abflussbeiwert (Tab. 9) übernommen. Er geht in Q_zu (Gl. 3), q_S,AC (Gl. 9), die Flächenbelastung A_C/A_S,m (Tab. 6) und die Flächenversickerung (Gl. 12) ein; A_C ≤ 800 m² entscheidet zudem über die Spalte der Bemessungshäufigkeit in Tab. 8 (§5.3.3.4, §5.3.3.5).
[EN] Design value A_C, taken by the tool from Eq. (2) as the sum of all connected sub-areas times their runoff coefficient (Tab. 9). It enters Q_zu (Eq. 3), q_S,AC (Eq. 9), the loading ratio A_C/A_S,m (Tab. 6) and area infiltration (Eq. 12); A_C ≤ 800 m² also decides the design-frequency column of Tab. 8 (§5.3.3.4, §5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'A_C_calculated';
UPDATE fields f SET description = 'Bemessungsrelevante Infiltrationsrate aus A138-11 (Gl. 5: k_f · f_K), zur Zusammenfassung übernommen. Sie wird in allen anlagenspezifischen Blättern (A138-16 ff.) weiterverwendet. Maßgebend ist die geringer durchlässige Schicht, bei oberirdischen Anlagen einschließlich der bewachsenen Bodenzone; im Einfachen Verfahren konstant (§5.3.1, §5.3.3.6).
[EN] Design infiltration rate from A138-11 (Eq. 5: k_f · f_K), carried into the summary. It is reused in all facility-specific sheets (A138-16 ff.). The less permeable layer governs, for above-ground facilities including the vegetated soil zone; constant in the simple method (§5.3.1, §5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'k_i_calculated';
UPDATE fields f SET description = 'Versickerungsleistung aus A138-12 (Gl. 4: k_i · A_S · 10³), zur Zusammenfassung übernommen. Zusammen mit Q_zu bestimmt sie das Speichervolumen nach Gl. (8); bei Flächenversickerung muss sie den Zufluss jederzeit aufnehmen. Gilt für die gewählte Vorab-Geometrie; ändert sich diese in Phase 4, ist Q_S neu zu berechnen (§5.3.3.6, Bild 5).
[EN] Infiltration capacity from A138-12 (Eq. 4: k_i · A_S · 10³), carried into the summary. Together with Q_zu it determines the storage volume per Eq. (8); for area infiltration it must take the inflow at every moment. Valid for the trial geometry chosen; if that changes in phase 4, Q_S must be recalculated (§5.3.3.6, Bild 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'Q_S_calculated';
UPDATE fields f SET description = 'Erforderliches Speichervolumen aus A138-13 (Maximum von Gl. 8 über alle Dauerstufen), zur Zusammenfassung übernommen. Bemessungszielgröße für alle Anlagen außer Flächenversickerung; die anlagenspezifischen Blätter weisen nach, dass die gewählte Geometrie dieses Volumen bereitstellt (Abgleich nach Bild 5). Für die Bemessungshäufigkeit n darf kein Überlauf auftreten (§5.3.3.4, §5.3.3.7).
[EN] Required storage volume from A138-13 (maximum of Eq. 8 over all durations), carried into the summary. Design target for all facilities except area infiltration; the facility-specific sheets prove that the chosen geometry provides this volume (comparison per Bild 5). No overflow may occur at the design frequency n (§5.3.3.4, §5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'V_VA_calculated';
UPDATE fields f SET description = 'Vom Tool gesetzt: wahr, wenn q_S,AC nach Gl. (9) ≥ 2 l/(s·ha). Dies ist die dritte Anwendungsbedingung des Einfachen Verfahrens und bestimmt das Phase-3-Tor. Falsch bedeutet nach Bild 5: Abmessungen anpassen, anderer Anlagentyp (z. B. mit Drosselabfluss Q_Dr) oder Nachweisverfahren. Bei q_S,AC ≤ 5 l/(s·ha) ist zusätzlich f_Z = 1,2 erforderlich (§5.3.3.2, §5.3.3.7).
[EN] Set by the tool: true if q_S,AC per Eq. (9) is ≥ 2 l/(s·ha). This is the third application condition of the simple method and determines the phase 3 gate. False means per Bild 5: adjust dimensions, another facility type (e.g. with throttled outflow Q_Dr) or the verification method. At q_S,AC ≤ 5 l/(s·ha), f_Z = 1.2 is additionally required (§5.3.3.2, §5.3.3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'q_S_AC_check_result';
UPDATE fields f SET description = 'Maßgebende Dauerstufe aus der Iteration in A138-13: die Dauer D, bei der Gl. (8) das eindeutige Maximum des Speichervolumens liefert. Vom Tool übernommen; sie dokumentiert, welches Wertepaar D / r_D(n) die Bemessung bestimmt. Im Einfachen Verfahren ist D schrittweise zu bestimmen; für Flächenversickerung gilt stattdessen D = 10 bis 15 min (§5.3.3.7, Tab. 12).
[EN] Governing duration from the iteration in A138-13: the duration D at which Eq. (8) yields the unique maximum of the storage volume. Carried over by the tool; it records which pair D / r_D(n) governs the design. In the simple method D must be found step by step; for area infiltration D = 10 to 15 min applies instead (§5.3.3.7, Tab. 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'D_optimal_min';
UPDATE fields f SET description = 'Regenspende bei der maßgebenden Dauerstufe, aus der angegebenen Niederschlagstabelle für Bemessungshäufigkeit n (Tab. 8) und D_optimal; vom Tool aus A138-13 übernommen. Sie ist der Regenwert, mit dem Q_zu (Gl. 3) und V_VA (Gl. 8) bestimmt wurden. Zu verwenden sind örtliche Starkregenauswertungen nach DWA-A 531 oder aktuelle KOSTRA-Daten in der gültigen Fassung (§5.3.3.2, §5.3.3.5).
[EN] Rainfall intensity at the governing duration, from the stated rainfall table for design frequency n (Tab. 8) and D_optimal; carried over by the tool from A138-13. It is the rain value with which Q_zu (Eq. 3) and V_VA (Eq. 8) were determined. Use local heavy-rain evaluations per DWA-A 531 or current KOSTRA data in the valid version (§5.3.3.2, §5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'r_D_n_optimal';
UPDATE fields f SET description = 'Datum, an dem die allgemeinen Berechnungen nach §5.3.3 (A_C, Q_zu, k_i, Q_S, V_VA, q_S,AC) abgeschlossen und geprüft wurden; vom Bearbeiter einzutragen. Das Tool verwendet es als Zeitstempel des Phase-3-Tors im Nachweis. Werden danach Eingaben (Flächen, k_f, Geometrie) geändert, ist die Berechnung zu wiederholen und das Datum zu aktualisieren (Bild 5, Iteration).
[EN] Date on which the general calculations per §5.3.3 (A_C, Q_zu, k_i, Q_S, V_VA, q_S,AC) were completed and checked; entered by the engineer. The tool uses it as the time stamp of the phase 3 gate in the proof. If inputs (areas, k_f, geometry) change afterwards, repeat the calculation and update the date (Bild 5, iteration).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-14' AND f.symbol = 'general_calc_completion_date';
UPDATE fields f SET description = 'Bestätigung, dass für den gewählten Anlagentyp die anlagenspezifische Bemessung nach Abschnitt 6.2 bis 6.8 durchgeführt wird (Gate A138-REQ-18). Abschnitt 6 ergänzt die allgemeinen Grundsätze aus 5.3.3 um systemspezifische Bemessungsgleichungen; für Varianten sind die Besonderheiten auf Basis von 5.3.3 zu berücksichtigen und nachvollziehbar zu dokumentieren (§6.1). Ohne Bestätigung blockiert das Tor den Abschluss des Blattes.
[EN] Confirmation that the facility-specific design per Sections 6.2 to 6.8 will be carried out for the selected facility type (gate A138-REQ-18). Section 6 adds system-specific sizing equations to the general principles of 5.3.3; for variants, the particularities must be considered on the basis of 5.3.3 and documented traceably (§6.1). Without the confirmation the gate blocks completion of this sheet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-15' AND f.symbol = 'attest_a138_15_a138_req_18';
UPDATE fields f SET description = 'Gewählter Anlagentyp nach Bild 7 (Pflichtfeld, Gate A138-REQ-17). Bild 7 ordnet die Anlagen nach Systemkomponenten (Versickerung, Speicherung, Ableitung), Flächenbedarf und Versickerungsfähigkeit des Untergrunds: Versickerungsfläche (nur Versickerung, höchster Flächenbedarf) bis Schacht (geringster); Mulden-Rigolen-System immer mit Drosselabfluss, Becken und Rigole optional. Oberirdische Anlagen bevorzugen (§4.1). Die Wahl bestimmt das Blatt A138-16 ff. (§6.1).
[EN] Selected facility type per Bild 7 (required, gate A138-REQ-17). Bild 7 orders the facilities by system components (infiltration, storage, discharge), space demand and subsoil infiltration capacity: from infiltration area (infiltration only, highest space demand) to shaft (lowest); the swale–trench system always has a throttled discharge, basin and trench optionally. Prefer above-ground facilities (§4.1). The choice decides the sheet A138-16 ff. (§6.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-15' AND f.symbol = 'facility_type_selected';
UPDATE fields f SET description = 'Mehrfachauswahl der in Betracht kommenden Anlagentypen nach Abschnitt 6; das Tool bemisst die Kandidaten in A138-16 bis 22 zum Vergleich. Vorauswahl nach Bild 7: Flächenversickerung nur bei k_i > r_D(n)·10⁻⁷ und ausreichend Fläche (Gl. 13); Rigolen, wenn die Fläche für eine Mulde nicht reicht (§6.4.1); Mulden-Rigolen-System bei geringer Versickerungsfähigkeit; Becken als zentrale Anlage mit k_f ≥ 1·10⁻⁵ m/s (Tab. 14). Varianten möglich (§6.1).
[EN] Multiple selection of the facility types under consideration per Section 6; the tool sizes the candidates in A138-16 to 22 for comparison. Shortlist by Bild 7: area infiltration only if k_i > r_D(n)·10⁻⁷ and enough area (Eq. 13); trenches where the area for a swale is insufficient (§6.4.1); swale–trench system for low subsoil infiltration capacity; basin as a central facility with k_f ≥ 1·10⁻⁵ m/s (Tab. 14). Variants are possible (§6.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-15' AND f.symbol = 'a138_anlagentyp_kandidaten';
UPDATE fields f SET description = 'Freitext mit der Begründung der Anlagenwahl nach Bild 7: verfügbare Fläche, Versickerungsfähigkeit des Untergrunds (k_i; Gl. 13 für Flächenversickerung), Abstand zum MHGW (≥ 1 m, §5.2.1), Behandlungsanforderung (Tab. 6 bei bewachsener Bodenzone, Tab. 7 bei unterirdischen Anlagen), Abstände zu Gebäuden (§5.3.2). Das Tool druckt den Text im Nachweis; für Varianten sind die Berechnungsansätze nachvollziehbar zu dokumentieren (§6.1).
[EN] Free text giving the reasons for the facility choice per Bild 7: available area, infiltration capacity of the subsoil (k_i; Eq. 13 for area infiltration), distance to the MHGW (≥ 1 m, §5.2.1), treatment requirement (Tab. 6 for the vegetated soil zone, Tab. 7 for underground facilities), distances to buildings (§5.3.2). The tool prints the text in the proof; for variants the calculation approaches must be documented traceably (§6.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-15' AND f.symbol = 'a138_auswahlkriterien';
UPDATE fields f SET description = 'Textliche Angabe des gewählten Anlagentyps (Liste wie Abschnitt 6: Versickerungsfläche, Versickerungsmulde, Rigole, Mulden-Rigolen-Element, Mulden-Rigolen-System, Versickerungsschacht, Versickerungsbecken); muss zum Feld Gewählter Anlagentyp passen. Das Tool verwendet die Angabe zur Beschriftung des Nachweises; die Bemessung folgt dem zugehörigen Blatt A138-16 ff. Bei Varianten den Bezugstyp nennen und die Abweichung dokumentieren (§6.1).
[EN] Text statement of the selected facility type (list as in Section 6: infiltration area, swale, trench, swale–trench element, swale–trench system, shaft, basin); must match the field Selected Facility Type. The tool uses it to label the proof; the design follows the corresponding sheet A138-16 ff. For variants, name the reference type and document the deviation (§6.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-15' AND f.symbol = 'a138_anlagentyp_gewaehlt';
UPDATE fields f SET description = 'Erforderliche Versickerungsfläche der Flächenversickerung; das Tool berechnet sie nach Gl. (12) aus A_C, k_i und r_D(n). Sie ist hier die Bemessungszielgröße (kein Speichervolumen) und muss als ebene, gleichmäßig beschickte Fläche vorhanden sein; die Zuleitung ist möglichst breitflächig auszubilden (§6.2.1). Gültig nur, wenn Gl. (13) erfüllt ist; sonst wird das Ergebnis negativ, weil die Regenintensität die Infiltrationsrate übersteigt (§6.2.2).
[EN] Required infiltration area for area infiltration; the tool computes it per Eq. (12) from A_C, k_i and r_D(n). Here it is the design target (no storage volume) and must exist as a level, evenly loaded area; the inflow must be spread as wide as possible (§6.2.1). Valid only if Eq. (13) is met; otherwise the result is negative because the rain intensity exceeds the infiltration rate (§6.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND f.symbol = 'A_S_flaeche';
UPDATE fields f SET description = 'Quelle der verwendeten Regenspende r_D(n) für D = 10 bzw. 15 min: Rasterfeld und Version des KOSTRA-DWD-Datensatzes oder örtliche Auswertung nach DWA-A 531; das Tool dokumentiert sie im Nachweis. Aktuelle KOSTRA-Daten in der gültigen Fassung sind zu verwenden (§5.3.3.5). Bei der Flächenversickerung entfällt die Iteration über D (§6.2.2, Tab. 12).
[EN] Source of the rainfall intensity r_D(n) used for D = 10 or 15 min: grid cell and version of the KOSTRA-DWD data set or local evaluation per DWA-A 531; the tool records it in the proof. Current KOSTRA data in the valid version must be used (§5.3.3.5). For area infiltration there is no iteration over D (§6.2.2, Tab. 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = 'Erforderliche Versickerungsfläche A_s,erf nach Gl. (12), vom Tool berechnet (identisch mit dem Ergebnis oben). Sie wird mit der Bemessungs-Versickerungsfläche verglichen: die ausgeführte Fläche muss mindestens A_s,erf betragen. Bei Entwässerung über eine durchlässige Flächenbefestigung ist k_i in Gl. (12) und (13) durch die Aufnahmefähigkeit des Belags in m/s zu ersetzen; der Untergrund muss einen Einstau im Oberbau vermeiden (§6.2.2).
[EN] Required infiltration area A_s,erf per Eq. (12), computed by the tool (identical to the result above). It is compared with the design infiltration area: the area built must be at least A_s,erf. Where drainage runs over a permeable pavement, replace k_i in Eq. (12) and (13) by the absorption capacity of the pavement in m/s; the subsoil must prevent ponding in the pavement structure (§6.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND f.symbol = 'a138_A_s_erf';
UPDATE fields f SET description = 'Regenspende für Dauerstufe D und Bemessungshäufigkeit n (Tab. 8) in l/(s·ha), aus KOSTRA-DWD bzw. DWA-A 531 für D = 10 min (bzw. 15 min). Das Tool setzt sie in Gl. (12) und in die Bedingung Gl. (13) ein: k_i > r_D(n)·10⁻⁷ (Gate A138-REQ-31). Je höher r_D(n) gegenüber k_i, desto größer die erforderliche Fläche (§6.2.2, §5.3.3.5).
[EN] Rainfall intensity for duration D and design frequency n (Tab. 8) in l/(s·ha), from KOSTRA-DWD or DWA-A 531 for D = 10 min (or 15 min). The tool inserts it into Eq. (12) and into the condition Eq. (13): k_i > r_D(n)·10⁻⁷ (gate A138-REQ-31). The higher r_D(n) relative to k_i, the larger the required area (§6.2.2, §5.3.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND f.symbol = 'r_D_n_used';
UPDATE fields f SET description = 'Vom Tool gesetzt: wahr, wenn Gl. (13) erfüllt ist, k_i > r_D(n)·10⁻⁷ (10⁻⁷ rechnet l/(s·ha) in m/s um). Nur dann liefert Gl. (12) ein hydrologisch sinnvolles Ergebnis; sonst ist die Fläche negativ, weil die Niederschlagsintensität die Infiltrationsrate übersteigt – Flächenversickerung ist dann nicht möglich, eine Anlage mit Speicher wählen. Gate A138-REQ-31 blockiert bei falsch. Für k_i ggf. die bewachsene Bodenzone berücksichtigen (§6.2.2).
[EN] Set by the tool: true if Eq. (13) holds, k_i > r_D(n)·10⁻⁷ (10⁻⁷ converts l/(s·ha) to m/s). Only then does Eq. (12) give a hydrologically meaningful result; otherwise the area is negative because the rain intensity exceeds the infiltration rate – area infiltration is then impossible, choose a facility with storage. Gate A138-REQ-31 blocks when false. Consider the vegetated soil zone for k_i where applicable (§6.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND f.symbol = 'k_i_ge_r_check';
UPDATE fields f SET description = 'Dauerstufe des Bemessungsregens für die Flächenversickerung in min. In der Regel D = 10 min; bei großen und flach geneigten Anschlussflächen darf D = 15 min gewählt werden (§6.2.2, Tab. 12: 10–15 min). Keine Iteration, da die Anlage keinen Speicher hat. Das Tool liest mit D und n die Regenspende r_D(n) für Gl. (12) und (13) aus der Niederschlagstabelle. Die Begründung für 15 min dokumentieren.
[EN] Duration of the design rain for area infiltration in min. As a rule D = 10 min; for large and gently sloping connected areas D = 15 min may be chosen (§6.2.2, Tab. 12: 10–15 min). No iteration, since the facility has no storage. With D and n the tool reads the rainfall intensity r_D(n) for Eq. (12) and (13) from the rainfall table. Document the reason for 15 min.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND f.symbol = 'D_min_used';
UPDATE fields f SET description = 'Tatsächlich vorgesehene Versickerungsfläche in m² aus der Planung (ebene Fläche, z. B. Rasen oder unbefestigter Randstreifen). Das Tool vergleicht sie mit A_s,erf nach Gl. (12): die Bemessungsfläche muss mindestens so groß sein. Nur die gleichmäßig beschickte Fläche darf angesetzt werden; ein gleichmäßiger Übergang des Wassers über die gesamte Fläche ist sicherzustellen und durch Unterhaltung dauerhaft zu gewährleisten (§6.2.1).
[EN] Infiltration area actually provided in m² from the design (level area, e.g. lawn or unpaved edge strip). The tool compares it with A_s,erf per Eq. (12): the design area must be at least as large. Only the evenly loaded area may be counted; an even transition of the water across the whole area must be ensured and maintained in the long term (§6.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND f.symbol = 'a138_A_s_dim';
UPDATE equations e SET description = 'Gl. (11) ist die Wasserbilanz der Flächenversickerung ohne Speicher: Zufluss von den angeschlossenen Flächen plus Regen auf die Versickerungsfläche selbst gleich Versickerung. A_C = Rechenwert nach Gl. (2); A_S = Versickerungsfläche; r_D(n) = Regenspende für D und n; k_i = Infiltrationsrate nach Gl. (5); 10⁻⁷ rechnet l/(s·ha) in m/s um. Das Tool nutzt die Umformung Gl. (12). Die Fläche selbst wird durch den Bemessungsregen belastet (§6.2.2).
[EN] Eq. (11) is the water balance of area infiltration without storage: inflow from the connected areas plus rain on the infiltration area itself equals the infiltration. A_C = design value per Eq. (2); A_S = infiltration area; r_D(n) = rainfall intensity for D and n; k_i = infiltration rate per Eq. (5); 10⁻⁷ converts l/(s·ha) to m/s. The tool uses the rearrangement Eq. (12). The infiltration area itself is loaded by the design rain (§6.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND e.equation_number = '11';
UPDATE equations e SET description = 'Gl. (12) bestimmt die erforderliche Versickerungsfläche A_S der Flächenversickerung durch Umformung von Gl. (11). A_C = Rechenwert nach Gl. (2); k_i = Infiltrationsrate nach Gl. (5) in m/s; r_D(n) = Regenspende für D = 10 (bis 15) min und Häufigkeit n. Das Ergebnis ist die Bemessungszielgröße und wird mit der vorgesehenen Fläche verglichen. Nur sinnvoll, wenn Gl. (13) gilt; bei durchlässigen Belägen k_i durch deren Aufnahmefähigkeit ersetzen (§6.2.2).
[EN] Eq. (12) determines the required infiltration area A_S for area infiltration by rearranging Eq. (11). A_C = design value per Eq. (2); k_i = design infiltration rate per Eq. (5) in m/s; r_D(n) = rainfall intensity for D = 10 (up to 15) min and frequency n. The result is the design target and is compared with the area provided. Meaningful only if Eq. (13) holds; for permeable pavements replace k_i by the pavement absorption capacity (§6.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND e.equation_number = '12';
UPDATE equations e SET description = 'Gl. (13) ist die Anwendungsbedingung der Flächenversickerung: k_i (m/s) muss größer sein als die Regenintensität r_D(n)·10⁻⁷ (l/(s·ha) in m/s umgerechnet). Nur dann liefert Gl. (12) ein positives, hydrologisch sinnvolles Ergebnis. Sonst ist Flächenversickerung für diesen Bemessungsregen nicht möglich (Gate A138-REQ-31); Anlage mit Speicher wählen. Tab. 14 fordert zusätzlich k_f ≥ 1·10⁻⁶ m/s für die maßgebliche Bodenschicht (§6.2.2, §6.9).
[EN] Eq. (13) is the applicability condition for area infiltration: k_i (m/s) must exceed the rain intensity r_D(n)·10⁻⁷ (l/(s·ha) converted to m/s). Only then does Eq. (12) give a positive, hydrologically meaningful result. If violated, area infiltration is not possible for this design rain (gate A138-REQ-31); choose a facility with storage. Tab. 14 additionally requires k_f ≥ 1·10⁻⁶ m/s for the relevant soil layer (§6.2.2, §6.9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-16' AND e.equation_number = '13';
UPDATE fields f SET description = 'Neigung der Muldenböschungen (1 : m), vom Planer gewählt. Das Tool hält sie mit der Mulden-Geometrie (b_M, L_M, h_M) fest und prüft sie gegen die Vorgabe der Richtlinie. §5.3.5: 1 : 3 ist bautechnisch und betrieblich geeignet, höchstens 1 : 1,5; Tab. 14: für Mulden i. d. R. 1 : 1,5 oder flacher — flachere Böschungen begünstigen die Verkehrssicherung.
[EN] Inclination of the swale side slopes (1 : m), chosen by you. The tool records it with the swale geometry (b_M, L_M, h_M) and checks it against the guideline value. §5.3.5: 1 : 3 is suitable in construction and operation, at most 1 : 1.5; Tab. 14: for swales as a rule 1 : 1.5 or flatter — flatter slopes favour safety.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'boeschungsneigung';
UPDATE fields f SET description = 'Abstand zwischen höchstem Bemessungswasserspiegel und Böschungsoberkante (Tab. 14 Anm. 2), vom Planer gewählt. Das Tool addiert ihn zur Einstauhöhe h_M für die Gesamttiefe der Mulde. Tab. 14 nennt für die reine Mulde keinen Freibord-Wert („–“, nur Mulden-Rigolen ≥ 10 cm, Becken ≥ 35 cm); im Wohnumfeld zählt er aber in die Grenze von max. 40 cm Wassertiefe inkl. Freibord nach §5.3.5 (DIN 18034-1).
[EN] Distance between the highest design water level and the top edge of the slope (Tab. 14 note 2), chosen by you. The tool adds it to the ponding depth h_M to get the total swale depth. Tab. 14 gives no freeboard value for a plain swale (“–”; only swale-trench ≥ 10 cm, basin ≥ 35 cm); in residential surroundings it counts towards the limit of max. 40 cm water depth including freeboard per §5.3.5 (DIN 18034-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'freibord';
UPDATE fields f SET description = 'Maximale Einstauhöhe in der Mulde, vom Planer gewählt. Das Tool rechnet damit das vorhandene Speichervolumen V_M = A_S,m · h_M (Gl. 15) und kann daraus den Flächenbedarf A_S,m nach Gl. 16 abschätzen. §6.3.1 / Tab. 14: der Bemessungseinstau ist i. d. R. auf 30 cm zu begrenzen; im Wohnumfeld zusätzlich max. 40 cm inkl. Freibord (§5.3.5).
[EN] Maximum ponding depth in the swale, chosen by you. The tool uses it for the available storage V_M = A_S,m · h_M (Eq. 15) and can estimate the required area A_S,m from it with Eq. 16. §6.3.1 / Tab. 14: the design ponding depth is as a rule to be limited to 30 cm; in residential surroundings additionally max. 40 cm including freeboard (§5.3.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'h_M';
UPDATE fields f SET description = 'Entleerungszeit der Mulde nach einem Einstau, optional; physikalisch näherungsweise h / k_i (Studienbuch), im Einfachen Verfahren ist kein rechnerischer Nachweis erforderlich, weil die Anwendungsgrenze q_S,AC ≥ 2 l/(s·ha) nach Gl. 9 greift (§6.3.2). Das Tool zeigt den Wert informativ an. §6.3.2 / Tab. 14: ≤ 84 h für n = 1/a ist vegetationstechnisch i. d. R. unkritisch; bei Langzeitsimulation ist die Einstaudauer für n = 1/a zu prüfen.
[EN] Emptying time of the swale after an impoundment, optional; physically about h / k_i (study book). In the simple method no computational proof is required because the application limit q_S,AC ≥ 2 l/(s·ha) of Eq. 9 applies (§6.3.2). The tool shows the value for information. §6.3.2 / Tab. 14: ≤ 84 h for n = 1/a is as a rule uncritical for vegetation; in long-term simulation the impoundment duration for n = 1/a must be checked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 't_E';
UPDATE fields f SET description = 'VORHANDENES Speichervolumen der Mulde, vom Tool aus der gewählten Geometrie berechnet: V_M = A_S,m · h_M (Gl. 15, „näherungsweise“). Gegenstück ist V_M,erf aus der Speichergleichung Gl. 14; die Mulde ist bemessen, wenn V_M ≥ V_M,erf (Prüfung A138-REQ-34). Hebel bei Unterdeckung: Sohlenfläche bzw. A_S,m vergrößern oder h_M bis zur Grenze von i. d. R. 30 cm (Tab. 14) erhöhen. Gl. 15 überschätzt das Volumen geböschter Mulden leicht (Studienbuch).
[EN] AVAILABLE storage volume of the swale, computed by the tool from the chosen geometry: V_M = A_S,m · h_M (Eq. 15, “approximately”). Its counterpart is V_M,req from the storage equation Eq. 14; the swale is sized when V_M ≥ V_M,req (check A138-REQ-34). If short: enlarge the base area / A_S,m or raise h_M up to the limit of as a rule 30 cm (Tab. 14). Eq. 15 slightly over-estimates the volume of sloped swales (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'V_M';
UPDATE fields f SET description = 'Quelle der verwendeten Regenspenden r_D(n), vom Planer als Referenz eingetragen (z. B. KOSTRA-DWD-2020, Rasterfeld). Das Tool dokumentiert damit die Herkunft aller r_D(n)-Werte dieses Blattes. §5.3.3.5: örtliche Starkregenauswertungen nach DWA-A 531 oder aktuelle KOSTRA-Datensätze verwenden; bei KOSTRA die exakten Werte des DWD (DWD-Vorgabe); das Arbeitsblatt bezieht sich auf KOSTRA-DWD-2020.
[EN] Source of the rainfall intensities r_D(n) used, entered by you as a reference (e.g. KOSTRA-DWD-2020, grid cell). The tool uses it to document the origin of all r_D(n) values on this sheet. §5.3.3.5: use local heavy-rain evaluations per DWA-A 531 or current KOSTRA data sets; with KOSTRA use the exact DWD values (DWD specification); the guideline refers to KOSTRA-DWD-2020.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = 'Überregnete Fläche der Mulde, d. h. die Fläche, deren Regen direkt in die Mulde fällt; vom Planer aus der geplanten Geometrie bestimmt oder näherungsweise A_VA = A_S,m gesetzt (§6.3.2, beide Optionen zulässig). Das Tool addiert sie in Gl. 14 zu A_C (Abflussbeiwert 1) für V_M,erf; fehlt sie, fällt es auf das Projekt-A_VA bzw. A_S,m zurück. Bei kleinen Anschlussflächen ist der Anteil erheblich — Weglassen unterbemisst die Mulde (Studienbuch).
[EN] Rained-on area of the swale, i.e. the area whose rain falls directly into the swale; determined by you from the planned geometry or set approximately as A_VA = A_S,m (§6.3.2, both options permitted). The tool adds it to A_C in Eq. 14 (runoff coefficient 1) for V_M,req; if empty it falls back to the project A_VA or A_S,m. For small connected areas the share is considerable — omitting it under-sizes the swale (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'A_VA_Mulde';
UPDATE fields f SET description = 'Breite der Muldensohle, vom Planer gewählt. Das Tool bildet daraus mit L_M die Sohlfläche A_S,min, mit Böschung und h_M die Fläche bei Volleinstau A_S,max und daraus A_S,m = (A_S,min + A_S,max)/2 (Gl. 7) für Gl. 14/15. Bei Mulden-Rigolen-Elementen wird die Muldenbreite i. d. R. gleich der Rigolenbreite gewählt (§6.5.1).
[EN] Width of the swale base, chosen by you. From it and L_M the tool forms the base area A_S,min, with the slope and h_M the area at full impoundment A_S,max, and from these A_S,m = (A_S,min + A_S,max)/2 (Eq. 7) for Eq. 14/15. In swale-trench elements the swale width is as a rule chosen equal to the trench width (§6.5.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'b_M';
UPDATE fields f SET description = 'Länge der Muldensohle, vom Planer gewählt. Das Tool bildet daraus mit b_M die Sohlfläche A_S,min und über die Böschungsgeometrie A_S,max und A_S,m (Gl. 7) für Gl. 14/15. §6.3.1: Sohlenebenen und -linien horizontal herstellen; große oder lange Mulden bei Geländegefälle durch Bodenschwellen abtreppen (Kaskaden) — dann jede Stufe als eigene Mulde ansetzen.
[EN] Length of the swale base, chosen by you. From it and b_M the tool forms the base area A_S,min and, via the slope geometry, A_S,max and A_S,m (Eq. 7) for Eq. 14/15. §6.3.1: build base planes and base lines horizontal; step large or long swales on sloping ground with soil sills (cascades) — then treat each step as its own swale.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'L_M';
UPDATE fields f SET description = 'Bemessungshäufigkeit der Mulde in 1/a, vom Planer nach Tab. 8 gewählt (Schutzkategorie und A_C ≤ / > 800 m²; z. B. Kategorie 2 bei A_C ≤ 800 m²: ≤ 0,2/a). Das Tool wählt damit die Spalte r_D(n) der Regentabelle für Gl. 14/16 und iteriert über die Dauerstufen D. §5.3.3.4: für diese Häufigkeit darf kein Überlauf aus der Anlage auftreten; bei Mulden-Rigolen-Elementen wird die Mulde i. d. R. mit n = 1/a bemessen (§6.5.2).
[EN] Design frequency of the swale in 1/a, chosen by you per Tab. 8 (protection category and A_C ≤ / > 800 m²; e.g. category 2 with A_C ≤ 800 m²: ≤ 0.2/a). The tool uses it to select the r_D(n) column of the rainfall table for Eq. 14/16 and iterates over the durations D. §5.3.3.4: no overflow from the facility may occur for this frequency; in swale-trench elements the swale is as a rule sized for n = 1/a (§6.5.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'n_M_Bemessung';
UPDATE fields f SET description = 'Bemessungsrelevante Infiltrationsrate, mit der diese Mulde in Gl. 14 und Gl. 16 rechnet; serverseitig gesetzt. Eigenständige Mulde: k_i der maßgeblichen Bodenschicht (A138-05/A138-11), wobei die bewachsene Bodenzone zu berücksichtigen ist (§6.3.2). Mulde eines Mulden-Rigolen-Elements/-Systems: k_i,BBZ der bewachsenen Bodenzone aus A138-19/A138-20, weil die Rigole mit dem anstehenden Boden rechnet (§6.5.2). Tab. 14: k_f der bewachsenen Bodenzone im langjährigen Betrieb ca. 1·10⁻⁵ m/s.
[EN] Design infiltration rate used by this swale in Eq. 14 and Eq. 16; set by the server. Stand-alone swale: k_i of the governing soil layer (A138-05/A138-11), taking the vegetated soil zone into account (§6.3.2). Swale of a swale-trench element/system: k_i,BBZ of the vegetated soil zone from A138-19/A138-20, because the trench is sized with the natural soil (§6.5.2). Tab. 14: k_f of the vegetated soil zone in long-term operation about 1·10⁻⁵ m/s.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'k_i_Mulde';
UPDATE fields f SET description = 'ERFORDERLICHES Speichervolumen der Mulde aus der Speichergleichung Gl. 14, vom Tool berechnet: Maximum über die Dauerstufen D der Bemessungshäufigkeit n_M mit r_D(n), A_C + A_VA, A_S,m, k_i_Mulde und f_Z. Das Feld V_M (Gl. 15 mit gewählter Einstauhöhe) ist das vorhandene Volumen; die Prüfung A138-REQ-34 verlangt V_M ≥ V_M,erf. §6.3.2: iterative Berechnung für unterschiedliche Dauerstufen D mit zugehöriger Regenspende; §5.3.3.7: f_Z 1,1–1,2, bei q_S,AC ≤ 5 l/(s·ha) ist f_Z = 1,2 erforderlich.
[EN] REQUIRED storage volume of the swale from the storage equation Eq. 14, computed by the tool: maximum over the durations D of the design frequency n_M with r_D(n), A_C + A_VA, A_S,m, k_i_Mulde and f_Z. The field V_M (Eq. 15 with the chosen ponding depth) is the available volume; check A138-REQ-34 requires V_M ≥ V_M,req. §6.3.2: iterative calculation for different durations D with their rainfall intensity; §5.3.3.7: f_Z 1.1–1.2, f_Z = 1.2 required when q_S,AC ≤ 5 l/(s·ha).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND f.symbol = 'V_M_erf';
UPDATE equations e SET description = 'Speichergleichung der Mulde: erforderliches Volumen V_M,erf = [(A_C + A_VA)·10⁻⁷·r_D(n) − A_S,m·k_i]·D·60·f_Z. Zufluss aus Anschlussfläche A_C plus überregneter Muldenfläche A_VA minus Versickerung über die mittlere Versickerungsfläche A_S,m mit k_i, mal Dauer D (min) und Zuschlagsfaktor f_Z. Das Tool iteriert über alle Dauerstufen D mit zugehörigem r_D(n); das Maximum ist V_M,erf und wird gegen V_M (Gl. 15) geprüft. §6.3.2: A_S,m und k_i werden als konstant angenommen; A_VA aus Geometrie oder ≈ A_S,m.
[EN] Storage equation of the swale: required volume V_M,req = [(A_C + A_VA)·10⁻⁷·r_D(n) − A_S,m·k_i]·D·60·f_Z. Inflow from the connected area A_C plus the rained-on swale area A_VA, minus infiltration through the mean infiltration area A_S,m with k_i, times duration D (min) and surcharge factor f_Z. The tool iterates over all durations D with their r_D(n); the maximum is V_M,req and is checked against V_M (Eq. 15). §6.3.2: A_S,m and k_i are assumed constant; A_VA from geometry or ≈ A_S,m.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND e.equation_number = '14';
UPDATE equations e SET description = 'Geometrisches Speichervolumen der Mulde: V_M = A_S,m · h_M (mittlere Versickerungsfläche mal maximale Einstauhöhe). Das Tool berechnet daraus das VORHANDENE Volumen der gewählten Geometrie und vergleicht es mit V_M,erf aus Gl. 14 (A138-REQ-34). §6.3.2 nennt die Gleichung „näherungsweise“; sie gilt als Alternative bei Vorgabe von h_M (i. d. R. ≤ 30 cm, Tab. 14) und überschätzt das Volumen geböschter Mulden leicht.
[EN] Geometric storage volume of the swale: V_M = A_S,m · h_M (mean infiltration area times maximum ponding depth). The tool computes from it the AVAILABLE volume of the chosen geometry and compares it with V_M,req from Eq. 14 (A138-REQ-34). §6.3.2 calls the equation “approximate”; it serves as the alternative when h_M is given (as a rule ≤ 30 cm, Tab. 14) and slightly over-estimates the volume of sloped swales.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND e.equation_number = '15';
UPDATE equations e SET description = 'Flächenbedarf bei vorgegebener Einstauhöhe: A_S,m = A_C·10⁻⁷·r_D(n) / [h_M/(D·60·f_Z) + k_i] — Gl. 15 in Gl. 14 eingesetzt, A_VA vernachlässigt, nach A_S,m aufgelöst. Das Tool iteriert über die Dauerstufen D; das Maximum ist die erforderliche mittlere Versickerungsfläche. §6.3.2: der Flächenbedarf entspricht mindestens A_S,max aus Gl. 7; da A_VA fehlt, ist das Ergebnis eine Abschätzung — die Endbemessung erfolgt mit Gl. 14 und der realen Geometrie (Studienbuch).
[EN] Required area for a given ponding depth: A_S,m = A_C·10⁻⁷·r_D(n) / [h_M/(D·60·f_Z) + k_i] — Eq. 15 inserted into Eq. 14, A_VA neglected, solved for A_S,m. The tool iterates over the durations D; the maximum is the required mean infiltration area. §6.3.2: the land required is at least A_S,max from Eq. 7; because A_VA is missing the result is an estimate — the final design uses Eq. 14 with the real geometry (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-17' AND e.equation_number = '16';
UPDATE fields f SET description = 'Größe einer einzelnen Sickeröffnung des Versickerrohrs in cm², aus den Herstellerangaben (§6.4.2). Das Tool rechnet damit und mit az_SÖ den spezifischen Wasseraustritt q_VS nach Gl. 24 für den Kapazitätsnachweis Gl. 25. Liegen keine Herstellerangaben vor, Feld leer lassen und die Näherungswerte nach §6.4.2 verwenden (Kiessand 0,2, Kies 16/32 5 l/(s·m)).
[EN] Size of one seepage opening of the infiltration pipe in cm², from the manufacturer''s data (§6.4.2). The tool uses it with az_SÖ to compute the specific water exit q_VS per Eq. 24 for the capacity check Eq. 25. If no manufacturer data exist, leave the field empty and use the approximate values of §6.4.2 (sandy gravel 0.2, gravel 16/32 5 l/(s·m)).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'A_SOE';
UPDATE fields f SET description = 'Anzahl gleichartiger Versickerrohre im Rigolenquerschnitt, vom Planer gewählt. Das Tool rechnet damit den Speicherkoeffizienten s_R nach Gl. 21 (dickwandige Rohre, d_i ≠ d_a) bzw. Gl. 22 (dünnwandige Kunststoffrohre, d = d_i ≈ d_a): jedes Rohr erhöht das Speichervolumen, weil sein Innenraum leerer ist als das verdrängte Schüttmaterial. Nur bei Rigolen aus Schüttmaterial relevant; bei Fertigteilen kommt s_R vom Hersteller (§6.4.2).
[EN] Number of identical infiltration pipes in the trench cross-section, chosen by you. The tool uses it for the storage coefficient s_R per Eq. 21 (thick-walled pipes, d_i ≠ d_a) or Eq. 22 (thin-walled plastic pipes, d = d_i ≈ d_a): each pipe adds storage because its interior is emptier than the fill it displaces. Relevant only for gravel-filled trenches; for prefabricated units s_R comes from the manufacturer (§6.4.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'az';
UPDATE fields f SET description = 'Anzahl der Sickeröffnungen je Meter Versickerrohr (1/m), aus den Herstellerangaben (§6.4.2). Das Tool rechnet damit und mit A_SÖ den spezifischen Wasseraustritt q_VS = 0,1·az_SÖ·A_SÖ·10⁻¹ (Gl. 24, Austrittsgeschwindigkeit v = 0,1 m/s) für den Nachweis Gl. 25. Ohne Herstellerangaben leer lassen und den Näherungswert nach Schüttmaterial verwenden.
[EN] Number of seepage openings per metre of infiltration pipe (1/m), from the manufacturer''s data (§6.4.2). The tool uses it with A_SÖ for the specific water exit q_VS = 0.1·az_SÖ·A_SÖ·10⁻¹ (Eq. 24, exit velocity v = 0.1 m/s) for the check Eq. 25. Without manufacturer data leave it empty and use the approximate value by fill material.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'az_SOE';
UPDATE fields f SET description = 'Breite des Rigolenquerschnitts, vom Planer zweckmäßig gewählt (§6.4.2: b_R und h_R werden gewählt, Zielgröße ist L_R). Das Tool rechnet damit die mittlere Versickerungsfläche A_S,m = (b_R + h_R)·L_R + b_R·h_R (Gl. 17), Q_S (Gl. 18), V_R (Gl. 19/20), s_R (Gl. 21/22) und die erforderliche Länge L_R (Gl. 23). Bei Mulden-Rigolen-Elementen wird die Muldenbreite i. d. R. gleich b_R gewählt (§6.5.1).
[EN] Width of the trench cross-section, chosen sensibly by you (§6.4.2: b_R and h_R are chosen, the target is L_R). The tool uses it for the mean infiltration area A_S,m = (b_R + h_R)·L_R + b_R·h_R (Eq. 17), Q_S (Eq. 18), V_R (Eq. 19/20), s_R (Eq. 21/22) and the required length L_R (Eq. 23). In swale-trench elements the swale width is as a rule chosen equal to b_R (§6.5.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'b_R';
UPDATE fields f SET description = 'Außendurchmesser des Versickerrohrs in m, aus den Herstellerangaben. Das Tool rechnet damit in Gl. 21 den vom Rohr verdrängten Schüttmaterial-Anteil (az·π/4·d_a²) des Speicherkoeffizienten s_R. Bei dünnwandigen Kunststoffrohren darf die Wandstärke vernachlässigt werden (d = d_i ≈ d_a, Gl. 22, §6.4.2). Achtung Einheit: Tab. 2 führt Durchmesser in mm, die Gleichungen rechnen in m (Studienbuch).
[EN] Outer diameter of the infiltration pipe in m, from the manufacturer''s data. The tool uses it in Eq. 21 for the fill displaced by the pipe (az·π/4·d_a²) within the storage coefficient s_R. For thin-walled plastic pipes the wall thickness may be neglected (d = d_i ≈ d_a, Eq. 22, §6.4.2). Mind the unit: Tab. 2 lists diameters in mm, the equations use m (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'd_a';
UPDATE fields f SET description = 'Innendurchmesser des Versickerrohrs in m, aus den Herstellerangaben. Das Tool rechnet damit in Gl. 21 das Speichervolumen des Rohrinnenraums (az·π/4·d_i²/s_F) im Speicherkoeffizienten s_R; bei dünnwandigen Rohren gilt d = d_i ≈ d_a (Gl. 22). §6.4.2: nur für Rigolen aus Schüttmaterial — bei Fertigteilen ist s_R den Herstellerangaben zu entnehmen.
[EN] Inner diameter of the infiltration pipe in m, from the manufacturer''s data. The tool uses it in Eq. 21 for the storage of the pipe interior (az·π/4·d_i²/s_F) within the storage coefficient s_R; for thin-walled pipes d = d_i ≈ d_a (Eq. 22). §6.4.2: only for gravel-filled trenches — for prefabricated units s_R is taken from the manufacturer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'd_i';
UPDATE fields f SET description = 'Höhe des Rigolenquerschnitts, vom Planer zweckmäßig gewählt. Das Tool rechnet damit A_S,m (Gl. 17: Seitenwände zählen bis zum mittleren Wasserstand h_R/2), Q_S (Gl. 18), V_R (Gl. 19/20), s_R (Gl. 21/22) und L_R (Gl. 23). §6.4.2: im Einfachen Verfahren wird über die gesamte Einstauzeit der mittlere Wasserstand h_R/2 angenommen; die Rigole reicht nicht bis zur Geländeoberkante (§6.4.1), und ihre Unterkante muss den Abstand a zum MHGW nach §5.2.1 einhalten.
[EN] Height of the trench cross-section, chosen sensibly by you. The tool uses it for A_S,m (Eq. 17: side walls count up to the mean water level h_R/2), Q_S (Eq. 18), V_R (Eq. 19/20), s_R (Eq. 21/22) and L_R (Eq. 23). §6.4.2: the simple method assumes the mean water level h_R/2 during the whole impoundment; the trench does not reach the ground surface (§6.4.1), and its bottom must keep the distance a to the MHGW per §5.2.1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'h_R';
UPDATE fields f SET description = 'Erforderliche Länge der Rigole, vom Tool nach Gl. 23 berechnet: iterative Anwendung für alle Dauerstufen D mit zugehörigem r_D(n), das Maximum ist maßgebend. Sie ist der Mindestwert; die ausgeführte Rigolenlänge darf nicht kürzer sein und geht in A_S,m (Gl. 17), Q_S (Gl. 18) und das vorhandene Volumen V_R = b_R·h_R·L_R·s_R (Gl. 20) ein. §6.4.1: das Versickerrohr sollte über die ganze Länge des Rigolenkörpers eingebaut werden (Bezug zu L_VS).
[EN] Required trench length, computed by the tool per Eq. 23: iterative application for all durations D with their r_D(n), the maximum governs. It is the minimum value; the built trench length must not be shorter and enters A_S,m (Eq. 17), Q_S (Eq. 18) and the available volume V_R = b_R·h_R·L_R·s_R (Eq. 20). §6.4.1: the infiltration pipe should be installed over the full length of the trench body (link to L_VS).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'L_R';
UPDATE fields f SET description = 'Gesamtlänge der Vollsickerrohre zur Zuleitung in die Rigole in m, vom Planer gewählt (§6.4.1: möglichst über die ganze Rigolenlänge). Das Tool prüft damit die hydraulische Leistungsfähigkeit des Wasseraustritts: L_VS · q_VS ≥ r_5(n) · A_C · 10⁻⁴ (Gl. 25, Gate A138-REQ-32, blockierend). Reicht die Länge nicht, Rohrlänge, Öffnungen oder Schüttmaterial (q_VS) anpassen.
[EN] Total length of the fully perforated pipes feeding the trench in m, chosen by you (§6.4.1: preferably over the full trench length). The tool uses it to check the hydraulic capacity of the water exit: L_VS · q_VS ≥ r_5(n) · A_C · 10⁻⁴ (Eq. 25, gate A138-REQ-32, blocking). If the length is insufficient, adjust pipe length, openings or fill material (q_VS).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'L_VS';
UPDATE fields f SET description = 'Spezifischer Wasseraustritt des Versickerrohrs in l/(s·m): vom Tool nach Gl. 24 aus az_SÖ und A_SÖ berechnet (q_VS = 0,1·az_SÖ·A_SÖ·10⁻¹, v = 0,1 m/s) oder als Näherungswert nach Schüttmaterial gesetzt (§6.4.2: Kiessand 0,2 l/(s·m), Kies z. B. 16/32 5 l/(s·m)). Geht in den Nachweis Gl. 25 (A138-REQ-32) ein. Die Leistung hängt von Art/Anzahl der Öffnungen, Rohrlänge, Druckhöhe und Füllmaterial ab — Kiessand drosselt den Austritt stark (Faktor 25, Studienbuch).
[EN] Specific water exit of the infiltration pipe in l/(s·m): computed by the tool per Eq. 24 from az_SÖ and A_SÖ (q_VS = 0.1·az_SÖ·A_SÖ·10⁻¹, v = 0.1 m/s) or set as the approximate value by fill (§6.4.2: sandy gravel 0.2 l/(s·m), gravel e.g. 16/32 5 l/(s·m)). It enters the check Eq. 25 (A138-REQ-32). Capacity depends on type/number of openings, pipe length, pressure head and fill — sandy gravel throttles the exit strongly (factor 25, study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'q_VS';
UPDATE fields f SET description = 'Speicherkoeffizient (nutzbarer Porenanteil) des Füll-/Schüttmaterials, vom Lieferanten oder aus Versuch; die Richtlinie nennt keinen Zahlenwert (0,35 für Kies ist ein typischer Erfahrungswert, Studienbuch). Das Tool rechnet damit s_R nach Gl. 21/22. §6.4.2: bei Rigolen aus Schüttmaterial wird s_R anteilig aus s_F und dem Speichervolumen der eingebetteten Versickerrohre berechnet; bei Fertigteilen s_R direkt vom Hersteller.
[EN] Storage coefficient (usable pore share) of the fill material, from the supplier or a test; the guideline gives no numerical value (0.35 for gravel is a typical experience value, study book). The tool uses it for s_R per Eq. 21/22. §6.4.2: for gravel-filled trenches s_R is calculated proportionally from s_F and the storage of the embedded infiltration pipes; for prefabricated units s_R comes directly from the manufacturer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 's_F';
UPDATE fields f SET description = 'Speicherkoeffizient der Rigole = Anteil des verfügbaren Speichervolumens am Rigolenkörper (§6.4.2). Vom Tool nach Gl. 21 (Schüttmaterial, dickwandige Rohre) bzw. Gl. 22 (dünnwandige Rohre) aus s_F, az, d_i, d_a berechnet; bei Fertigteilen (Füllkörper, Tunnelelemente) den Herstellerwert eintragen. Geht in V_R = b_R·h_R·L_R·s_R (Gl. 20) und in L_R (Gl. 23) ein — ein höheres s_R verkürzt die Rigole, verkleinert aber A_S,m und verlängert die Entleerung (Studienbuch).
[EN] Storage coefficient of the trench = share of the trench body available for water (§6.4.2). Computed by the tool per Eq. 21 (fill, thick-walled pipes) or Eq. 22 (thin-walled pipes) from s_F, az, d_i, d_a; for prefabricated units (crates, tunnel elements) enter the manufacturer''s value. Enters V_R = b_R·h_R·L_R·s_R (Eq. 20) and L_R (Eq. 23) — a higher s_R shortens the trench but reduces A_S,m and lengthens emptying (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 's_R';
UPDATE fields f SET description = 'Speichervolumen der Rigole. Das Tool berechnet das ERFORDERLICHE Volumen nach Gl. 19 (Zufluss A_C·10⁻⁷·r_D(n) minus Versickerung A_S,m·k_i minus Drosselabfluss Q_Dr·10⁻³, mal D·60·f_Z, Maximum über D) und das VORHANDENE Volumen nach Gl. 20 (b_R·h_R·L_R·s_R); vorhanden ≥ erforderlich ist die Bemessungsbedingung, aus der Gl. 23 folgt. §6.4.2: ohne Ableitung ist Q_Dr = 0; anders als bei der Mulde gibt es kein A_VA, da die Rigole überdeckt ist.
[EN] Storage volume of the trench. The tool computes the REQUIRED volume per Eq. 19 (inflow A_C·10⁻⁷·r_D(n) minus infiltration A_S,m·k_i minus throttle Q_Dr·10⁻³, times D·60·f_Z, maximum over D) and the AVAILABLE volume per Eq. 20 (b_R·h_R·L_R·s_R); available ≥ required is the sizing condition from which Eq. 23 follows. §6.4.2: without a discharge Q_Dr = 0; unlike the swale there is no A_VA, because the trench is covered.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'V_R';
UPDATE fields f SET description = 'Quelle der verwendeten Regenspenden r_D(n) und r_5(n), vom Planer als Referenz eingetragen (z. B. KOSTRA-DWD-2020, Rasterfeld). Das Tool dokumentiert damit die Herkunft der Regendaten dieses Blattes. §5.3.3.5: Starkregenauswertungen nach DWA-A 531 oder aktuelle KOSTRA-Datensätze; bei KOSTRA die exakten DWD-Werte verwenden.
[EN] Source of the rainfall intensities r_D(n) and r_5(n) used, entered by you as a reference (e.g. KOSTRA-DWD-2020, grid cell). The tool uses it to document the origin of the rainfall data of this sheet. §5.3.3.5: heavy-rain evaluations per DWA-A 531 or current KOSTRA data sets; with KOSTRA use the exact DWD values.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = 'Regenspende r_D(n) in l/(s·ha) für die maßgebende Dauerstufe D und die Bemessungshäufigkeit n_R, vom Tool aus der Regentabelle bei der Iteration von Gl. 19/23 ermittelt (die Dauerstufe mit der größten erforderlichen Länge L_R ist maßgebend). Wird mit der zugehörigen Dauerstufe dokumentiert. §6.4.2: die erforderliche Länge L_R erhält man durch iterative Anwendung der Gl. 23 für unterschiedliche Dauerstufen D und jeweils zugehöriger Regenspende r_D(n).
[EN] Rainfall intensity r_D(n) in l/(s·ha) for the governing duration D and the design frequency n_R, determined by the tool from the rainfall table during the iteration of Eq. 19/23 (the duration with the largest required length L_R governs). Documented together with its duration. §6.4.2: the required length L_R is obtained by iterative application of Eq. 23 for different durations D with their rainfall intensity r_D(n).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'r_D_n_used_R';
UPDATE fields f SET description = 'Regenspende für die Dauerstufe D = 5 min und die gewählte Bemessungshäufigkeit n, vom Tool aus der Regentabelle entnommen. Sie liefert den maximalen Zufluss zur Rigole r_5(n)·A_C·10⁻⁴ (l/s) für den hydraulischen Nachweis des Versickerrohrs L_VS·q_VS ≥ r_5(n)·A_C·10⁻⁴ (Gl. 25, A138-REQ-32). §6.4.2: der Rohrnachweis wird bewusst mit dem kurzen, intensiven 5-min-Regen geführt, nicht mit der maßgebenden Dauerstufe der Volumenbemessung.
[EN] Rainfall intensity for the duration D = 5 min and the chosen design frequency n, taken by the tool from the rainfall table. It gives the peak inflow to the trench r_5(n)·A_C·10⁻⁴ (l/s) for the hydraulic check of the infiltration pipe L_VS·q_VS ≥ r_5(n)·A_C·10⁻⁴ (Eq. 25, A138-REQ-32). §6.4.2: the pipe check is deliberately made with the short, intense 5-min rain, not with the governing duration of the volume sizing.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'r_5_n';
UPDATE fields f SET description = 'Bemessungshäufigkeit der Rigole in 1/a, vom Planer nach Tab. 8 gewählt (Schutzkategorie, A_C ≤ / > 800 m²). Das Tool wählt damit die r_D(n)-Spalte für Gl. 19/23 und r_5(n) für Gl. 25. §5.3.3.4: für die Bemessungshäufigkeit nach Tab. 8 darf kein Überlauf aus der Versickerungsanlage auftreten; die Ableitung eines Drosselabflusses ist nur zulässig, wenn reine Versickerung wegen der Bodendurchlässigkeit nicht möglich ist (§6.4.2).
[EN] Design frequency of the trench in 1/a, chosen by you per Tab. 8 (protection category, A_C ≤ / > 800 m²). The tool uses it to select the r_D(n) column for Eq. 19/23 and r_5(n) for Eq. 25. §5.3.3.4: for the design frequency per Tab. 8 no overflow from the infiltration facility may occur; a throttled discharge is only permitted when pure infiltration is impossible because of the soil permeability (§6.4.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'n_R_Bemessung';
UPDATE fields f SET description = 'Schüttmaterial der Rigole (Kiessand oder Kies, z. B. 16/32), vom Planer gewählt. Das Tool leitet daraus den Näherungswert für q_VS ab, wenn keine Herstellerangaben zu den Sickeröffnungen vorliegen: Kiessand 0,2 l/(s·m), Kies 5 l/(s·m) (§6.4.2). Liegen az_SÖ und A_SÖ vor, geht Gl. 24 vor. Hinweis: das Material bestimmt auch s_F (Porenanteil) — dieser Wert kommt vom Lieferanten.
[EN] Fill material of the trench (sandy gravel or gravel, e.g. 16/32), chosen by you. The tool derives from it the approximate q_VS when no manufacturer data on the seepage openings exist: sandy gravel 0.2 l/(s·m), gravel 5 l/(s·m) (§6.4.2). If az_SÖ and A_SÖ are given, Eq. 24 takes precedence. Note: the material also determines s_F (pore share) — that value comes from the supplier.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND f.symbol = 'schuettmaterial';
UPDATE equations e SET description = 'Mittlere Versickerungsfläche einer quaderförmigen Rigole: A_S,m = (b_R + h_R)·L_R + b_R·h_R — Sohle plus beide Seitenwände bis zum mittleren Wasserstand h_R/2 je Meter, plus die zwei Stirnflächen bis h_R/2. Das Tool rechnet damit Q_S (Gl. 18), V_R (Gl. 19) und das Verhältnis A_C/A_S,m. §6.4.2: bei langgestreckten Rigolen können die Stirnflächen (b_R·h_R) vernachlässigt werden; nur Flächen ansetzen, über die Wasser tatsächlich in den Boden gelangt.
[EN] Mean infiltration area of a box-shaped trench: A_S,m = (b_R + h_R)·L_R + b_R·h_R — base plus both side walls up to the mean water level h_R/2 per metre, plus the two end faces up to h_R/2. The tool uses it for Q_S (Eq. 18), V_R (Eq. 19) and the ratio A_C/A_S,m. §6.4.2: for elongated trenches the end faces (b_R·h_R) may be neglected; count only areas through which water actually enters the soil.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '17';
UPDATE equations e SET description = 'Versickerungsleistung der Rigole Q_S = A_S,m · k_i mit A_S,m nach Gl. 17 — Ergebnis in m³/s (ohne den Faktor 10³ der allgemeinen Gl. 4). Das Tool rechnet damit den Versickerungsanteil in Gl. 19 und die spezifische Leistung q_S,AC nach Gl. 9. §6.4.2: k_i ist die bemessungsrelevante Infiltrationsrate des anstehenden Bodens nach Gl. 5; Gl. 9 verlangt q_S,AC ≥ 2 l/(s·ha) als Anwendungsgrenze des Einfachen Verfahrens.
[EN] Infiltration capacity of the trench Q_S = A_S,m · k_i with A_S,m per Eq. 17 — result in m³/s (without the factor 10³ of the general Eq. 4). The tool uses it for the infiltration term in Eq. 19 and the specific capacity q_S,AC per Eq. 9. §6.4.2: k_i is the design infiltration rate of the natural soil per Eq. 5; Eq. 9 requires q_S,AC ≥ 2 l/(s·ha) as the application limit of the simple method.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '18';
UPDATE equations e SET description = 'Erforderliches Speichervolumen der Rigole aus der Grundgleichung Gl. 8: V_R = [A_C·10⁻⁷·r_D(n) − ((b_R + h_R)·L_R + b_R·h_R)·k_i − Q_Dr·10⁻³]·D·60·f_Z. Zufluss nur aus A_C (kein A_VA, die Rigole ist überdeckt), minus Versickerung, minus mittlerer Drosselabfluss Q_Dr (l/s → m³/s). Das Tool iteriert über D; das Maximum wird mit dem vorhandenen Volumen nach Gl. 20 verglichen. §6.4.2: bei reiner Versickerung Q_Dr = 0.
[EN] Required storage volume of the trench from the basic Eq. 8: V_R = [A_C·10⁻⁷·r_D(n) − ((b_R + h_R)·L_R + b_R·h_R)·k_i − Q_Dr·10⁻³]·D·60·f_Z. Inflow only from A_C (no A_VA, the trench is covered), minus infiltration, minus mean throttled outflow Q_Dr (l/s → m³/s). The tool iterates over D; the maximum is compared with the available volume per Eq. 20. §6.4.2: for pure infiltration Q_Dr = 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '19';
UPDATE equations e SET description = 'Vorhandenes Speichervolumen der quaderförmigen Rigole: V_R = b_R · h_R · L_R · s_R — Rigolenkörper mal Speicherkoeffizient. Das Tool rechnet damit das verfügbare Volumen der gewählten Abmessungen und stellt es dem erforderlichen Volumen aus Gl. 19 gegenüber; aus „Gl. 20 = Gl. 19“ folgt die Längengleichung Gl. 23. §6.4.2: s_R nach Gl. 21/22 (Schüttmaterial) oder Herstellerangabe (Fertigteile).
[EN] Available storage volume of the box-shaped trench: V_R = b_R · h_R · L_R · s_R — trench body times storage coefficient. The tool uses it for the available volume of the chosen dimensions and sets it against the required volume from Eq. 19; from “Eq. 20 = Eq. 19” follows the length equation Eq. 23. §6.4.2: s_R per Eq. 21/22 (fill) or manufacturer''s data (prefabricated units).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '20';
UPDATE equations e SET description = 'Speicherkoeffizient einer Schüttmaterial-Rigole mit eingebetteten Versickerrohren (Kreisquerschnitt, Wandstärke berücksichtigt): s_R = s_F/(b_R·h_R)·[b_R·h_R + az·π/4·(d_i²/s_F − d_a²)]. Porenvolumen des Schüttmaterials plus der (zu 100 % leere) Rohrinnenraum minus das vom Rohr verdrängte Material, bezogen auf den Querschnitt. Das Tool rechnet damit s_R für Gl. 20/23. §6.4.2: gilt für Rigolen aus Schüttmaterial; bei Fertigteilen s_R vom Hersteller.
[EN] Storage coefficient of a gravel-filled trench with embedded infiltration pipes (circular, wall thickness considered): s_R = s_F/(b_R·h_R)·[b_R·h_R + az·π/4·(d_i²/s_F − d_a²)]. Pore volume of the fill plus the (100 % void) pipe interior minus the fill displaced by the pipe, related to the cross-section. The tool uses it for s_R in Eq. 20/23. §6.4.2: applies to gravel-filled trenches; for prefabricated units s_R from the manufacturer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '21';
UPDATE equations e SET description = 'Vereinfachter Speicherkoeffizient für dünnwandige Kunststoffrohre, bei denen die Wandstärke vernachlässigt wird (d = d_i ≈ d_a): s_R = s_F/(b_R·h_R)·[b_R·h_R + az·π·d²/4·(1/s_F − 1)]. Der Term (1/s_F − 1) ist der Zusatz-Hohlraum des Rohrs gegenüber dem gleichen Raum voll Schüttmaterial. Das Tool verwendet diese Form, wenn d_a ≈ d_i angegeben ist, sonst Gl. 21; Ergebnis für Gl. 20/23 (§6.4.2).
[EN] Simplified storage coefficient for thin-walled plastic pipes where the wall thickness is neglected (d = d_i ≈ d_a): s_R = s_F/(b_R·h_R)·[b_R·h_R + az·π·d²/4·(1/s_F − 1)]. The term (1/s_F − 1) is the extra void of the pipe compared with the same space filled with gravel. The tool uses this form when d_a ≈ d_i is given, otherwise Eq. 21; result for Eq. 20/23 (§6.4.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '22';
UPDATE equations e SET description = 'Bemessungsgleichung der Rigole für die erforderliche Länge bei gewähltem Querschnitt: L_R = [A_C·10⁻⁷·r_D(n) − b_R·h_R·k_i − Q_Dr·10⁻³] / [b_R·h_R·s_R/(D·60·f_Z) + (b_R + h_R)·k_i] — Zähler: zu bewältigender Zufluss minus Versickerung der Stirnflächen minus Drossel; Nenner: Speicher- und Versickerungsleistung je Meter Rigole. §6.4.2: iterative Anwendung für unterschiedliche Dauerstufen D mit zugehöriger r_D(n), das Maximum ist L_R; das Tool prüft zusätzlich Gl. 9 (q_S,AC ≥ 2 l/(s·ha)).
[EN] Sizing equation of the trench for the required length at a chosen cross-section: L_R = [A_C·10⁻⁷·r_D(n) − b_R·h_R·k_i − Q_Dr·10⁻³] / [b_R·h_R·s_R/(D·60·f_Z) + (b_R + h_R)·k_i] — numerator: inflow to be handled minus end-face infiltration minus throttle; denominator: storage and infiltration capacity per metre of trench. §6.4.2: iterative application for different durations D with their r_D(n), the maximum is L_R; the tool additionally checks Eq. 9 (q_S,AC ≥ 2 l/(s·ha)).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '23';
UPDATE equations e SET description = 'Spezifischer Wasseraustritt des Versickerrohrs: q_VS = 0,1 · az_SÖ · A_SÖ · 10⁻¹ in l/(s·m) — Austrittsgeschwindigkeit v = 0,1 m/s mal Öffnungen je Meter mal Öffnungsfläche (cm², Faktor 10⁻¹ für cm² → m² und m³ → l). Das Tool rechnet damit q_VS aus Herstellerangaben für den Nachweis Gl. 25. §6.4.2: ohne Herstellerangaben Näherungswerte verwenden — Kiessand 0,2 l/(s·m), Kies (z. B. 16/32) 5 l/(s·m).
[EN] Specific water exit of the infiltration pipe: q_VS = 0.1 · az_SÖ · A_SÖ · 10⁻¹ in l/(s·m) — exit velocity v = 0.1 m/s times openings per metre times opening area (cm², factor 10⁻¹ for cm² → m² and m³ → l). The tool computes q_VS from manufacturer data for the check Eq. 25. §6.4.2: without manufacturer data use approximate values — sandy gravel 0.2 l/(s·m), gravel (e.g. 16/32) 5 l/(s·m).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '24';
UPDATE equations e SET description = 'Nachweis der hydraulischen Leistungsfähigkeit des Versickerrohrs: L_VS · q_VS ≥ r_5(n) · A_C · 10⁻⁴ — der Wasseraustritt der gesamten Rohrlänge muss den maximalen Zufluss (l/s) beim 5-min-Regen der Bemessungshäufigkeit aufnehmen. Das Tool prüft die Bedingung als Gate A138-REQ-32 (blockierend). §6.4.2: Nachweis mit r_5(n) für D = 5 min und der gewählten Bemessungshäufigkeit n, „mit ausreichender Genauigkeit“ für die gewählte Rohrlänge.
[EN] Check of the hydraulic capacity of the infiltration pipe: L_VS · q_VS ≥ r_5(n) · A_C · 10⁻⁴ — the water exit of the whole pipe length must take the peak inflow (l/s) of the 5-min rain at the design frequency. The tool checks the condition as gate A138-REQ-32 (blocking). §6.4.2: proof with r_5(n) for D = 5 min and the chosen design frequency n, “with sufficient accuracy” for the chosen pipe length.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-18' AND e.equation_number = '25';
UPDATE fields f SET description = 'Prüfergebnis des Tools: liegt die geplante Überlaufhäufigkeit der Mulde in die Rigole innerhalb des Grenzwerts nach Tab. 6 (n_M_overflow_limit)? Die Überlaufhäufigkeit wird aus Qualitätsgründen begrenzt, weil Überlaufwasser die bewachsene Bodenzone umgeht (§6.5.1). Tab. 6: Überlauf in Rigole mit n_M max. 2/a für Belastungskategorie I, max. 1/a für Kategorie II und III; die Mulde wird i. d. R. mit n = 1/a bemessen (§6.5.2).
[EN] Check result of the tool: is the planned overflow frequency of the swale into the trench within the Tab. 6 limit (n_M_overflow_limit)? The overflow frequency is limited for quality reasons because overflow water bypasses the vegetated soil zone (§6.5.1). Tab. 6: overflow into the trench with n_M max. 2/a for pollution category I, max. 1/a for categories II and III; the swale is as a rule sized for n = 1/a (§6.5.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'n_M_overflow_check';
UPDATE fields f SET description = 'Grenzwert der statistischen Überlaufhäufigkeit n_M der Mulde in die Rigole nach Tab. 6, vom Tool aus der Belastungskategorie der angeschlossenen Flächen abgeleitet: 2/a bei Kategorie I (D, VW1, V1, BG1), 1/a bei Kategorie II und III. Dient der Prüfung n_M_overflow_check. §6.5.1: die Begrenzung erfolgt vor dem Hintergrund der stofflichen Flächenbelastung, weil der Wegfall der Bodenpassage nur für geringe Überlaufmengen unbedenklich ist.
[EN] Limit of the statistical overflow frequency n_M of the swale into the trench per Tab. 6, derived by the tool from the pollution category of the connected surfaces: 2/a for category I (D, VW1, V1, BG1), 1/a for categories II and III. Used for the check n_M_overflow_check. §6.5.1: the limit reflects the pollutant load of the surfaces, because the loss of the soil passage is unproblematic only for small overflow quantities.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'n_M_overflow_limit';
UPDATE fields f SET description = 'Bemessungshäufigkeit der Rigole des Mulden-Rigolen-Elements in 1/a, vom Planer nach Tab. 6 und Tab. 8 gewählt. Das Tool wählt damit r_D(n) für Gl. 28/29 (Gesamtvolumen und Rigolenlänge) und r_D(n_R) für den Muldenüberlauf Gl. 30. §6.5.2: die Mulde wird i. d. R. mit n = 1/a bemessen und damit größer (häufiger) als die Rigole; §5.3.3.4: für n nach Tab. 8 darf kein Überlauf aus dem Gesamtsystem auftreten.
[EN] Design frequency of the trench of the swale-trench element in 1/a, chosen by you per Tab. 6 and Tab. 8. The tool uses it to select r_D(n) for Eq. 28/29 (total volume and trench length) and r_D(n_R) for the swale overflow Eq. 30. §6.5.2: the swale is as a rule sized for n = 1/a and thus a larger (more frequent) value than the trench; §5.3.3.4: for n per Tab. 8 no overflow from the overall system may occur.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'n_R';
UPDATE fields f SET description = 'Erforderliches Gesamtspeichervolumen des Mulden-Rigolen-Elements, vom Tool berechnet: V_MR = V_M + V_R (Gl. 26) bzw. aus der Grundgleichung mit Rigolen-Versickerungsfläche nach Gl. 17: V_MR = [(A_C + A_VA)·10⁻⁷·r_D(n) − ((b_R + h_R)·L_R + b_R·h_R)·k_i]·D·60·f_Z (Gl. 28, Maximum über D). Zufluss ist der Zufluss zur Mulde, Abfluss nur die Versickerung aus der Rigole in den anstehenden Boden. §6.5.2: gilt nur bei vorhandenem Muldenüberlauf; ohne Überlauf Mulde und Rigole getrennt nach 6.3.2/6.4.2 bemessen.
[EN] Required total storage volume of the swale-trench element, computed by the tool: V_MR = V_M + V_R (Eq. 26) or from the basic equation with the trench infiltration area per Eq. 17: V_MR = [(A_C + A_VA)·10⁻⁷·r_D(n) − ((b_R + h_R)·L_R + b_R·h_R)·k_i]·D·60·f_Z (Eq. 28, maximum over D). Inflow is the inflow to the swale, outflow only the infiltration from the trench into the natural soil. §6.5.2: applies only with a swale overflow; without one, size swale and trench separately per 6.3.2/6.4.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'V_MR';
UPDATE fields f SET description = 'Quelle der verwendeten Regenspenden r_D(n) und r_D(n_R), vom Planer als Referenz eingetragen (z. B. KOSTRA-DWD-2020, Rasterfeld). Das Tool dokumentiert damit die Herkunft der Regendaten dieses Blattes. §5.3.3.5: Starkregenauswertungen nach DWA-A 531 oder aktuelle KOSTRA-Datensätze; bei KOSTRA die exakten DWD-Werte verwenden.
[EN] Source of the rainfall intensities r_D(n) and r_D(n_R) used, entered by you as a reference (e.g. KOSTRA-DWD-2020, grid cell). The tool uses it to document the origin of the rainfall data of this sheet. §5.3.3.5: heavy-rain evaluations per DWA-A 531 or current KOSTRA data sets; with KOSTRA use the exact DWD values.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = 'Speichervolumen der Mulde des Elements, vom Tool aus A138-17 übernommen (V_M = A_S,m · h_M, Gl. 15; bemessen für die Muldenhäufigkeit i. d. R. n = 1/a mit k_i der bewachsenen Bodenzone). Es ist der erste Schritt der zweistufigen Bemessung: V_M geht als Abzug V_M/(D·60·f_Z) in die Rigolenlänge Gl. 29 und als Abzug in das Überlaufvolumen Gl. 30 ein; V_R = V_MR − V_M (Gl. 27). §6.5.2: maßgebliche Bodenschicht der Mulde ist die bewachsene Bodenzone.
[EN] Storage volume of the swale of the element, taken by the tool from A138-17 (V_M = A_S,m · h_M, Eq. 15; sized for the swale frequency as a rule n = 1/a with k_i of the vegetated soil zone). It is the first step of the two-step sizing: V_M enters the trench length Eq. 29 as the deduction V_M/(D·60·f_Z) and the overflow volume Eq. 30 as a deduction; V_R = V_MR − V_M (Eq. 27). §6.5.2: the governing soil layer of the swale is the vegetated soil zone.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'V_M_MRE';
UPDATE fields f SET description = 'Erforderliches Speichervolumen der Rigole des Elements, vom Tool als Volumenbilanz V_R = V_MR − V_M (Gl. 27) berechnet — zweiter Schritt der Bemessung. Daraus bzw. direkt nach Gl. 29 folgt die Rigolenlänge L_R bei gewähltem Querschnitt b_R, h_R; das vorhandene Rigolenvolumen ist b_R·h_R·L_R·s_R (Gl. 20, A138-18). §6.5.2: die Rigole versickert mit dem k_i des anstehenden Bodens, nicht mit dem der bewachsenen Bodenzone.
[EN] Required storage volume of the trench of the element, computed by the tool as the volume balance V_R = V_MR − V_M (Eq. 27) — second step of the sizing. From it, or directly via Eq. 29, follows the trench length L_R for the chosen cross-section b_R, h_R; the available trench volume is b_R·h_R·L_R·s_R (Eq. 20, A138-18). §6.5.2: the trench infiltrates with the k_i of the natural soil, not that of the vegetated soil zone.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'V_R_MRE';
UPDATE fields f SET description = 'Überregnete Fläche der Mulde des Mulden-Rigolen-Elements, vom Planer aus der Muldengeometrie bestimmt oder näherungsweise A_VA = A_S,m gesetzt (§6.5.2: „analog zur Muldenbemessung, siehe 6.3.2“). Das Tool addiert sie in Gl. 28, 29 und 30 zu A_C (Zufluss zur Mulde) und nutzt sie in Gl. 31 als Versickerungsfläche beim Überlauf. Bei kleinen Anschlussflächen ist der Anteil erheblich (Studienbuch).
[EN] Rained-on area of the swale of the swale-trench element, determined by you from the swale geometry or set approximately as A_VA = A_S,m (§6.5.2: “analogous to swale sizing, see 6.3.2”). The tool adds it to A_C in Eq. 28, 29 and 30 (inflow to the swale) and uses it in Eq. 31 as the infiltrating area during overflow. For small connected areas the share is considerable (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'A_VA_MRE';
UPDATE fields f SET description = 'Wasserdurchlässigkeit der bewachsenen Bodenzone, optional. Für die MULDE des Elements ist sie die maßgebliche Bodenschicht (§6.5.2); die Rigole versickert mit dem k_i des anstehenden Bodens (A138-11). Erfüllt der Boden 5.2.3.2 und Bild 1, darf k_f,BBZ mit 1·10⁻⁵ bis 5·10⁻⁵ m/s angesetzt werden (Quelle „Bereich nach 5.3.3.6“, f_Methode entfällt); sonst Messwert (f_Methode nach Tab. 11 gilt). Leer = Mulde rechnet mit dem Projekt-k_i. §6.5.1: nach langjährigem Betrieb k_f ≥ 1·10⁻⁵ m/s.
[EN] Permeability of the vegetated soil zone, optional. For the SWALE of the element it is the governing layer (§6.5.2); the trench infiltrates with the k_i of the natural soil (A138-11). If the soil meets 5.2.3.2 and Bild 1, k_f,BBZ may be set at 1·10⁻⁵ to 5·10⁻⁵ m/s (source “range per 5.3.3.6”, f_Methode neglected); otherwise a measured value (f_Methode per Tab. 11 applies). Empty = the swale uses the project k_i. §6.5.1: k_f ≥ 1·10⁻⁵ m/s after long-term operation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'k_f_BBZ';
UPDATE fields f SET description = 'Herkunft von k_f,BBZ, vom Planer gewählt: „Bereich nach 5.3.3.6“ (1·10⁻⁵ bis 5·10⁻⁵ m/s) oder „gemessen“. Das Tool bestimmt daraus den Korrekturfaktor für k_i,BBZ: im Bereichsfall nur f_Ort (f_Methode entfällt), im Messfall f_K = f_Ort · f_Methode nach Gl. 6. §5.3.3.6: der Korrekturfaktor für die Bestimmungsmethode f_Methode nach Tab. 11 ist beim Bereichsansatz zu vernachlässigen.
[EN] Source of k_f,BBZ, chosen by you: “range per 5.3.3.6” (1·10⁻⁵ to 5·10⁻⁵ m/s) or “measured”. The tool derives from it the correction factor for k_i,BBZ: in the range case only f_Ort (f_Methode neglected), in the measured case f_K = f_Ort · f_Methode per Eq. 6. §5.3.3.6: the correction factor for the determination method f_Methode per Tab. 11 is to be neglected when the range value is used.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'k_f_BBZ_quelle';
UPDATE fields f SET description = 'Bemessungsrelevante Infiltrationsrate der Mulde: k_i,BBZ = k_f,BBZ · f_Ort (Bereich nach 5.3.3.6) bzw. k_f,BBZ · f_K (gemessen) — Gl. 5/6 auf die bewachsene Bodenzone angewandt; serverseitig berechnet. Wird auf A138-17 als k_i_Mulde übernommen: die Mulde dieses Elements rechnet Gl. 14/16 und den Muldenüberlauf (Gl. 30/31) damit, die Rigole (Gl. 28/29) mit dem Projekt-k_i des anstehenden Bodens. §6.5.2: maßgebliche Bodenschicht der Mulde ist die bewachsene Bodenzone.
[EN] Design infiltration rate of the swale: k_i,BBZ = k_f,BBZ · f_Ort (range per 5.3.3.6) or k_f,BBZ · f_K (measured) — Eq. 5/6 applied to the vegetated soil zone; computed by the server. Forwarded to A138-17 as k_i_Mulde: the swale of this element uses it in Eq. 14/16 and the swale overflow (Eq. 30/31), the trench (Eq. 28/29) uses the project k_i of the natural soil. §6.5.2: the governing soil layer of the swale is the vegetated soil zone.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND f.symbol = 'k_i_BBZ';
UPDATE equations e SET description = 'Gesamtspeichervolumen des Mulden-Rigolen-Elements mit Muldenüberlauf: V_MR = V_M + V_R — Summe aus erforderlichem Mulden- und Rigolenvolumen. Das Tool bildet damit das Gesamtvolumen aus den Teilvolumina (A138-17, A138-18) und vergleicht es mit Gl. 28. §6.5.2: gilt nur, wenn ein Überlauf von der Mulde in die Rigole vorhanden ist; ohne Überlauf sind getrennte Bemessungen nach 6.3.2 und 6.4.2 durchzuführen (Nachweisverfahren empfohlen).
[EN] Total storage volume of the swale-trench element with swale overflow: V_MR = V_M + V_R — sum of the required swale and trench volumes. The tool forms the total from the partial volumes (A138-17, A138-18) and compares it with Eq. 28. §6.5.2: applies only if an overflow from the swale into the trench exists; without one, separate sizings per 6.3.2 and 6.4.2 are required (verification method recommended).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND e.equation_number = '26';
UPDATE equations e SET description = 'Volumenbilanz für die Rigole: V_R = V_MR − V_M — das erforderliche Rigolenvolumen ist das Gesamtvolumen nach Gl. 28 abzüglich des im ersten Schritt bemessenen Muldenvolumens. Das Tool nutzt sie als zweiten Bemessungsschritt; mit Gl. 20 eingesetzt entsteht daraus die Längengleichung Gl. 29. §6.5.2: V_M ist das Muldenvolumen für die Muldenhäufigkeit (i. d. R. n = 1/a).
[EN] Volume balance for the trench: V_R = V_MR − V_M — the required trench volume is the total volume per Eq. 28 minus the swale volume sized in the first step. The tool uses it as the second sizing step; with Eq. 20 inserted it yields the length equation Eq. 29. §6.5.2: V_M is the swale volume for the swale frequency (as a rule n = 1/a).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND e.equation_number = '27';
UPDATE equations e SET description = 'Gesamtvolumen aus der Grundgleichung Gl. 8 mit Systemgrenze um Mulde und Rigole: V_MR = [(A_C + A_VA)·10⁻⁷·r_D(n) − ((b_R + h_R)·L_R + b_R·h_R)·k_i]·D·60·f_Z. Zufluss = Zufluss zur Mulde (inkl. Regen auf die Mulde), Abfluss = Versickerung aus der quaderförmigen Rigole (Gl. 17) mit k_i des anstehenden Bodens; die Sickerung Mulde → Rigole bleibt innerhalb der Systemgrenze. Das Tool iteriert über D (Häufigkeit n_R). §6.5.2: das Verhältnis A_C/A_S,m nach Tab. 6 ist nachzuweisen.
[EN] Total volume from the basic Eq. 8 with the system boundary around swale and trench: V_MR = [(A_C + A_VA)·10⁻⁷·r_D(n) − ((b_R + h_R)·L_R + b_R·h_R)·k_i]·D·60·f_Z. Inflow = inflow to the swale (incl. rain on the swale), outflow = infiltration from the box-shaped trench (Eq. 17) with k_i of the natural soil; the seepage swale → trench stays inside the boundary. The tool iterates over D (frequency n_R). §6.5.2: the ratio A_C/A_S,m per Tab. 6 must be verified.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND e.equation_number = '28';
UPDATE equations e SET description = 'Rigolenlänge des Mulden-Rigolen-Elements bei gewähltem Querschnitt: L_R = [(A_C + A_VA)·10⁻⁷·r_D(n) − b_R·h_R·k_i − V_M/(D·60·f_Z)] / [b_R·h_R·s_R/(D·60·f_Z) + (b_R + h_R)·k_i] — Gl. 28 und Gl. 20 in Gl. 27 eingesetzt. Der Abzug V_M/(D·60·f_Z) ist der Beitrag des Muldenvolumens; er verkürzt die Rigole. §6.5.2: iterative Anwendung für unterschiedliche Dauerstufen D mit zugehörigen r_D(n); das Maximum ist L_R; Muldenlänge und -breite ggf. an die Rigole anpassen.
[EN] Trench length of the swale-trench element at a chosen cross-section: L_R = [(A_C + A_VA)·10⁻⁷·r_D(n) − b_R·h_R·k_i − V_M/(D·60·f_Z)] / [b_R·h_R·s_R/(D·60·f_Z) + (b_R + h_R)·k_i] — Eq. 28 and Eq. 20 inserted into Eq. 27. The deduction V_M/(D·60·f_Z) is the contribution of the swale volume; it shortens the trench. §6.5.2: iterative application for different durations D with their r_D(n); the maximum is L_R; adapt swale length and width to the trench if necessary.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND e.equation_number = '29';
UPDATE equations e SET description = 'Anzeige-Gleichung für die Infiltrationsrate der Mulde: k_i_BBZ = k_f_BBZ · f_Ort (Quelle „Bereich nach 5.3.3.6“) bzw. k_f_BBZ · f_K (Quelle „gemessen“) — Gl. 5/6 auf die bewachsene Bodenzone angewandt. Der Server schreibt k_i_BBZ und übergibt es als k_i_Mulde an A138-17 (Gl. 14/16, 30/31). §5.3.3.6: beim Bereichsansatz 1·10⁻⁵ bis 5·10⁻⁵ m/s ist f_Methode nach Tab. 11 zu vernachlässigen, f_Ort bleibt (Tab. 10: 0,3–1,0).
[EN] Display equation for the swale infiltration rate: k_i_BBZ = k_f_BBZ · f_Ort (source “range per 5.3.3.6”) or k_f_BBZ · f_K (source “measured”) — Eq. 5/6 applied to the vegetated soil zone. The server writes k_i_BBZ and passes it to A138-17 as k_i_Mulde (Eq. 14/16, 30/31). §5.3.3.6: with the range value 1·10⁻⁵ to 5·10⁻⁵ m/s, f_Methode per Tab. 11 is neglected, f_Ort remains (Tab. 10: 0.3–1.0).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-19' AND e.equation_number = 'A138-19-D1';
UPDATE fields f SET description = 'Mittlerer, konstanter Drosselabfluss des Mulden-Rigolen-Systems in l/s, vom Tool nach Gl. 33 berechnet: Q_Dr = (Q_Dr,min + Q_Dr,max)/2. Geht als Abzug Q_Dr·10⁻³ in die Rigolenlänge Gl. 32 und in q_S,AC nach Gl. 9 ein — die Drossel kann ein System auf schwach durchlässigem Boden erst über die Anwendungsgrenze 2 l/(s·ha) heben (Studienbuch). §6.6.2: im Einfachen Verfahren darf mit hinreichender Genauigkeit ein konstanter Mittelwert angesetzt werden.
[EN] Mean, constant throttled outflow of the swale-trench system in l/s, computed by the tool per Eq. 33: Q_Dr = (Q_Dr,min + Q_Dr,max)/2. It enters the trench length Eq. 32 as the deduction Q_Dr·10⁻³ and q_S,AC per Eq. 9 — on poorly permeable soil the throttle may be what lifts the system above the application limit 2 l/(s·ha) (study book). §6.6.2: in the simple method a constant mean value may be used with sufficient accuracy.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'Q_Dr';
UPDATE fields f SET description = 'Maximaler Drosselabfluss der gewählten Drosseleinrichtung in l/s, aus den Herstellerangaben. Das Tool mittelt ihn mit Q_Dr,min zu Q_Dr (Gl. 33). §6.6.2: die maximale Leistung der Drossel muss mit der Wasserbehörde oder dem Kanalnetzbetreiber abgestimmt werden — erst abstimmen, dann bemessen; ein später reduzierter Wert verlängert die Rigole erheblich (Studienbuch).
[EN] Maximum throttled outflow of the chosen throttle device in l/s, from the manufacturer''s data. The tool averages it with Q_Dr,min to Q_Dr (Eq. 33). §6.6.2: the maximum capacity of the throttle must be agreed with the water authority or the sewer operator — agree first, then size; a value reduced later lengthens the trench considerably (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'Q_Dr_max';
UPDATE fields f SET description = 'Minimaler Drosselabfluss der gewählten Drosseleinrichtung in l/s, aus den Herstellerangaben. Das Tool mittelt ihn mit Q_Dr,max zu Q_Dr (Gl. 33). §6.6.2: je nach Drosseltyp kann ein stark veränderlicher Abfluss wirksam werden; das Einfache Verfahren ersetzt ihn durch den konstanten Mittelwert.
[EN] Minimum throttled outflow of the chosen throttle device in l/s, from the manufacturer''s data. The tool averages it with Q_Dr,max to Q_Dr (Eq. 33). §6.6.2: depending on the throttle type a strongly variable outflow can occur; the simple method replaces it by the constant mean.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'Q_Dr_min';
UPDATE fields f SET description = 'Bemessungsabfluss für den Muldenüberlauf in l/s, vom Tool nach Gl. 31 berechnet: Q_MÜ = A_C·10⁻⁴·r_MÜ − A_VA·k_i·1000 (Abfluss der Anschlussflächen bei der maßgeblichen Regenspende minus Versickerung auf der Muldenfläche mit k_i der bewachsenen Bodenzone). Dient der Auswahl eines Überlaufs mit ausreichender hydraulischer Leistungsfähigkeit (§6.5.2, für das System analog §6.6.2). V_MÜ ≤ 0 für alle D bedeutet: kein Überlauf, Q_MÜ = 0.
[EN] Design discharge for the swale overflow in l/s, computed by the tool per Eq. 31: Q_MÜ = A_C·10⁻⁴·r_MÜ − A_VA·k_i·1000 (runoff of the connected surfaces at the governing intensity minus infiltration on the swale area with k_i of the vegetated soil zone). Used to select an overflow with sufficient hydraulic capacity (§6.5.2, for the system analogously §6.6.2). V_MÜ ≤ 0 for all D means: no overflow, Q_MÜ = 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'Q_MUE';
UPDATE fields f SET description = 'Maßgebliche Regenspende des Muldenüberlaufs in l/(s·ha), vom Tool aus der Iteration von Gl. 30 bestimmt: die Regenspende r_D(n_R) der KLEINSTEN Dauerstufe, für die V_MÜ > 0 ist. Geht in Gl. 31 ein. §6.5.2: ergibt sich für eine Dauerstufe D ein Wert größer als Null, liegt ein Überlauf vor; die kürzeste überlaufende Dauerstufe hat die höchste Intensität und ist für den Abfluss (l/s) maßgebend (Studienbuch).
[EN] Governing rainfall intensity of the swale overflow in l/(s·ha), determined by the tool from the iteration of Eq. 30: the intensity r_D(n_R) of the SMALLEST duration for which V_MÜ > 0. Enters Eq. 31. §6.5.2: if a duration D gives a value greater than zero, an overflow occurs; the shortest overflowing duration has the highest intensity and governs the flow (l/s) (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'r_MUE';
UPDATE fields f SET description = 'Überlaufvolumen der Mulde nach Gl. 30, vom Tool je Dauerstufe berechnet: V_MÜ = [(A_C + A_VA)·r_D(n_R)·10⁻⁷ − A_S,m·k_i]·D·60·f_Z − V_M — Muldenbilanz (Gl. 14) mit der Regenspende der Rigolenhäufigkeit n_R und dem k_i der bewachsenen Bodenzone, abzüglich des Muldenvolumens V_M. Die kleinste Dauerstufe mit V_MÜ > 0 liefert r_MÜ und damit Q_MÜ (Gl. 31). KEIN Speichervolumen — das Systemvolumen ist V_MR (Gl. 26). V_MÜ ≤ 0 für alle D: die Mulde läuft bei n_R nicht über (r_MÜ = Q_MÜ = 0).
[EN] Overflow volume of the swale per Eq. 30, computed by the tool for each duration: V_MÜ = [(A_C + A_VA)·r_D(n_R)·10⁻⁷ − A_S,m·k_i]·D·60·f_Z − V_M — swale balance (Eq. 14) with the intensity of the trench frequency n_R and the k_i of the vegetated soil zone, minus the swale volume V_M. The smallest duration with V_MÜ > 0 gives r_MÜ and thus Q_MÜ (Eq. 31). NOT a storage volume — the system volume is V_MR (Eq. 26). V_MÜ ≤ 0 for all D: the swale does not overflow at n_R (r_MÜ = Q_MÜ = 0).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'V_MUE';
UPDATE fields f SET description = 'Quelle der verwendeten Regenspenden r_D(n) und r_D(n_R), vom Planer als Referenz eingetragen (z. B. KOSTRA-DWD-2020, Rasterfeld). Das Tool dokumentiert damit die Herkunft der Regendaten dieses Blattes. §5.3.3.5: Starkregenauswertungen nach DWA-A 531 oder aktuelle KOSTRA-Datensätze; bei KOSTRA die exakten DWD-Werte verwenden.
[EN] Source of the rainfall intensities r_D(n) and r_D(n_R) used, entered by you as a reference (e.g. KOSTRA-DWD-2020, grid cell). The tool uses it to document the origin of the rainfall data of this sheet. §5.3.3.5: heavy-rain evaluations per DWA-A 531 or current KOSTRA data sets; with KOSTRA use the exact DWD values.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = 'Regenspende für die Bemessungshäufigkeit der Rigole n_R in l/(s·ha), vom Tool je Dauerstufe D aus der Regentabelle entnommen. Sie steuert die Iteration von Gl. 30 (Überlaufvolumen) und, als r_D(n), die Rigolenlänge nach Gl. 32. §6.5.2: in Gl. 30 wird bewusst die seltenere Regenspende der Rigole angesetzt, weil geprüft wird, ob die für n_M (i. d. R. 1/a) bemessene Mulde bei n_R überläuft.
[EN] Rainfall intensity for the design frequency of the trench n_R in l/(s·ha), taken by the tool from the rainfall table for each duration D. It drives the iteration of Eq. 30 (overflow volume) and, as r_D(n), the trench length per Eq. 32. §6.5.2: Eq. 30 deliberately uses the rarer trench intensity, because it tests whether the swale sized for n_M (as a rule 1/a) overflows at n_R.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'r_D_nR';
UPDATE fields f SET description = 'Bemessungshäufigkeit der Rigole im Mulden-Rigolen-System in 1/a, vom Planer nach Tab. 6 und Tab. 8 gewählt. Das Tool wählt damit r_D(n) für Gl. 32 und r_D(n_R) für Gl. 30. §6.6.2: Bemessung analog zum Mulden-Rigolen-Element (§6.5.2: Mulde i. d. R. n = 1/a, Rigole seltener); §5.3.3.4: für n nach Tab. 8 darf kein Überlauf aus dem Gesamtsystem auftreten; bei vernetzten Systemen wird das Nachweisverfahren empfohlen.
[EN] Design frequency of the trench in the swale-trench system in 1/a, chosen by you per Tab. 6 and Tab. 8. The tool uses it to select r_D(n) for Eq. 32 and r_D(n_R) for Eq. 30. §6.6.2: sizing analogous to the swale-trench element (§6.5.2: swale as a rule n = 1/a, trench rarer); §5.3.3.4: for n per Tab. 8 no overflow from the overall system may occur; for networked systems the verification method is recommended.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'n_R_MRS';
UPDATE fields f SET description = 'Zufluss zum Mulden-Rigolen-System in l/s, vom Tool nach Gl. 3 berechnet: Q_zu = r_D(n)·(A_C + A_VA)·10⁻⁴ — Abfluss der Anschlussflächen plus Regen auf die Mulde für die betrachtete Dauerstufe. Dient der Darstellung der Zufluss-/Versickerungs-/Drossel-Bilanz (Grundgleichung Gl. 8: V = (Q_zu − Q_S − Q_Dr)·D·60·f_Z·f_A·10⁻³), aus der Gl. 32 hervorgeht. Keine eigene Grenze in §6.6.
[EN] Inflow to the swale-trench system in l/s, computed by the tool per Eq. 3: Q_zu = r_D(n)·(A_C + A_VA)·10⁻⁴ — runoff of the connected surfaces plus rain on the swale for the duration considered. Used to display the inflow / infiltration / throttle balance (basic Eq. 8: V = (Q_zu − Q_S − Q_Dr)·D·60·f_Z·f_A·10⁻³) from which Eq. 32 derives. No specific limit in §6.6.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'Q_zu_total_MRS';
UPDATE fields f SET description = 'Gesamtspeichervolumen des Systems, serverseitig berechnet: V_MR = V_M (Mulde, A138-17) + V_R (Rigole, A138-18) nach Gl. 26 — Bemessung „analog zu Mulden-Rigolen-Elementen (siehe 6.5.2)“ (§6.6.2); nur die Rigolenlänge nach Gl. 32 berücksichtigt zusätzlich Q_Dr. V_MÜ (Gl. 30) ist dagegen Überlaufvolumen, kein Speichervolumen. Wird in die Zusammenfassung (A138-23) übernommen. §6.6.1: Rigolenvolumen unterhalb der Sohle des Ablaufrohrs im Einfachen Verfahren vernachlässigen.
[EN] Total storage volume of the system, computed by the server: V_MR = V_M (swale, A138-17) + V_R (trench, A138-18) per Eq. 26 — sized “analogously to swale-trench elements (see 6.5.2)” (§6.6.2); only the trench length per Eq. 32 additionally accounts for Q_Dr. V_MÜ (Eq. 30) by contrast is an overflow volume, not storage. Forwarded to the summary (A138-23). §6.6.1: trench volume below the invert of the outlet pipe is neglected in the simple method.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'V_MR';
UPDATE fields f SET description = 'Wasserdurchlässigkeit der bewachsenen Bodenzone, optional. Für die MULDE des Systems ist sie die maßgebliche Bodenschicht (§6.6.2 → §6.5.2); die Rigole versickert mit dem k_i des anstehenden Bodens (A138-11). Erfüllt der Boden 5.2.3.2 und Bild 1, darf k_f,BBZ mit 1·10⁻⁵ bis 5·10⁻⁵ m/s angesetzt werden (Quelle „Bereich nach 5.3.3.6“, f_Methode entfällt); sonst Messwert (f_Methode nach Tab. 11 gilt). Leer = Mulde rechnet mit dem Projekt-k_i. §6.5.1: nach langjährigem Betrieb k_f ≥ 1·10⁻⁵ m/s.
[EN] Permeability of the vegetated soil zone, optional. For the SWALE of the system it is the governing layer (§6.6.2 → §6.5.2); the trench infiltrates with the k_i of the natural soil (A138-11). If the soil meets 5.2.3.2 and Bild 1, k_f,BBZ may be set at 1·10⁻⁵ to 5·10⁻⁵ m/s (source “range per 5.3.3.6”, f_Methode neglected); otherwise a measured value (f_Methode per Tab. 11 applies). Empty = the swale uses the project k_i. §6.5.1: k_f ≥ 1·10⁻⁵ m/s after long-term operation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'k_f_BBZ';
UPDATE fields f SET description = 'Herkunft von k_f,BBZ, vom Planer gewählt: „Bereich nach 5.3.3.6“ (1·10⁻⁵ bis 5·10⁻⁵ m/s) oder „gemessen“. Das Tool bestimmt daraus den Korrekturfaktor für k_i,BBZ: im Bereichsfall nur f_Ort (f_Methode entfällt), im Messfall f_K = f_Ort · f_Methode nach Gl. 6. §5.3.3.6: der Korrekturfaktor für die Bestimmungsmethode f_Methode nach Tab. 11 ist beim Bereichsansatz zu vernachlässigen.
[EN] Source of k_f,BBZ, chosen by you: “range per 5.3.3.6” (1·10⁻⁵ to 5·10⁻⁵ m/s) or “measured”. The tool derives from it the correction factor for k_i,BBZ: in the range case only f_Ort (f_Methode neglected), in the measured case f_K = f_Ort · f_Methode per Eq. 6. §5.3.3.6: the correction factor for the determination method f_Methode per Tab. 11 is to be neglected when the range value is used.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'k_f_BBZ_quelle';
UPDATE fields f SET description = 'Bemessungsrelevante Infiltrationsrate der Mulde: k_i,BBZ = k_f,BBZ · f_Ort (Bereich nach 5.3.3.6) bzw. k_f,BBZ · f_K (gemessen) — Gl. 5/6 auf die bewachsene Bodenzone angewandt; serverseitig berechnet. Wird auf A138-17 als k_i_Mulde übernommen: die Mulde dieses Systems rechnet Gl. 14/16 und den Muldenüberlauf (Gl. 30/31) damit, die Rigole (Gl. 32) mit dem Projekt-k_i des anstehenden Bodens. §6.5.2: maßgebliche Bodenschicht der Mulde ist die bewachsene Bodenzone.
[EN] Design infiltration rate of the swale: k_i,BBZ = k_f,BBZ · f_Ort (range per 5.3.3.6) or k_f,BBZ · f_K (measured) — Eq. 5/6 applied to the vegetated soil zone; computed by the server. Forwarded to A138-17 as k_i_Mulde: the swale of this system uses it in Eq. 14/16 and the swale overflow (Eq. 30/31), the trench (Eq. 32) uses the project k_i of the natural soil. §6.5.2: the governing soil layer of the swale is the vegetated soil zone.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND f.symbol = 'k_i_BBZ';
UPDATE equations e SET description = 'Gesamtspeichervolumen des Systems: V_MR = V_M + V_R — Gl. 26 auf das Mulden-Rigolen-System angewandt (§6.6.2: Bemessung analog 6.5.2). Anzeige-Gleichung; der Server schreibt V_MR aus V_M (A138-17) und V_R (A138-18) und übergibt es an die Zusammenfassung A138-23. Nicht mit V_MÜ (Gl. 30, Überlaufvolumen) verwechseln.
[EN] Total storage volume of the system: V_MR = V_M + V_R — Eq. 26 applied to the swale-trench system (§6.6.2: sizing analogous to 6.5.2). Display equation; the server writes V_MR from V_M (A138-17) and V_R (A138-18) and passes it to the summary A138-23. Do not confuse with V_MÜ (Eq. 30, overflow volume).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND e.equation_number = '26';
UPDATE equations e SET description = 'Überlaufvolumen der Mulde: V_MÜ = [(A_C + A_VA)·r_D(n_R)·10⁻⁷ − A_S,m·k_i]·D·60·f_Z − V_M — Muldenbilanz mit der Regenspende der Rigolenhäufigkeit n_R, Versickerung über A_S,m der Mulde mit k_i der bewachsenen Bodenzone, abzüglich des für n_M bemessenen Muldenvolumens V_M. Das Tool iteriert über D; die kleinste Dauerstufe mit V_MÜ > 0 liefert r_MÜ für Gl. 31. §6.5.2: V_MÜ > 0 bedeutet Überlauf; kein positiver Wert → kein Überlauf bei n_R. Für das System analog §6.6.2.
[EN] Overflow volume of the swale: V_MÜ = [(A_C + A_VA)·r_D(n_R)·10⁻⁷ − A_S,m·k_i]·D·60·f_Z − V_M — swale balance with the intensity of the trench frequency n_R, infiltration through the swale''s A_S,m with k_i of the vegetated soil zone, minus the swale volume V_M sized for n_M. The tool iterates over D; the smallest duration with V_MÜ > 0 gives r_MÜ for Eq. 31. §6.5.2: V_MÜ > 0 means overflow; no positive value → no overflow at n_R. For the system analogously §6.6.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND e.equation_number = '30';
UPDATE equations e SET description = 'Bemessungsabfluss des Muldenüberlaufs: Q_MÜ = A_C·10⁻⁴·r_MÜ − A_VA·k_i·1000 in l/s — Abfluss der Anschlussflächen bei der maßgeblichen Regenspende r_MÜ (aus Gl. 30) minus Versickerung auf der überregneten Muldenfläche A_VA (m³/s → l/s). Das Tool berechnet damit die hydraulische Mindestleistung der Überlaufbauwerke. §6.5.2: Gl. 31 setzt anders als Gl. 30 nur A_C als Zufluss und A_VA als Versickerungsfläche an — so anwenden wie gedruckt, nicht „korrigieren“ (Studienbuch).
[EN] Design discharge of the swale overflow: Q_MÜ = A_C·10⁻⁴·r_MÜ − A_VA·k_i·1000 in l/s — runoff of the connected surfaces at the governing intensity r_MÜ (from Eq. 30) minus infiltration on the rained-on swale area A_VA (m³/s → l/s). The tool uses it for the minimum hydraulic capacity of the overflow structures. §6.5.2: unlike Eq. 30, Eq. 31 takes only A_C as inflow and A_VA as infiltrating area — apply as printed, do not “correct” it (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND e.equation_number = '31';
UPDATE equations e SET description = 'Rigolenlänge des Systems: Gl. 29 um den Drosselabfluss ergänzt — L_R = [(A_C + A_VA)·10⁻⁷·r_D(n) − b_R·h_R·k_i − V_M/(D·60·f_Z) − Q_Dr·10⁻³] / [b_R·h_R·s_R/(D·60·f_Z) + (b_R + h_R)·k_i]. Zähler: Zufluss minus Stirnflächen-Versickerung minus Muldenvolumen-Anteil minus Drossel; Nenner: Speicher- und Versickerungsleistung je Meter Rigole (k_i des anstehenden Bodens). §6.6.2: Iteration über die Dauerstufen D (der Text nennt „Gl. 33“, gemeint ist Gl. 32); das Maximum ist L_R.
[EN] Trench length of the system: Eq. 29 extended by the throttled outflow — L_R = [(A_C + A_VA)·10⁻⁷·r_D(n) − b_R·h_R·k_i − V_M/(D·60·f_Z) − Q_Dr·10⁻³] / [b_R·h_R·s_R/(D·60·f_Z) + (b_R + h_R)·k_i]. Numerator: inflow minus end-face infiltration minus swale-volume share minus throttle; denominator: storage and infiltration capacity per metre of trench (k_i of the natural soil). §6.6.2: iterate over the durations D (the text says “Eq. 33”, Eq. 32 is meant); the maximum is L_R.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND e.equation_number = '32';
UPDATE equations e SET description = 'Mittlerer Drosselabfluss: Q_Dr = (Q_Dr,min + Q_Dr,max)/2 in l/s — arithmetisches Mittel aus minimalem und maximalem Abfluss der gewählten Drosseleinrichtung (Herstellerangaben). Das Tool setzt Q_Dr in Gl. 32 und in q_S,AC (Gl. 9) ein. §6.6.2: im Einfachen Verfahren kann mit hinreichender Genauigkeit ein konstanter, mittlerer Drosselabfluss zugrunde gelegt werden; die maximale Drosselleistung ist mit Wasserbehörde oder Kanalnetzbetreiber abzustimmen.
[EN] Mean throttled outflow: Q_Dr = (Q_Dr,min + Q_Dr,max)/2 in l/s — arithmetic mean of the minimum and maximum outflow of the chosen throttle device (manufacturer''s data). The tool inserts Q_Dr into Eq. 32 and into q_S,AC (Eq. 9). §6.6.2: in the simple method a constant mean throttled outflow may be used with sufficient accuracy; the maximum throttle capacity must be agreed with the water authority or sewer operator.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND e.equation_number = '33';
UPDATE equations e SET description = 'Anzeige-Gleichung für die Infiltrationsrate der Mulde: k_i_BBZ = k_f_BBZ · f_Ort (Quelle „Bereich nach 5.3.3.6“) bzw. k_f_BBZ · f_K (Quelle „gemessen“) — Gl. 5/6 auf die bewachsene Bodenzone angewandt. Der Server schreibt k_i_BBZ und übergibt es als k_i_Mulde an A138-17 (Gl. 14/16, 30/31). §5.3.3.6: beim Bereichsansatz 1·10⁻⁵ bis 5·10⁻⁵ m/s ist f_Methode nach Tab. 11 zu vernachlässigen, f_Ort bleibt (Tab. 10: 0,3–1,0).
[EN] Display equation for the swale infiltration rate: k_i_BBZ = k_f_BBZ · f_Ort (source “range per 5.3.3.6”) or k_f_BBZ · f_K (source “measured”) — Eq. 5/6 applied to the vegetated soil zone. The server writes k_i_BBZ and passes it to A138-17 as k_i_Mulde (Eq. 14/16, 30/31). §5.3.3.6: with the range value 1·10⁻⁵ to 5·10⁻⁵ m/s, f_Methode per Tab. 11 is neglected, f_Ort remains (Tab. 10: 0.3–1.0).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-20' AND e.equation_number = 'A138-20-D1';
UPDATE fields f SET description = 'Querschnittsfläche der Filterschicht beim Schacht Typ B, vom Tool aus dem Innendurchmesser berechnet: A_S,FS = π·d_i²/4 (§6.7.2: „die Querschnittsfläche mit dem Durchmesser d_i“). Geht in den Filterschicht-Nachweis A_S,FS·k_f,FS ≥ A_S,Schacht·k_i (Gl. 38, Gate A138-REQ-33) ein; bei anstehendem Boden mit k_f > 1·10⁻³ m/s ist sie die allein versickerungswirksame Fläche (Gl. 40). Nur bei Typ B relevant.
[EN] Cross-sectional area of the filter layer for shaft type B, computed by the tool from the inner diameter: A_S,FS = π·d_i²/4 (§6.7.2: “the cross-sectional area with diameter d_i”). Enters the filter check A_S,FS·k_f,FS ≥ A_S,Schacht·k_i (Eq. 38, gate A138-REQ-33); where the natural soil has k_f > 1·10⁻³ m/s it is the only effective infiltration area (Eq. 40). Relevant for type B only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'A_S_FS';
UPDATE fields f SET description = 'Versickerungsfläche des Schachts, vom Tool nach Gl. 34 berechnet: A_S = π·d_a²/4 + π·d_a·h_S/2 — Sohlfläche plus Mantelfläche bis zum mittleren Wasserstand h_S/2, beide mit dem AUSSENdurchmesser, weil das Wasser an der Außenseite der Ringe in den Boden tritt. Geht in V_S (Gl. 35), h_S (Gl. 37) und den Filternachweis Gl. 38 ein. §6.7.2: A_S wird als konstant angenommen, näherungsweise Mantel- und Sohlenfläche; gilt für Typ A und B gleich.
[EN] Infiltration area of the shaft, computed by the tool per Eq. 34: A_S = π·d_a²/4 + π·d_a·h_S/2 — base area plus wall area up to the mean water level h_S/2, both with the OUTER diameter, because water enters the soil at the outside of the rings. Enters V_S (Eq. 35), h_S (Eq. 37) and the filter check Eq. 38. §6.7.2: A_S is assumed constant, approximately wall plus base area; the same for type A and B.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'A_S_Schacht';
UPDATE fields f SET description = 'Erforderlicher Bemessungseinstau im Schacht, vom Tool nach Gl. 37 berechnet (Typ A und B; bei Typ B mit anstehendem k_f > 1·10⁻³ m/s nach Gl. 40): Iteration über die Dauerstufen D mit zugehörigem r_D(n), das Maximum ist maßgebend. Geht in A_S (Gl. 34), V_S (Gl. 36) und erf. k_f,FS (Gl. 39) ein; die ausgeführte Einstauhöhe muss ≥ h_S sein. §6.7.1: Schachtsohle (Typ A) bzw. Unterkante Filterschicht (Typ B) muss den Abstand a zum MHGW nach 5.2.1 einhalten.
[EN] Required design ponding depth in the shaft, computed by the tool per Eq. 37 (types A and B; for type B with natural k_f > 1·10⁻³ m/s per Eq. 40): iterative application for different durations D with their r_D(n), the maximum governs. Enters A_S (Eq. 34), V_S (Eq. 36) and req. k_f,FS (Eq. 39); the built ponding height (inflow invert to shaft base / top of filter) must be ≥ h_S. §6.7.1: the shaft base (type A) or bottom of the filter layer (type B) must keep the distance a to the MHGW per 5.2.1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'h_S';
UPDATE fields f SET description = 'Durchlässigkeitsbeiwert der Filterschicht (Schacht Typ B) in m/s, aus Produktdaten/Laborprüfung des Filtersands — ohne Korrekturfaktor f_K (§6.7.2 verwendet k_f,FS direkt). Das Tool prüft damit Gl. 38 (A138-REQ-33) und rechnet bei anstehendem Boden mit k_f > 1·10⁻³ m/s h_S nach Gl. 40. Fenster: ≥ erf. k_f,FS nach Gl. 39 UND ≤ 1·10⁻³ m/s (§6.7.1/§6.7.2: zum Schutz des Grundwassers darf die Filterschicht 1·10⁻³ m/s nicht überschreiten).
[EN] Permeability coefficient of the filter layer (shaft type B) in m/s, from product data / laboratory test of the filter sand — without correction factor f_K (§6.7.2 uses k_f,FS directly). The tool checks Eq. 38 (A138-REQ-33) with it and, where the natural soil has k_f > 1·10⁻³ m/s, computes h_S per Eq. 40. Window: ≥ req. k_f,FS per Eq. 39 AND ≤ 1·10⁻³ m/s (§6.7.1/§6.7.2: to protect groundwater the filter layer must not exceed 1·10⁻³ m/s).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'k_f_FS';
UPDATE fields f SET description = 'Prüfergebnis des Tools: Schacht-Innendurchmesser d_i ≥ 1,0 m (DN 1000)? §6.7.1: „Ein Mindestdurchmesser von DN 1000 darf nicht unterschritten werden“ — harte Vorgabe, gilt für Typ A und B. Fällt die Prüfung durch, Schachtdurchmesser vergrößern; ein größerer Durchmesser erweitert zugleich bei Typ B das zulässige Fenster für k_f,FS (Gl. 39).
[EN] Check result of the tool: shaft inner diameter d_i ≥ 1.0 m (DN 1000)? §6.7.1: “A minimum diameter of DN 1000 must not be undercut” — a hard rule, for types A and B. If the check fails, enlarge the shaft diameter; for type B a larger diameter also widens the permissible window for k_f,FS (Eq. 39).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'schacht_d_i_check';
UPDATE fields f SET description = 'Mächtigkeit der Filterschicht im Sohlenbereich des Schachts Typ B in cm, vom Planer gewählt. Das Tool prüft sie gegen das Minimum (schacht_filter_thickness_check) und braucht sie für die Höhenlage: der Abstand a zum MHGW wird bei Typ B ab Unterkante Filterschicht gemessen (§6.7.1). §6.7.1: Filterschicht ≥ 50 cm aus carbonathaltigem Sand 0–4 mm oder geeigneten Substraten, k_f ≤ 1·10⁻³ m/s, möglichst wenig Schlämmkorn und Feinsand (Kolmation).
[EN] Thickness of the filter layer in the base area of shaft type B in cm, chosen by you. The tool checks it against the minimum (schacht_filter_thickness_check) and needs it for the levels: for type B the distance a to the MHGW is measured from the bottom edge of the filter layer (§6.7.1). §6.7.1: filter layer ≥ 50 cm of carbonate-containing sand 0–4 mm or suitable substrates, k_f ≤ 1·10⁻³ m/s, as little silt/clay and fine sand as possible (clogging).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'schacht_filter_thickness';
UPDATE fields f SET description = 'Prüfergebnis des Tools: Filterschicht des Schachts Typ B ≥ 50 cm? §6.7.1: als Material für diese Filterschicht (≥ 50 cm) ist carbonathaltiger Sand mit Körnung > 0 bis 4 mm oder ein geeignetes Substrat zu verwenden. Nur bei shaft_type = Typ B relevant; die Entleerung erfolgt bei Typ B vollständig über die Durchsickerung der Filterschicht.
[EN] Check result of the tool: filter layer of shaft type B ≥ 50 cm? §6.7.1: the material of this filter layer (≥ 50 cm) shall be carbonate-containing sand with a grain size of > 0 to 4 mm or a suitable substrate. Relevant only for shaft_type = type B; for type B the storage empties entirely by seepage through the filter layer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'schacht_filter_thickness_check';
UPDATE fields f SET description = 'Bauart des Versickerungsschachts, vom Planer gewählt: Typ A — Schachtringe mit seitlichen Durchtrittsöffnungen oder wasserdurchlässig, keine zusätzliche Reinigungswirkung; Typ B — Öffnungen nur unterhalb einer Filterschicht (≥ 50 cm) im Sohlenbereich, zusätzliche Reinigung. Das Tool schaltet damit die Typ-B-Prüfungen frei (Filterschicht-Mächtigkeit, Gl. 38/39 als Gate A138-REQ-33, ggf. Gl. 40). §6.7.1: bei beiden Typen Behandlungsanlage im Zulauf nach Tab. 7; Bemessung nach gleichen Grundsätzen (§6.7.2).
[EN] Construction type of the infiltration shaft, chosen by you: type A — shaft rings with lateral openings or permeable, no additional cleaning; type B — openings only below a filter layer (≥ 50 cm) in the base area, additional cleaning. The tool uses it to enable the type-B checks (filter thickness, Eq. 38/39 as gate A138-REQ-33, Eq. 40 where applicable). §6.7.1: both types need a treatment unit in the inflow per Tab. 7; sizing follows the same principles (§6.7.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'shaft_type';
UPDATE fields f SET description = 'Speichervolumen des Schachts. Das Tool berechnet das ERFORDERLICHE Volumen nach Gl. 35 (V_S = (A_C·10⁻⁷·r_D(n) − A_S·k_i)·D·60·f_Z, Maximum über D; kein A_VA, der Schacht ist überdeckt) und das VORHANDENE Volumen nach Gl. 36 (V_S = π·d_i²/4·h_S, Innendurchmesser). Beide stimmen für den Bemessungseinstau h_S nach Gl. 37 überein — ein Selbsttest der Rechnung (Studienbuch). §6.7.2: A_S nach Gl. 34, k_i nach Gl. 5.
[EN] Storage volume of the shaft. The tool computes the REQUIRED volume per Eq. 35 (V_S = (A_C·10⁻⁷·r_D(n) − A_S·k_i)·D·60·f_Z, maximum over D; no A_VA, the shaft is covered) and the AVAILABLE volume per Eq. 36 (V_S = π·d_i²/4·h_S, inner diameter). Both coincide for the design depth h_S per Eq. 37 — a self-check of the calculation (study book). §6.7.2: A_S per Eq. 34, k_i per Eq. 5.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'V_S';
UPDATE fields f SET description = 'Quelle der verwendeten Regenspenden r_D(n), vom Planer als Referenz eingetragen (z. B. KOSTRA-DWD-2020, Rasterfeld). Das Tool dokumentiert damit die Herkunft der Regendaten dieses Blattes. §5.3.3.5: Starkregenauswertungen nach DWA-A 531 oder aktuelle KOSTRA-Datensätze; bei KOSTRA die exakten DWD-Werte verwenden. Bei Schächten in durchlässigem Boden sind die kurzen Dauerstufen maßgebend (Studienbuch).
[EN] Source of the rainfall intensities r_D(n) used, entered by you as a reference (e.g. KOSTRA-DWD-2020, grid cell). The tool uses it to document the origin of the rainfall data of this sheet. §5.3.3.5: heavy-rain evaluations per DWA-A 531 or current KOSTRA data sets; with KOSTRA use the exact DWD values. For shafts in permeable soil the short durations govern (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = 'Innendurchmesser des Schachts in m (Herstellerangabe). Das Tool rechnet damit das vorhandene Volumen V_S = π·d_i²/4·h_S (Gl. 36), den Speicherterm in Gl. 37, die Filterschicht-Fläche A_S,FS = π·d_i²/4 (Gl. 38–40) und prüft DN 1000 (schacht_d_i_check). §6.7.1: Mindestdurchmesser DN 1000 darf nicht unterschritten werden; Durchmesser in den Gleichungen in m, nicht in mm (Tab. 2, Studienbuch).
[EN] Inner diameter of the shaft in m (manufacturer''s data). The tool uses it for the available volume V_S = π·d_i²/4·h_S (Eq. 36), the storage term in Eq. 37, the filter-layer area A_S,FS = π·d_i²/4 (Eq. 38–40) and the DN 1000 check (schacht_d_i_check). §6.7.1: minimum diameter DN 1000 must not be undercut; diameters in the equations in m, not mm (Tab. 2, study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'd_S_innen';
UPDATE fields f SET description = 'Außendurchmesser des Schachts in m (Herstellerangabe, inkl. Ringwand). Das Tool rechnet damit die Versickerungsfläche A_S = π·d_a²/4 + π·d_a·h_S/2 (Gl. 34), den Versickerungsterm in Gl. 37 und erf. k_f,FS nach Gl. 39. §6.7.2: die Versickerung wird mit dem Außendurchmesser angesetzt (Wasser tritt an der Außenseite der Ringe in den Boden), das Speichervolumen mit dem Innendurchmesser (Gl. 36).
[EN] Outer diameter of the shaft in m (manufacturer''s data, incl. ring wall). The tool uses it for the infiltration area A_S = π·d_a²/4 + π·d_a·h_S/2 (Eq. 34), the infiltration term in Eq. 37 and req. k_f,FS per Eq. 39. §6.7.2: infiltration is calculated with the outer diameter (water enters the soil at the outside of the rings), storage with the inner diameter (Eq. 36).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'd_S_aussen';
UPDATE fields f SET description = 'Regenspende r_D(n) in l/(s·ha) der maßgebenden Dauerstufe für die gewählte Bemessungshäufigkeit n, vom Tool bei der Iteration von Gl. 37 (bzw. Gl. 40) aus der Regentabelle ermittelt — die Dauerstufe mit dem größten h_S ist maßgebend. §6.7.2: iterative Anwendung für unterschiedliche Dauerstufen D und jeweils zugehöriger Regenspende r_D(n); in durchlässigen Böden liegt das Maximum bei kurzen Dauerstufen (Studienbuch).
[EN] Rainfall intensity r_D(n) in l/(s·ha) of the governing duration for the chosen design frequency n, determined by the tool during the iteration of Eq. 37 (or Eq. 40) from the rainfall table — the duration with the largest h_S governs. §6.7.2: iterative application for different durations D with their rainfall intensity r_D(n); in permeable soils the maximum lies at short durations (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'r_D_n_S';
UPDATE fields f SET description = 'Bemessungs-Infiltrationsrate der Filterschicht in m/s, optional. Tab. 2 der Richtlinie definiert das Symbol k_i,FS, §6.7.2 rechnet in Gl. 38–40 jedoch direkt mit dem Durchlässigkeitsbeiwert k_f,FS ohne Korrekturfaktor (Studienbuch). Das Tool nutzt das Feld nur als Alternative/Ergänzung zu k_f_FS für Gl. 40; maßgeblich für die Prüfungen ist k_f_FS. Grenze §6.7.2: Filterschicht ≤ 1·10⁻³ m/s.
[EN] Design infiltration rate of the filter layer in m/s, optional. Tab. 2 of the guideline defines the symbol k_i,FS, but §6.7.2 uses the permeability coefficient k_f,FS directly in Eq. 38–40 without a correction factor (study book). The tool uses the field only as an alternative/supplement to k_f_FS for Eq. 40; k_f_FS governs the checks. Limit §6.7.2: filter layer ≤ 1·10⁻³ m/s.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND f.symbol = 'k_i_FS';
UPDATE equations e SET description = 'Versickerungsfläche des runden Schachts: A_S = π·d_a²/4 + π·d_a·h_S/2 — Sohlfläche plus Mantelfläche bis zum mittleren Wasserstand h_S/2, mit dem Außendurchmesser. Das Tool rechnet A_S für Gl. 35 und den Filternachweis Gl. 38 (A_S,Schacht). §6.7.2: Annahmen des Einfachen Verfahrens — A_S konstant, homogener Untergrund, über die gesamte Zeit der mittlere Wasserstand h_S/2; gilt für Typ A und Typ B.
[EN] Infiltration area of the round shaft: A_S = π·d_a²/4 + π·d_a·h_S/2 — base area plus wall area up to the mean water level h_S/2, with the outer diameter. The tool computes A_S for Eq. 35 and the filter check Eq. 38 (A_S,Schacht). §6.7.2: assumptions of the simple method — A_S constant, homogeneous subsoil, mean water level h_S/2 during the whole time; for type A and type B.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND e.equation_number = '34';
UPDATE equations e SET description = 'Erforderliches Schachtvolumen aus der Speichergleichung Gl. 8: V_S = (A_C·10⁻⁷·r_D(n) − A_S·k_i)·D·60·f_Z — Zufluss nur aus A_C (kein A_VA, Schacht überdeckt) minus Versickerung über A_S nach Gl. 34 mit k_i nach Gl. 5. Das Tool iteriert über D und vergleicht mit dem vorhandenen Volumen nach Gl. 36; beide zusammen ergeben die Bemessungsgleichung Gl. 37 (§6.7.2).
[EN] Required shaft volume from the storage equation Eq. 8: V_S = (A_C·10⁻⁷·r_D(n) − A_S·k_i)·D·60·f_Z — inflow only from A_C (no A_VA, shaft covered) minus infiltration through A_S per Eq. 34 with k_i per Eq. 5. The tool iterates over D and compares with the available volume per Eq. 36; together they yield the sizing equation Eq. 37 (§6.7.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND e.equation_number = '35';
UPDATE equations e SET description = 'Vorhandenes Speichervolumen des runden Schachts: V_S = π·d_i²/4 · h_S — Innenquerschnitt mal maximale Bemessungseinstauhöhe. Das Tool rechnet damit das verfügbare Volumen der gewählten Schachtabmessung; mit Gl. 34 in Gl. 35 eingesetzt folgt daraus Gl. 37. §6.7.2: hier der INNENdurchmesser (Wasser steht im Ring), in Gl. 34 der Außendurchmesser.
[EN] Available storage volume of the round shaft: V_S = π·d_i²/4 · h_S — inner cross-section times maximum design ponding depth. The tool uses it for the available volume of the chosen shaft dimension; inserted with Eq. 34 into Eq. 35 it yields Eq. 37. §6.7.2: here the INNER diameter (water stands inside the ring), in Eq. 34 the outer diameter.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND e.equation_number = '36';
UPDATE equations e SET description = 'Bemessungsgleichung des Schachts für den Bemessungseinstau: h_S = (A_C·10⁻⁷·r_D(n) − π·d_a²/4·k_i) / (π·d_i²/(4·D·60·f_Z) + d_a·π·k_i/2) — Gl. 34 und 36 in Gl. 35 eingesetzt; Zähler: Zufluss minus Versickerung der Sohle, Nenner: Speicher- und Wandversickerungsleistung je Meter Einstau. Das Tool iteriert über die Dauerstufen D mit zugehörigem r_D(n); das Maximum ist h_S (§6.7.2 — der Text nennt „Gl. 38“, gemeint ist Gl. 37). Negativer Zähler: die Sohle allein schluckt den Zufluss dieser Dauerstufe.
[EN] Sizing equation of the shaft for the design ponding depth: h_S = (A_C·10⁻⁷·r_D(n) − π·d_a²/4·k_i) / (π·d_i²/(4·D·60·f_Z) + d_a·π·k_i/2) — Eq. 34 and 36 inserted into Eq. 35; numerator: inflow minus base infiltration, denominator: storage and wall-infiltration capacity per metre of depth. The tool iterates over the durations D with their r_D(n); the maximum is h_S (§6.7.2 — the text says “Eq. 38”, Eq. 37 is meant). Negative numerator: the base alone takes the inflow of that duration.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND e.equation_number = '37';
UPDATE equations e SET description = 'Filterschicht-Nachweis für Schacht Typ B: A_S,FS · k_f,FS ≥ A_S,Schacht · k_i — die Filterschicht (Querschnitt mit d_i) muss mindestens so viel Wasser durchlassen, wie die Bemessung dem Boden über A_S nach Gl. 34 zuschreibt (Engpass-Prinzip). Das Tool prüft die Bedingung bei shaft_type = Typ B als Gate A138-REQ-33 (blockierend). §6.7.2: „Für den Schacht Typ B ist nachzuweisen, dass die bei der Bemessung berücksichtigte Versickerungsleistung nicht durch die Filterschicht eingeschränkt wird.“
[EN] Filter-layer check for shaft type B: A_S,FS · k_f,FS ≥ A_S,Schacht · k_i — the filter layer (cross-section with d_i) must pass at least as much water as the sizing assigns to the soil through A_S per Eq. 34 (bottleneck principle). The tool checks the condition for shaft_type = type B as gate A138-REQ-33 (blocking). §6.7.2: “For shaft type B it must be proven that the infiltration capacity considered in the sizing is not limited by the filter layer.”' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND e.equation_number = '38';
UPDATE equations e SET description = 'Erforderliche Durchlässigkeit der Filterschicht, Gl. 38 umgestellt: erf. k_f,FS ≥ (d_a² + 2·h_S·d_a)/d_i² · k_i. Das Tool berechnet den Mindestwert, den der gewählte Filtersand erreichen muss (k_f_FS ≥ erf. k_f,FS). §6.7.2: zum Schutz des Grundwassers darf erf. k_f,FS 1·10⁻³ m/s nicht überschreiten — liegt der Wert darüber, gibt es keinen zulässigen Filtersand; dann Innendurchmesser vergrößern (mehr Filterfläche) oder Belastung reduzieren (Studienbuch).
[EN] Required permeability of the filter layer, Eq. 38 rearranged: req. k_f,FS ≥ (d_a² + 2·h_S·d_a)/d_i² · k_i. The tool computes the minimum value the chosen filter sand must reach (k_f_FS ≥ req. k_f,FS). §6.7.2: to protect groundwater, req. k_f,FS must not exceed 1·10⁻³ m/s — if the value is above, no permissible filter sand exists; then enlarge the inner diameter (more filter area) or reduce the load (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND e.equation_number = '39';
UPDATE equations e SET description = 'Bemessungseinstau bei maßgeblicher Filterschicht (Typ B, anstehender Boden mit k_f > 1·10⁻³ m/s): h_S = (A_C·10⁻⁷·r_D(n) − π·d_i²/4·k_f,FS) · 4·D·60·f_Z/(d_i²·π) — versickerungswirksam ist nur A_S,FS = π·d_i²/4 mit k_f,FS, kein Wandterm. Das Tool wendet Gl. 40 statt Gl. 37 an, wenn der anstehende Boden durchlässiger als die Filterschicht ist, und iteriert über D. §6.7.2: „wird die Filterschicht für die Bemessung maßgeblich“; k_f,FS ≤ 1·10⁻³ m/s.
[EN] Design ponding depth when the filter layer governs (type B, natural soil with k_f > 1·10⁻³ m/s): h_S = (A_C·10⁻⁷·r_D(n) − π·d_i²/4·k_f,FS) · 4·D·60·f_Z/(d_i²·π) — only A_S,FS = π·d_i²/4 with k_f,FS infiltrates, no wall term. The tool applies Eq. 40 instead of Eq. 37 when the natural soil is more permeable than the filter layer, iterating over D. §6.7.2: “the filter layer becomes decisive for the sizing”; k_f,FS ≤ 1·10⁻³ m/s.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-21' AND e.equation_number = '40';
UPDATE fields f SET description = 'Prüfergebnis des Tools: Einstauhöhe des Beckens h_B ≥ 0,5 m? §6.8.1 / Tab. 14: Versickerungsbecken haben in der Regel Einstauhöhen von h ≥ 0,5 m (kompakter Speicher bei hoher hydraulischer Belastung). Hinweis-Prüfung („in der Regel“), keine harte Grenze; eine flachere Anlage ist eher eine Mulde nach 6.3.
[EN] Check result of the tool: basin ponding depth h_B ≥ 0.5 m? §6.8.1 / Tab. 14: infiltration basins as a rule have ponding depths of h ≥ 0.5 m (compact storage under high hydraulic load). An advisory check (“as a rule”), not a hard limit; a shallower facility is rather a swale per 6.3.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'basin_h_check';
UPDATE fields f SET description = 'Prüfergebnis des Tools: Infiltrationsrate des Beckens k_i ≥ 1·10⁻⁵ m/s? §6.8.1: bei Becken ist A_C/A_S,m in der Regel größer als 15; diese hohe hydraulische Belastung erfordert für die rasche Entleerung eine gesicherte Durchlässigkeit — i. d. R. k_i ≥ 1·10⁻⁵ m/s (Tab. 14: k_f der maßgeblichen Bodenschicht ≥ 1·10⁻⁵ m/s, zehnfach gegenüber dezentralen Anlagen). Die bewachsene Bodenzone ist zu berücksichtigen (§6.8.2); abweichende Werte für den langjährigen Betrieb nachweisen (Tab. 14 Anm. 1).
[EN] Check result of the tool: design infiltration rate of the basin k_i ≥ 1·10⁻⁵ m/s? §6.8.1: for basins A_C/A_S,m is as a rule greater than 15; this high hydraulic load requires an assured permeability for rapid emptying — as a rule k_i ≥ 1·10⁻⁵ m/s (Tab. 14: k_f of the governing soil layer ≥ 1·10⁻⁵ m/s, ten times the decentralised value). The vegetated soil zone must be considered in k_i (§6.8.2); deviating values must be proven for long-term operation (Tab. 14 note 1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'basin_ki_min_check';
UPDATE fields f SET description = 'Einstauhöhe des Versickerungsbeckens, vom Planer gewählt. Das Tool bildet daraus mit der Sohlgeometrie und der Böschung die Fläche bei Volleinstau A_S,max und A_S,m (Gl. 7), das vorhandene Volumen und prüft basin_h_check. §6.8.1 / Tab. 14: in der Regel h ≥ 0,5 m; Freibord zum Überlauf ≥ 35 cm (Tab. 14); bei h > 40 cm inkl. Freibord ist die Zugänglichkeit im Wohnumfeld zu beschränken (§5.3.5, Bild 16 „ggf. Einfriedung“).
[EN] Ponding depth of the infiltration basin, chosen by you. From it, the base geometry and the slope the tool forms the area at full impoundment A_S,max and A_S,m (Eq. 7), the available volume, and runs basin_h_check. §6.8.1 / Tab. 14: as a rule h ≥ 0.5 m; freeboard to the overflow ≥ 35 cm (Tab. 14); with h > 40 cm incl. freeboard, access must be restricted in residential surroundings (§5.3.5, Bild 16 “fence if required”).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'h_B';
UPDATE fields f SET description = 'Prüfergebnis des Tools: Wassertiefe inkl. Freibord ≤ 40 cm im Wohnumfeld? §5.3.5: bei oberirdischen Versickerungsanlagen im Wohnumfeld muss die Zugänglichkeit auf Bereiche beschränkt werden, in denen keine großen Strömungen auftreten und die Wassertiefe in Anlehnung an DIN 18034-1:2020 maximal 40 cm inklusive Freibord beträgt. Da Becken i. d. R. h ≥ 0,5 m haben, fällt die Prüfung meist durch → Zugang beschränken (Einfriedung), nicht die Tiefe verringern.
[EN] Check result of the tool: water depth incl. freeboard ≤ 40 cm in residential surroundings? §5.3.5: for above-ground infiltration facilities in residential surroundings, accessibility must be restricted to areas where no strong currents occur and the water depth, following DIN 18034-1:2020, is at most 40 cm including freeboard. Since basins as a rule have h ≥ 0.5 m, the check usually fails → restrict access (fence), do not reduce the depth.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'residential_depth_check';
UPDATE fields f SET description = 'Erforderliches Speichervolumen des Beckens, vom Tool nach Gl. 41 berechnet: V_VA = [(A_C + A_VA)·10⁻⁷·r_D(n) − A_S,m·k_i − Q_Dr·10⁻³]·D·60·f_Z·f_A — Gl. 14 ergänzt um Drosselabfluss und Abminderungsfaktor; Maximum über die Dauerstufen D. Das vorhandene Volumen folgt aus der Beckengeometrie (Sohle, Böschung, h_B) und muss ≥ V_VA sein. §6.8.2: ohne Ableitung Q_Dr = 0; f_A nach DWA-A 117, i. d. R. ≅ 1 (§5.3.3.7); bei hohem Schadpotenzial Nachweisverfahren empfohlen.
[EN] Required storage volume of the basin, computed by the tool per Eq. 41: V_VA = [(A_C + A_VA)·10⁻⁷·r_D(n) − A_S,m·k_i − Q_Dr·10⁻³]·D·60·f_Z·f_A — Eq. 14 extended by throttle and reduction factor; maximum over the durations D. The available volume follows from the basin geometry (base, slope, h_B) and must be ≥ V_VA. §6.8.2: without a discharge Q_Dr = 0; f_A per DWA-A 117, as a rule ≅ 1 (§5.3.3.7); with high damage potential the verification method is recommended.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'V_B';
UPDATE fields f SET description = 'Quelle der verwendeten Regenspenden r_D(n), vom Planer als Referenz eingetragen (z. B. KOSTRA-DWD-2020, Rasterfeld). Das Tool dokumentiert damit die Herkunft der Regendaten dieses Blattes. §5.3.3.5: Starkregenauswertungen nach DWA-A 531 oder aktuelle KOSTRA-Datensätze; bei KOSTRA die exakten DWD-Werte verwenden. Bei Becken mit hohem A_C/A_S,m liegt die maßgebende Dauerstufe bei langen Regen (Studienbuch).
[EN] Source of the rainfall intensities r_D(n) used, entered by you as a reference (e.g. KOSTRA-DWD-2020, grid cell). The tool uses it to document the origin of the rainfall data of this sheet. §5.3.3.5: heavy-rain evaluations per DWA-A 531 or current KOSTRA data sets; with KOSTRA use the exact DWD values. For basins with high A_C/A_S,m the governing duration lies at long rains (study book).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'rainfall_table_ref';
UPDATE fields f SET description = 'Überregnete Fläche des Beckens (Regen, der direkt in das Becken fällt), vom Planer aus der Geometrie bestimmt (z. B. Wasserspiegelfläche A_S,max) oder näherungsweise A_VA = A_S,m (analog §6.3.2). Das Tool addiert sie in Gl. 41 zu A_C mit Abflussbeiwert 1. Gl. 41 nennt sie „überregnete Fläche einer oberirdischen Versickerungsanlage / des Versickerungsbeckens“.
[EN] Rained-on area of the basin (rain falling directly into the basin), determined by you from the geometry (e.g. water-surface area A_S,max) or set approximately as A_VA = A_S,m (analogous to §6.3.2). The tool adds it to A_C in Eq. 41 with runoff coefficient 1. Eq. 41 lists it as “rained-on area of an above-ground infiltration facility / of the infiltration basin”.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'A_VA_Becken';
UPDATE fields f SET description = 'Regenspende r_D(n) in l/(s·ha) der maßgebenden Dauerstufe für die Bemessungshäufigkeit n_B, vom Tool bei der Iteration von Gl. 41 aus der Regentabelle ermittelt — die Dauerstufe mit dem größten V_VA ist maßgebend. §6.8.2: das erforderliche Speichervolumen erhält man durch iterative Anwendung der Gl. 41 für unterschiedliche Dauerstufen D und jeweils zugehöriger Regenspende r_D(n).
[EN] Rainfall intensity r_D(n) in l/(s·ha) of the governing duration for the design frequency n_B, determined by the tool during the iteration of Eq. 41 from the rainfall table — the duration with the largest V_VA governs. §6.8.2: the required storage volume is obtained by iterative application of Eq. 41 for different durations D with their rainfall intensity r_D(n).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'r_D_n_B';
UPDATE fields f SET description = 'Bemessungshäufigkeit des Beckens in 1/a, vom Planer nach Tab. 8 gewählt. Das Tool wählt damit die r_D(n)-Spalte für Gl. 41. Ein Becken an öffentlichen Regenwasserkanälen fällt in die Tab.-8-Spalte „A_C > 800 m² und öffentliche Entwässerung“ (z. B. Kategorie 2: ≤ 0,33/a, Kategorie 3: ≤ 0,2/a); §5.3.3.4: für diese Häufigkeit darf kein Überlauf auftreten; zusätzlich Überflutungsnachweis nach 5.3.4.
[EN] Design frequency of the basin in 1/a, chosen by you per Tab. 8. The tool uses it to select the r_D(n) column for Eq. 41. A basin fed by public stormwater sewers falls into the Tab. 8 column “A_C > 800 m² and public drainage” (e.g. category 2: ≤ 0.33/a, category 3: ≤ 0.2/a); §5.3.3.4: no overflow may occur for this frequency; in addition a flood check per 5.3.4.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND f.symbol = 'n_B_Bemessung';
UPDATE equations e SET description = 'Speichergleichung des Beckens, analog zur Mulde (Gl. 14): V_VA = [(A_C + A_VA)·10⁻⁷·r_D(n) − A_S,m·k_i − Q_Dr·10⁻³]·D·60·f_Z·f_A — Zufluss (A_C plus überregnete Beckenfläche) minus Versickerung über A_S,m mit k_i (bewachsene Bodenzone beachten) minus Drosselabfluss, mal Dauer, f_Z und Abminderungsfaktor f_A (DWA-A 117, i. d. R. ≅ 1). §6.8.2: iterative Anwendung für unterschiedliche Dauerstufen D; ggf. unterschiedliche k_f in Sohle und Böschung; Entleerungszeit nach 6.3.2/Tab. 14 (≤ 84 h bei n = 1/a).
[EN] Storage equation of the basin, analogous to the swale (Eq. 14): V_VA = [(A_C + A_VA)·10⁻⁷·r_D(n) − A_S,m·k_i − Q_Dr·10⁻³]·D·60·f_Z·f_A — inflow (A_C plus rained-on basin area) minus infiltration through A_S,m with k_i (consider the vegetated soil zone) minus throttled outflow, times duration, f_Z and reduction factor f_A (DWA-A 117, as a rule ≅ 1). §6.8.2: iterative application for different durations D; different k_f in base and slopes where applicable; emptying time per 6.3.2/Tab. 14 (≤ 84 h at n = 1/a).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-22' AND e.equation_number = '41';
UPDATE fields f SET description = 'Ergebnis der Phase-4-Prüfung (Anlagenbemessung) als PASS, CONDITIONAL oder FAIL; wird vom Ingenieur nach Abschluss des anlagenspezifischen Bemessungsblatts (A138-11 bis A138-22) festgelegt, die Tool-Empfehlung darunter dient als Vorschlag. Das Feld speist Gate A138-REQ-19: nur PASS oder CONDITIONAL öffnet Phase 5 (Verifikation). Maßstab ist Abschnitt 6: Tabelle 14 (§6.9) stellt die Planungs- und Bemessungsvorgaben aus §6.2 bis §6.8 zusammen; CONDITIONAL nur mit benannter Auflage.
[EN] Result of the Phase-4 check (facility design) as PASS, CONDITIONAL or FAIL; you set it after completing the facility-specific design sheet (A138-11 to A138-22), with the tool''s recommendation below as a proposal. The field feeds gate A138-REQ-19: only PASS or CONDITIONAL opens Phase 5 (verification). The yardstick is Section 6: Table 14 (§6.9) compiles the planning and design specifications of §6.2 to §6.8; use CONDITIONAL only with a named condition.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'phase_4_gate_result';
UPDATE fields f SET description = 'Der Anlagentyp, für den die anlagenspezifische Bemessung tatsächlich durchgeführt wurde; aus der Typwahl in A138-10 übernehmen und mit dem ausgefüllten Bemessungsblatt abgleichen. Legt fest, welche Gleichungen und Vorgaben aus §6.2 bis §6.8 für Phase 5 und die Konformitätserklärung gelten. Bild 7 (§6.1) zeigt die sieben Grundtypen (Fläche, Mulde, Rigole, MR-Element, MR-System, Schacht, Becken); Varianten sind nach §6.1 möglich und nachvollziehbar zu dokumentieren.
[EN] The facility type for which the facility-specific design was actually carried out; carry it over from the type selection in A138-10 and reconcile it with the completed design sheet. It determines which equations and specifications of §6.2 to §6.8 apply in Phase 5 and the conformity declaration. Bild 7 (§6.1) shows the seven basic types (area, swale, trench, swale-trench element, swale-trench system, shaft, basin); variants are allowed under §6.1 and must be documented traceably.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'facility_type_dimensioned';
UPDATE fields f SET description = 'Das aus der anlagenspezifischen Bemessungsgleichung des gewählten Typs (§6.2 bis §6.8) ermittelte Speichervolumen; aus dem Bemessungsblatt übernehmen (bei der Versickerungsfläche entfällt es, §5.3.3.7). Dient in A138-24 als V_VA (final) und geht nach §5.3.4.1 in Gl. 10 des Überflutungsnachweises ein. Nach §5.3.3.7 ist das erforderliche Speichervolumen die Bemessungszielgröße; die maßgebende Dauerstufe D ist schrittweise zu bestimmen, bis das Maximum gefunden ist.
[EN] The storage volume obtained from the facility-specific design equation of the chosen type (§6.2 to §6.8); carry it over from the design sheet (not applicable to the infiltration area, §5.3.3.7). It becomes V_VA (final) in A138-24 and enters Eq. 10 of the flood proof under §5.3.4.1. Per §5.3.3.7 the required storage volume is the design target; the governing duration D must be found step by step until the maximum is reached.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'facility_specific_volume_m3';
UPDATE fields f SET description = 'Grundfläche, die die bemessene Anlage im Grundriss belegt; aus der Geometrie des Bemessungsblatts (Sohlfläche, Rigolenbreite × Länge, Beckenfläche) übernehmen. Wird für den Flächennachweis im Lageplan, die Abstandsprüfungen und als Plausibilitätsgröße gegenüber A_S,m benötigt. Die Richtlinie gibt für die Aufstandsfläche keinen Grenzwert; Bild 7 (§6.1) ordnet die Anlagentypen nur nach Flächenbedarf von hoch (Versickerungsfläche) bis gering (Schacht).
[EN] Plan area the designed facility occupies; take it from the geometry on the design sheet (e.g. base area, trench width × length, basin area). Needed for the area proof on the site plan, the distance checks and as a plausibility figure against the mean infiltration area A_S,m. The guideline sets no limit on the footprint itself; Bild 7 (§6.1) only orders the facility types by space demand from high (infiltration area) to low (shaft).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'facility_footprint_m2';
UPDATE fields f SET description = 'Bestätigung, dass die bemessene Anlage mit ihrer endgültigen mittleren Versickerungsfläche A_S,m die Anwendungsgrenze des Einfachen Verfahrens einhält; Wert aus dem Bemessungsblatt bzw. A138-09. Fließt in das Phase-4-Tor ein und wird in A138-25 abschließend verifiziert. §5.3.3.7, Gl. 9: q_S,AC = (k_i · A_S,m · 1000 + Q_Dr) / AC · 10⁴ ≥ 2 l/(s·ha); nach §5.3.3.2 ist die Einhaltung der Bedingungen des Einfachen Verfahrens bei der Bemessung nachzuweisen.
[EN] Confirmation that the designed facility, with its final mean infiltration area A_S,m, meets the application limit of the simple method; value from the design sheet or A138-09. It feeds the Phase-4 gate and is finally verified in A138-25. §5.3.3.7, Eq. 9: q_S,AC = (k_i · A_S,m · 1000 + Q_Dr) / AC · 10⁴ ≥ 2 l/(s·ha); per §5.3.3.2 compliance with the conditions of the simple method must be demonstrated in the design.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'facility_meets_qsac';
UPDATE fields f SET description = 'Bestätigung des Ingenieurs, dass alle Pflichtfelder des anlagenspezifischen Bemessungsblatts ausgefüllt sind und das Maximum über die Dauerstufen D gefunden wurde. Voraussetzung für das Phase-4-Tor; ohne diese Bestätigung bleibt der Übergang in Phase 5 gesperrt. §5.3.3.7: Die maßgebende Dauerstufe ist im Einfachen Verfahren iterativ zu bestimmen, bis sich ein eindeutiges Maximum des erforderlichen Speichervolumens ergibt.
[EN] Your confirmation that all mandatory fields of the facility-specific design sheet are filled and that the maximum over the rain durations D has been found. Prerequisite for the Phase-4 gate; without it the transition to Phase 5 stays blocked. §5.3.3.7: in the simple method the governing duration is determined iteratively until a clear maximum of the required storage volume is found.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'facility_specific_dimensioning_complete';
UPDATE fields f SET description = 'Datum, an dem die anlagenspezifische Bemessung abgeschlossen und freigegeben wurde; vom Ingenieur eintragen. Dient der Nachvollziehbarkeit im Bericht und zeigt, auf welchem Stand der Eingangsdaten (Flächenverzeichnis, k_i, KOSTRA) die Bemessung beruht. Die Richtlinie schreibt kein Datum vor; es ist ein Dokumentationsfeld des Workflows.
[EN] Date on which the facility-specific design was completed and released; you enter it. It provides traceability in the report and shows which state of the input data (surface inventory, k_i, KOSTRA) the design is based on. The guideline does not prescribe a date; this is a workflow documentation field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'facility_design_completion_date';
UPDATE fields f SET description = 'Vom Tool geschriebene, schreibgeschützte Empfehlung für das Phase-4-Tor (PASS / CONDITIONAL / FAIL), abgeleitet aus den Gate-Ergebnissen des Bemessungsblatts und der q_S,AC-Prüfung. Nicht manuell ändern; die Empfehlung mit der eigenen Entscheidung in ''Phase-4-Tor Ergebnis'' abgleichen und Abweichungen begründen. Die Richtlinie kennt kein solches Tor; das Feld ist eine Workflow-Hilfe.
[EN] Tool-written, read-only recommendation for the Phase-4 gate (PASS / CONDITIONAL / FAIL), derived from the gate results of the design sheet and the q_S,AC check. Do not edit manually; compare it with your own decision in ''Phase 4 Gate Result'' and justify any difference. The guideline has no such gate; the field is a workflow aid.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'recommended_phase_4_gate';
UPDATE fields f SET description = 'Vom Tool geschriebener Freitext, der die empfohlene Tor-Entscheidung begründet (z. B. welche Gates offen sind, ob q_S,AC ≥ 2 l/(s·ha) erfüllt ist). Hilft, die Empfehlung nachzuvollziehen und im Bericht zu zitieren. Nicht bearbeiten; eigene Anmerkungen gehören in das Bemessungsblatt oder in A138-25.
[EN] Tool-written free text explaining the recommended gate result (e.g. which gates are open, whether q_S,AC ≥ 2 l/(s·ha) is met). It helps you follow the recommendation and quote it in the report. Do not edit; put your own remarks in the design sheet or in A138-25.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-23' AND f.symbol = 'phase_4_recommendation_reasons';
UPDATE fields f SET description = 'Bestätigung des Ingenieurs, dass die kombinierte Ergebnis-Zusammenstellung vollständig ist und alle Endwerte (A_C, V_VA, Q_S, q_S,AC, Anlagentyp, T_n, Verfahren) mit den Bemessungsblättern übereinstimmen. Das Feld ist Bedingung des Gates A138-REQ-20 und wird in der Konformitätserklärung ausgewiesen. Fachliche Grundlage ist §5.3.3.7 (Bemessungsgleichung Gl. 8 und Anwendungsprüfung Gl. 9); erst nach der Prüfung bestätigen.
[EN] Your confirmation that the combined results compilation is complete and that all final values (A_C, V_VA, Q_S, q_S,AC, facility type, T_n, method) agree with the design sheets. The field is the condition of gate A138-REQ-20 and is shown in the conformity declaration. The technical basis is §5.3.3.7 (design equation Eq. 8 and application check Eq. 9); confirm only after checking.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'attest_a138_24_a138_req_20';
UPDATE fields f SET description = 'Endgültiger Rechenwert für die Bemessung, übernommen aus dem Flächenverzeichnis (A138-07) nach Abschluss aller Flächenänderungen. Er ist Bezugsgröße für q_S,AC (Gl. 9), für die 800-m²-Schwelle des Überflutungsnachweises und für die Bemessungshäufigkeit nach Tabelle 8. §5.3.3.5, Gl. 2: AC = Σ(A_E,b,a,i · C_i) + Σ(A_E,nb,a,i · C_i), Summe aller angeschlossenen Teilflächen mal zugehörigem Abflussbeiwert (z. B. nach Tabelle 9, mittlerer Beiwert C_m).
[EN] Final design value, carried over from the surface inventory (A138-07) after all area changes are closed. It is the reference for q_S,AC (Eq. 9), for the 800 m² threshold of the flood proof and for the design frequency of Table 8. §5.3.3.5, Eq. 2: AC = Σ(A_E,b,a,i · C_i) + Σ(A_E,nb,a,i · C_i), the sum of all connected sub-areas times their runoff coefficient (e.g. per Table 9, mean coefficient C_m).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'A_C_final';
UPDATE fields f SET description = 'Endgültiges erforderliches Speichervolumen der Anlage aus dem anlagenspezifischen Bemessungsblatt (Maximum über die Dauerstufen D). Es ist die Bemessungszielgröße nach §5.3.3.7 und wird im Überflutungsnachweis (Gl. 10) als bereits gefülltes Volumen abgezogen. §5.3.3.7, Gl. 8: V_VA = (Q_zu − Q_S − Q_Dr) · D · 60 · f_Z · f_A · 10⁻³; nach §5.3.4.1 darf zusätzlich das Volumen sonstiger Speicher (z. B. Retentionsdächer) in V_VA eingehen.
[EN] Final required storage volume of the facility from the facility-specific design sheet (maximum over the durations D). It is the design target per §5.3.3.7 and is subtracted in the flood proof (Eq. 10) as volume already filled. §5.3.3.7, Eq. 8: V_VA = (Q_zu − Q_S − Q_Dr) · D · 60 · f_Z · f_A · 10⁻³; per §5.3.4.1 the volume of other storages (e.g. retention roofs) may additionally be counted in V_VA.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'V_VA_final';
UPDATE fields f SET description = 'Endgültige Versickerungsleistung der Anlage, vom Tool aus der bemessungsrelevanten Infiltrationsrate k_i (A138-08) und der endgültigen Versickerungsfläche des Bemessungsblatts berechnet. Wird für Gl. 9 und als Q_S im Überflutungsnachweis (Gl. 10) weiterverwendet. §5.3.3.6, Gl. 4: Q_S = k_i · A_S · 10³ (l/s); im Einfachen Verfahren wird nach Gl. 7 die mittlere Versickerungsfläche A_S,m = (A_S,min + A_S,max) / 2 zugrunde gelegt.
[EN] Final infiltration capacity of the facility, computed by the tool from the design infiltration rate k_i (A138-08) and the final infiltration area of the design sheet. It is reused for Eq. 9 and as Q_S in the flood proof (Eq. 10). §5.3.3.6, Eq. 4: Q_S = k_i · A_S · 10³ (l/s); in the simple method the mean infiltration area A_S,m = (A_S,min + A_S,max) / 2 per Eq. 7 is used.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'Q_S_final';
UPDATE fields f SET description = 'Endgültige spezifische Versickerungs-/Abflussleistung, vom Tool aus k_i, der endgültigen A_S,m, Q_Dr und A_C (final) berechnet. Sie entscheidet, ob das Einfache Verfahren anwendbar bleibt, und steuert den Zuschlagsfaktor f_Z. §5.3.3.7, Gl. 9: q_S,AC = (k_i · A_S,m · 1000 + Q_Dr) / AC · 10⁴ ≥ 2 l/(s·ha); bei q_S,AC ≤ 5 l/(s·ha) ist f_Z = 1,2 erforderlich. Nach §6.3.2 entfällt im Einfachen Verfahren ein gesonderter Nachweis der Entleerungszeit, weil diese Anwendungsgrenze greift.
[EN] Final specific infiltration/discharge capacity, computed by the tool from k_i, the final A_S,m, Q_Dr and A_C (final). It decides whether the simple method remains applicable and controls the surcharge factor f_Z. §5.3.3.7, Eq. 9: q_S,AC = (k_i · A_S,m · 1000 + Q_Dr) / AC · 10⁴ ≥ 2 l/(s·ha); if q_S,AC ≤ 5 l/(s·ha), f_Z = 1.2 is required. Per §6.3.2 no separate emptying-time proof is needed in the simple method because this application limit applies.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'q_S_AC_final';
UPDATE fields f SET description = 'Endgültig gewählter Anlagentyp nach Bild 7 (§6.1); muss mit dem in A138-23 dimensionierten Typ übereinstimmen. Steuert, welche anlagenspezifischen Vorgaben (Tabelle 14) in Bericht und Konformitätserklärung zitiert werden. §6.1 nennt Versickerungsfläche, Versickerungsmulde, Rigole, Mulden-Rigolen-Element, Mulden-Rigolen-System, Versickerungsschacht und Versickerungsbecken; bei Varianten sind die Berechnungsansätze nachvollziehbar zu dokumentieren.
[EN] Finally chosen facility type per Bild 7 (§6.1); it must match the type dimensioned in A138-23. It controls which facility-specific specifications (Table 14) are cited in the report and the conformity declaration. §6.1 names infiltration area, infiltration swale, trench, swale-trench element, swale-trench system, infiltration shaft and infiltration basin; for variants the calculation approaches must be documented traceably.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'facility_type_final';
UPDATE fields f SET description = 'Kurzbeschreibung der endgültigen Anlagengeometrie in Worten (z. B. Sohlfläche, Einstauhöhe, Böschungsneigung, Rigolenabmessungen, Schachtdurchmesser), aus dem Bemessungsblatt zusammengefasst. Erleichtert die Übernahme in Lageplan und Bericht und den Abgleich mit den Vorgaben der Tabelle 14 (§6.9). Die Ausführungsplanung muss nach §5.3.5 (Schluss) die Anlage vollständig in Grundriss und Schnitt mit allen Höhen und Böschungsneigungen darstellen.
[EN] Short description in words of the final facility geometry (e.g. base area, impoundment depth, side slope, trench dimensions, shaft diameter), summarised from the design sheet. It eases transfer into the site plan and report and the comparison with the specifications of Table 14 (§6.9). Per the end of §5.3.5 the detailed design must show the facility completely in plan and section with all levels and slope gradients.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'geometry_final_summary';
UPDATE fields f SET description = 'Für die Bemessung verwendete Wiederkehrzeit der KOSTRA-Regenspenden, übernommen aus der Festlegung der Bemessungshäufigkeit (A138-06) und dem Bemessungsblatt. Sie legt fest, welche Spalte der Regenstatistik in Gl. 8 eingeht, und wird im Bericht als Bemessungsgrundlage ausgewiesen. §5.3.3.4, Tabelle 8: Bemessungshäufigkeit nach Schutzkategorie und AC ≤ / > 800 m²; §5.3.3.2: im Einfachen Verfahren T_n ≤ 10 a (n ≥ 0,1/a); §5.3.3.5: KOSTRA-DWD-2020 mit den exakten Werten des DWD.
[EN] Return period of the KOSTRA rainfall intensities used for the design, carried over from the design-frequency decision (A138-06) and the design sheet. It fixes which column of the rainfall statistics enters Eq. 8 and is reported as the design basis. §5.3.3.4, Table 8: design frequency by protection category and AC ≤ / > 800 m²; §5.3.3.2: in the simple method T_n ≤ 10 a (n ≥ 0.1/a); §5.3.3.5: KOSTRA-DWD-2020 with the exact DWD values.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'kostra_design_T_n';
UPDATE fields f SET description = 'Endgültig angewandtes Bemessungsverfahren, übernommen aus der Verfahrenswahl (A138-05/06). Legt fest, welche Nachweise die Konformitätserklärung enthalten muss. §5.3.3.2 Einfaches Verfahren: A_E ≤ 200 ha oder t_f ≤ 15 min, T_n ≤ 10 a, q_S ≥ 2 l/(s·ha), Regenhäufigkeit = Bemessungshäufigkeit; für dezentrale Anlagen in der Regel anwendbar. §5.3.3.3 Nachweisverfahren (Langzeitsimulation) für zentrale und vernetzte Anlagen empfohlen; Regenreihe ≥ 10 a, M ≥ 3 · T_n (Gl. 1).
[EN] Design method finally applied, carried over from the method selection (A138-05/06). It determines which proofs the conformity declaration must contain. §5.3.3.2 simple method: A_E ≤ 200 ha or t_f ≤ 15 min, T_n ≤ 10 a, q_S ≥ 2 l/(s·ha), rain frequency = design frequency; generally applicable to decentralised facilities. §5.3.3.3 verification method (long-term simulation) recommended for central and networked facilities; rainfall series ≥ 10 a, M ≥ 3 · T_n (Eq. 1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'design_basis_final';
UPDATE fields f SET description = 'Endgültige Feststellung, ob ein rechnerischer Überflutungsnachweis zu führen ist; vom Tool aus A_C (final) als Summe aller abflusswirksamen Flächen des Grundstücks abgeleitet, vom Ingenieur zu bestätigen. Steuert, ob A138-26 Pflicht ist (Gate A138-REQ-22). §5.3.4.1: Für innerörtliche Grundstücke ist ein Überflutungsnachweis nach DIN 1986-100 erforderlich, wenn AC > 800 m²; auch bei AC < 800 m² ist die Schadenswirkung eines Versagens zu betrachten und ggf. eine Notentwässerung vorzusehen.
[EN] Final determination whether a computational flood proof must be provided; derived by the tool from A_C (final) as the sum of all runoff-effective surfaces of the plot, to be confirmed by you. It controls whether A138-26 is mandatory (gate A138-REQ-22). §5.3.4.1: for plots within built-up areas a flood proof per DIN 1986-100 is required if AC > 800 m². Even for AC < 800 m², §5.3.4.1 requires considering the damage a failure could cause and providing emergency drainage if necessary.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'flood_check_required_final';
UPDATE fields f SET description = 'Datum, an dem die kombinierte Ergebnis-Zusammenstellung abgeschlossen wurde; vom Ingenieur eintragen. Markiert den Stand der Endwerte, auf den sich Verifikation (A138-25/26) und Konformitätserklärung beziehen. Die Richtlinie schreibt kein Datum vor; Workflow-Dokumentationsfeld.
[EN] Date on which the combined results compilation was completed; you enter it. It marks the state of the final values that verification (A138-25/26) and the conformity declaration refer to. The guideline does not prescribe a date; workflow documentation field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-24' AND f.symbol = 'compilation_completion_date';
UPDATE fields f SET description = 'Gesamtergebnis der abschließenden Eignungsprüfung (PASS / FAIL / NA), vom Ingenieur nach den Einzelprüfungen dieses Blatts festgelegt; NA nur, wenn Gl. 9 für den Typ nicht einschlägig ist (z. B. Nachweisverfahren). Speist Gate A138-REQ-21: nur PASS oder NA lässt die Konformitätserklärung zu. Kern ist §5.3.3.7, Gl. 9 mit der endgültigen A_S,m: q_S,AC ≥ 2 l/(s·ha); nach §5.3.3.2 ist die Einhaltung der Bedingungen des Einfachen Verfahrens bei der Bemessung nachzuweisen.
[EN] Overall result of the final adequacy check (PASS / FAIL / NA), set by you after the individual checks on this sheet; NA only when Eq. 9 does not apply to the case (e.g. verification method). It feeds gate A138-REQ-21: only PASS or NA allows the conformity declaration. The core is §5.3.3.7, Eq. 9 with the final A_S,m: q_S,AC ≥ 2 l/(s·ha); per §5.3.3.2 compliance with the simple-method conditions must be demonstrated in the design.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-25' AND f.symbol = 'design_adequacy_result';
UPDATE fields f SET description = 'Bestätigung, dass der verifizierte Wert q_S,AC die Anwendungsgrenze einhält; mit dem darunter eingetragenen Wert vergleichen. Ist das Kriterium verletzt, ist das Einfache Verfahren nicht anwendbar: Anlage vergrößern (A_S,m), Drosselabfluss vorsehen oder nach §5.3.3.3 ins Nachweisverfahren wechseln. §5.3.3.7, Gl. 9: q_S,AC ≥ 2 l/(s·ha); dieselbe Bedingung steht in §5.3.3.2 als Anwendungsbedingung des Einfachen Verfahrens.
[EN] Confirmation that the verified q_S,AC value meets the application limit; compare it with the value entered below. If the criterion is violated the simple method is not applicable: enlarge the facility (A_S,m), add a throttled outflow, or switch to the verification method per §5.3.3.3. §5.3.3.7, Eq. 9: q_S,AC ≥ 2 l/(s·ha); the same condition appears in §5.3.3.2 as an application condition of the simple method.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-25' AND f.symbol = 'qsac_geq_2_check';
UPDATE fields f SET description = 'Der abschließend geprüfte Wert q_S,AC, nachgerechnet mit der endgültigen mittleren Versickerungsfläche A_S,m, dem bemessungsrelevanten k_i, dem mittleren Drosselabfluss Q_Dr und A_C (final); mit q_S_AC_final aus A138-24 abgleichen. Der Wert wird im Bericht als Nachweis der Anwendungsbedingung ausgewiesen. §5.3.3.7, Gl. 9: q_S,AC = (k_i · A_S,m · 1000 + Q_Dr) / AC · 10⁴ in l/(s·ha); A_S,m nach Gl. 7 als Mittel aus Sohlfläche und Fläche bei Volleinstau.
[EN] The finally checked q_S,AC value, recomputed with the final mean infiltration area A_S,m, the design infiltration rate k_i, the mean throttled outflow Q_Dr and A_C (final); reconcile it with q_S_AC_final from A138-24. The value is reported as proof of the application condition. §5.3.3.7, Eq. 9: q_S,AC = (k_i · A_S,m · 1000 + Q_Dr) / AC · 10⁴ in l/(s·ha); A_S,m per Eq. 7 as the mean of base area and area at full impoundment.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-25' AND f.symbol = 'qsac_value_verified';
UPDATE fields f SET description = 'Bestätigung, dass der Abstand zwischen der endgültigen Anlagensohle (Rigole: Unterkante; Schacht Typ A: Schachtsohle, Typ B: Unterkante Filterschicht) und dem maßgeblichen MHGW aus A138-04 eingehalten ist; Standortnachweis für die Konformitätserklärung. §5.1.1 und §5.2.1: Bei ≥ 1 m Abstand zum MHGW kann in der Regel auf die Abstimmung mit der Genehmigungsbehörde verzichtet werden, sonst ist der Abstand mit ihr abzustimmen; in Trinkwasser- und Heilquellenschutzgebieten gelten weitergehende Anforderungen.
[EN] Confirmation that the distance between the final facility base (trench: underside; shaft type A: shaft base, type B: underside of filter layer) and the governing MHGW from A138-04 is met; the site proof for the conformity declaration. §5.1.1 and §5.2.1: with ≥ 1 m from facility base to MHGW the agreement with the permitting authority can normally be waived, otherwise the distance must be agreed with it; stricter requirements apply in drinking-water and medicinal-spring protection areas.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-25' AND f.symbol = 'mhgw_clearance_ge_1m_check';
UPDATE fields f SET description = 'Bestätigung, dass die Anwendungsbedingungen des gewählten Bemessungsverfahrens abschließend geprüft und dokumentiert sind (Einfaches Verfahren: die vier Bedingungen nach §5.3.3.2; Nachweisverfahren: Anforderungen an die Regenreihe nach §5.3.3.3). Die Prüfung gehört zum Bemessungsnachweis in Bericht und Konformitätserklärung. §5.3.3.2: Die Einhaltung der Bedingungen ist bei der Bemessung nachzuweisen; §5.3.3.3: Regenreihe ≥ 10 Jahre, empfohlen M ≥ 3 · T_n (Gl. 1).
[EN] Confirmation that the application conditions of the chosen design method have been finally checked and documented (for the simple method the four conditions of §5.3.3.2, for the verification method the rainfall-series requirements of §5.3.3.3). The check is part of the design proof in the report and conformity declaration. §5.3.3.2: compliance with the conditions for the simple method must be demonstrated in the design; §5.3.3.3: rainfall series ≥ 10 years, recommended M ≥ 3 · T_n (Eq. 1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-25' AND f.symbol = 'qf_validation_complete';
UPDATE fields f SET description = 'Bestätigung, dass der im Bemessungsblatt verwendete Zuschlagsfaktor f_Z zum verifizierten q_S,AC passt; Wert aus A138-09 bzw. dem Bemessungsblatt prüfen. Ein zu kleiner f_Z führt zu einer Unterbemessung des Speichervolumens und muss vor der Konformitätserklärung korrigiert werden. §5.3.3.7: f_Z beugt einer Unterbemessung im Einfachen Verfahren vor; empfohlen 1,1 bis 1,2 je nach Risikomaß nach DWA-A 117; bei q_S,AC ≤ 5 l/(s·ha) ist f_Z = 1,2 erforderlich.
[EN] Confirmation that the surcharge factor f_Z used on the design sheet matches the verified q_S,AC; check the value from A138-09 or the design sheet. Too small an f_Z under-sizes the storage volume and must be corrected before the conformity declaration. §5.3.3.7: f_Z guards against under-sizing in the simple method; 1.1 to 1.2 recommended depending on the risk measure per DWA-A 117; for q_S,AC ≤ 5 l/(s·ha), f_Z = 1.2 is required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-25' AND f.symbol = 'f_Z_appropriate_check';
UPDATE fields f SET description = 'Datum, an dem die Bemessungs-Eignungsprüfung abgeschlossen wurde; vom Ingenieur eintragen. Dokumentiert, auf welchem Stand der Endwerte aus A138-24 die Verifikation beruht, und wird im Bericht ausgewiesen. Die Richtlinie schreibt kein Datum vor; Workflow-Dokumentationsfeld.
[EN] Date on which the design adequacy check was completed; you enter it. It documents which state of the final values from A138-24 the verification is based on and is shown in the report. The guideline does not prescribe a date; workflow documentation field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-25' AND f.symbol = 'verification_completion_date';
UPDATE fields f SET description = 'Freitext für Anmerkungen zur Eignungsprüfung: Begründung eines NA, Hinweise auf knappe Reserven (z. B. q_S,AC nahe 2 l/(s·ha)), abgestimmte Abweichungen mit der Behörde beim MHGW-Abstand, Verweise auf Belege. Wird in den Bericht übernommen und hilft dem Design Review in A138-27. Kein Pflichtinhalt der Richtlinie; Workflow-Feld.
[EN] Free text for remarks on the adequacy check: justification of an NA, notes on thin margins (e.g. q_S,AC close to 2 l/(s·ha)), authority-agreed deviations on the MHGW distance, references to evidence. It is carried into the report and supports the design review in A138-27. Not a mandatory content of the guideline; workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-25' AND f.symbol = 'verification_notes';
UPDATE fields f SET description = 'Bestätigung des Ingenieurs, dass die Abweichungsanalyse zum Überflutungsnachweis dokumentiert ist, d. h. Abweichungen zwischen Bemessungs- und Überflutungsfall (Spitzen- statt mittlere Abflussbeiwerte, zusätzliche Speicher, Einstauflächen) nachvollziehbar festgehalten sind. Bedingung des Gates A138-REQ-24. §5.3.4.1 verlangt, dass der schadlose Verbleib der zurückzuhaltenden Regenwassermenge auf dem Grundstück nachgewiesen wird; die Dokumentationsform selbst gibt die Richtlinie nicht vor.
[EN] Your confirmation that the deviation analysis for the flood proof is documented, i.e. differences between design and flood case (peak instead of mean runoff coefficients, additional storages, ponding areas) are recorded traceably. Condition of gate A138-REQ-24. §5.3.4.1 requires proof that the rainwater volume to be retained can remain harmlessly on the plot; the guideline does not prescribe the form of documentation itself.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'attest_a138_26_a138_req_24';
UPDATE fields f SET description = 'Bestätigung des Ingenieurs, dass die erforderlichen Freigaben zum Überflutungsnachweis eingeholt sind (Bauherr für die Einstauflächen auf dem Grundstück, ggf. Kommune/Wasserbehörde für Notüberlauf oder Kanalanschluss). Bedingung des Gates A138-REQ-26. §5.3.4.1: Ist der Anschluss eines Überlaufs an den öffentlichen Kanal geplant und satzungsrechtlich möglich, ist das Erfordernis einer Rückstausicherung zu prüfen (DIN 1986-100, DIN EN 12056-4).
[EN] Your confirmation that the approvals required for the flood proof have been collected (owner for the ponding areas on the plot, municipality/water authority where an emergency overflow or sewer connection is planned). Condition of gate A138-REQ-26. §5.3.4.1: if the connection of an overflow to the public sewer is planned and permitted by the municipal statutes, the need for backflow protection must be checked (DIN 1986-100, DIN EN 12056-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'attest_a138_26_a138_req_26';
UPDATE fields f SET description = 'Ergebnis des Überflutungsnachweises (PASS / FAIL / NA), vom Ingenieur festgelegt: PASS, wenn V_Rück vollständig und schadlos auf dem Grundstück verbleiben kann; NA, wenn nach A138-24 kein Nachweis erforderlich ist. Speist Gate A138-REQ-23 und die Konformitätserklärung. §5.3.4.1: Der schadlose Verbleib kann durch zusätzlichen Speicherraum oder durch Einstau in der Fläche erfolgen; bei hydraulisch unabhängigen Entwässerungseinheiten ist der Nachweis getrennt zu führen.
[EN] Result of the flood proof (PASS / FAIL / NA), set by you: PASS when V_Rück can remain completely and harmlessly on the plot; NA when A138-24 shows no proof is required. It feeds gate A138-REQ-23 and the conformity declaration. §5.3.4.1: harmless retention may be achieved by additional storage space or by ponding on the surface; for hydraulically independent drainage units the proof must be carried out separately.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'flood_check_result';
UPDATE fields f SET description = 'Wiederkehrzeit für den Überflutungsnachweis; vom Ingenieur nach dem Anteil der Dach- und nicht überflutbaren Flächen im Flächenverzeichnis festlegen. Bestimmt, welche KOSTRA-Spalte (r_D(30) oder r_D(100)) in Gl. 10 eingeht. §5.3.4.1: in der Regel n = 0,033/a (T_n = 30 a) für alle Schutzkategorien der Tabelle 8; bestehen die befestigten Flächen zu mehr als 70 % aus Dachflächen und nicht überflutbaren Flächen wie Innenhöfen, ist mit T_n = 100 a und r_D(100) zu rechnen.
[EN] Return period for the flood proof; you set it from the share of roof and non-floodable surfaces in the surface inventory. It determines which KOSTRA column (r_D(30) or r_D(100)) enters Eq. 10. §5.3.4.1: as a rule n = 0.033/a (T_n = 30 a) for all protection categories of Table 8; if more than 70 % of the paved surfaces are roofs and non-floodable surfaces such as inner courtyards, use T_n = 100 a with r_D(100).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'T_n_Ue';
UPDATE fields f SET description = 'Zurückzuhaltende Regenwassermenge im Überflutungsfall, vom Tool nach Gl. 10 für die maßgebende Dauerstufe berechnet (Maximum über alle D). Sie ist der Wert, dessen schadloser Verbleib auf dem Grundstück nachzuweisen ist (Gate A138-REQ-22/23). §5.3.4.1, Gl. 10: V_Rück = ((r_D(30) · (Σ(A_E,b,a · C_S) + A_VA) / 10 000 − (Q_S + Q_Dr)) · D · 60 / 1000 − V_VA ≥ 0; ergibt sich ein negativer Wert, wird V_Rück = 0 gesetzt.
[EN] Rainwater volume to be retained in the flood case, computed by the tool per Eq. 10 for the governing duration (maximum over all D). It is the value whose harmless retention on the plot must be proven (gates A138-REQ-22/23). §5.3.4.1, Eq. 10: V_Rück = ((r_D(30) · (Σ(A_E,b,a · C_S) + A_VA) / 10 000 − (Q_S + Q_Dr)) · D · 60 / 1000 − V_VA ≥ 0; if the result is negative, V_Rück = 0 is set.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'V_Rueck';
UPDATE fields f SET description = 'Regenspende für die gewählte Dauerstufe D und die Wiederkehrzeit T_n = 30 a aus der KOSTRA-Statistik des Standorts (A138-06); bei T_n = 100 a entsprechend r_D(100) eintragen. Geht als Niederschlagsbelastung in Gl. 10 ein und wird für jede geprüfte Dauerstufe neu angesetzt. §5.3.4.1: Bei Verwendung von KOSTRA-Regenspenden sind die exakten Werte des DWD (DWD-Vorgabe) zu verwenden; §5.3.3.5: Bezug ist KOSTRA-DWD-2020.
[EN] Rainfall intensity for the chosen duration D and return period T_n = 30 a from the KOSTRA statistics of the site (A138-06); for T_n = 100 a enter r_D(100) accordingly. It enters Eq. 10 as the rainfall load and is re-read for each duration checked. §5.3.4.1: when KOSTRA intensities are used, the exact DWD values (DWD specification) must be used; §5.3.3.5: the reference dataset is KOSTRA-DWD-2020.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'r_D_30';
UPDATE fields f SET description = 'Summe der befestigten, angeschlossenen Teilflächen im Einzugsgebiet, übernommen aus dem Flächenverzeichnis (A138-07) ohne Abflussbeiwert. Sie wird in Gl. 10 zusammen mit dem Spitzenabflussbeiwert C_S zur abflusswirksamen Fläche; bei mehreren Teilflächen ist die Summe Σ(A_E,b,a · C_S) maßgebend (siehe A_C,s). §5.3.4.1: A_E,b,a = befestigte, angeschlossene Fläche im Einzugsgebiet; gegebenenfalls können abflussrelevante nicht befestigte Flächen mit einbezogen werden.
[EN] Sum of the paved, connected sub-areas in the catchment, carried over from the surface inventory (A138-07) without runoff coefficient. In Eq. 10 it is combined with the peak runoff coefficient C_S to give the runoff-effective area; with several sub-areas the sum Σ(A_E,b,a · C_S) governs (see A_C,s). §5.3.4.1: A_E,b,a = paved, connected area in the catchment; runoff-relevant unpaved surfaces may be included where appropriate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'A_E_b_a_flood';
UPDATE fields f SET description = 'Spitzenabflussbeiwert der befestigten Flächen für den Überflutungsfall; aus Tabelle 9, Spalte C_s, je Teilfläche wählen (bei mehreren Flächen flächengewichtet oder über A_C,s). Er ersetzt in Gl. 10 den mittleren Beiwert C_m der Bemessung, weil im seltenen Starkregen praktisch der gesamte Niederschlag abfließt. §5.3.4.1 Gl. 10 mit Tabelle 9 (§5.3.3.5), z. B. Dachflächen 1,0, Asphalt/Beton 1,0, Betonsteinpflaster in Sand 0,9, Rasengittersteine mit häufigem Verkehr 0,4.
[EN] Peak runoff coefficient of the paved surfaces for the flood case; choose it from Table 9, column C_s, per sub-area (area-weighted or via A_C,s when there are several). In Eq. 10 it replaces the mean coefficient C_m of the design because in a rare heavy rain practically all rainfall runs off. §5.3.4.1 Eq. 10 with Table 9 (§5.3.3.5), e.g. roofs 1.0, asphalt/concrete 1.0, concrete block paving in sand 0.9, grass pavers with frequent traffic 0.4.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'C_S';
UPDATE fields f SET description = 'Dauerstufe des Bemessungsregens, für die Gl. 10 ausgewertet wird; das Tool iteriert über die KOSTRA-Dauerstufen und zeigt die maßgebende Dauer mit dem größten V_Rück an, der Ingenieur bestätigt sie. Zusammen mit r_D(30) definiert sie den Lastfall des Nachweises im Bericht. §5.3.4.1: Die Ermittlung der maßgeblichen Dauerstufe D erfolgt iterativ für unterschiedliche Dauerstufen und jeweils zugehöriger Regenspende r_D(30).
[EN] Duration of the design rain for which Eq. 10 is evaluated; the tool iterates over the KOSTRA durations and shows the governing duration with the largest V_Rück, which you confirm. Together with r_D(30) it defines the load case of the proof in the report. §5.3.4.1: the governing duration D is determined iteratively for different durations and the corresponding rainfall intensity r_D(30).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'D_flood_min';
UPDATE fields f SET description = 'Versickerungsleistung der Anlage im Überflutungsfall, übernommen aus Q_S (final) in A138-24; sie wird in Gl. 10 als Abfluss aus der vollen Anlage angesetzt. Eine höhere Versickerungsleistung als in der Bemessung darf hier nicht angenommen werden. §5.3.4.1: Q_S = Versickerungsleistung nach Gl. 4, d. h. Q_S = k_i · A_S · 10³ (§5.3.3.6).
[EN] Infiltration capacity of the facility in the flood case, carried over from Q_S (final) in A138-24; in Eq. 10 it is applied as the outflow from the full facility. Do not assume a higher infiltration capacity here than in the design. §5.3.4.1: Q_S = infiltration capacity per Eq. 4, i.e. Q_S = k_i · A_S · 10³ (§5.3.3.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'Q_S_flood';
UPDATE fields f SET description = 'Mittlerer Drosselabfluss, der auch im Überflutungsfall aus der Anlage abgeführt wird; nur bei Anlagen mit Drossel (z. B. Mulden-Rigolen-System) aus dem Bemessungsblatt übernehmen, sonst 0 oder leer. Er mindert in Gl. 10 das zurückzuhaltende Volumen. §5.3.4.1: Q_Dr = mittlerer Drosselabfluss (z. B. bei Mulden-Rigolen-Systemen); §5.3.3.7: nur bei Anlagen relevant, die im Regelbetrieb einen zusätzlichen Abfluss in ein nachfolgendes System aufweisen.
[EN] Mean throttled outflow that leaves the facility also in the flood case; carry it over from the design sheet only for facilities with a throttle (e.g. swale-trench system), otherwise 0 or empty. In Eq. 10 it reduces the volume to be retained. §5.3.4.1: Q_Dr = mean throttled outflow (e.g. in swale-trench systems); §5.3.3.7: relevant only for facilities that have an additional discharge to a downstream system in normal operation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'Q_Dr_flood';
UPDATE fields f SET description = 'Vom Tool berechnete Summe Σ(A_E,b,a · C_S) über alle befestigten Zeilen des Flächenverzeichnisses (Gleichung A138-26-D1); nicht manuell eingeben. Sie ist der Flächenterm von Gl. 10 mit Spitzenabflussbeiwerten und ersetzt dort das Produkt aus Einzelfläche und Einzelbeiwert, sobald die Umstellung aktiv ist. Grundlage: §5.3.4.1 Gl. 10 mit C_S je Teilfläche nach Tabelle 9; unbefestigte Flächen bleiben außen vor, sofern sie nicht nach §5.3.4.1 ausdrücklich einbezogen werden.
[EN] Tool-computed sum Σ(A_E,b,a · C_S) over all paved rows of the surface inventory (equation A138-26-D1); do not enter manually. It is the area term of Eq. 10 with peak runoff coefficients and replaces the single area × single coefficient product there once the switch is active. Basis: §5.3.4.1 Eq. 10 with C_S per sub-area from Table 9; unpaved surfaces stay excluded unless explicitly included per §5.3.4.1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND f.symbol = 'A_C_s_flood';
UPDATE equations e SET description = 'Volumenbilanz des Überflutungsnachweises: Zufluss aus Spitzenabfluss der befestigten Flächen plus überregneter Anlagenfläche A_VA, abzüglich Q_S und Q_Dr über die Dauer D, abzüglich des bereits gefüllten Speichervolumens V_VA. Das Tool rechnet jede Dauerstufe mit dem zugehörigen r_D(30) bzw. r_D(100) und übernimmt das Maximum als V_Rück. §5.3.4.1: Nachweis nach DIN 1986-100 bei AC > 800 m²; negative Ergebnisse werden V_Rück = 0; der schadlose Verbleib auf dem Grundstück ist nachzuweisen.
[EN] Volume balance of the flood proof: inflow from the peak runoff of the paved surfaces plus the rained-on facility area A_VA, minus Q_S and Q_Dr over the duration D, minus the storage volume V_VA that is already full. The tool evaluates each duration with its r_D(30) or r_D(100) and takes the maximum as V_Rück. §5.3.4.1: proof per DIN 1986-100 required when AC > 800 m²; negative results become V_Rück = 0; harmless retention of the resulting volume on the plot must be demonstrated.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND e.equation_number = '10';
UPDATE equations e SET description = 'Hilfsgleichung des Tools: summiert über das Flächenverzeichnis für jede befestigte Zeile das Produkt Fläche × Spitzenabflussbeiwert C_s und liefert den Flächenterm Σ(A_E,b,a · C_S) für Gl. 10. Unbefestigte Zeilen gehen mit 0 ein. Sie bildet die Summenschreibweise von Gl. 10 (§5.3.4.1) ab, in der jede Teilfläche mit ihrem eigenen C_S nach Tabelle 9 zu bewerten ist; die Richtlinie selbst nummeriert diese Zwischensumme nicht.
[EN] Tool helper equation: sums over the surface inventory, for each paved row, the product area × peak runoff coefficient C_s and returns the area term Σ(A_E,b,a · C_S) for Eq. 10. Unpaved rows enter as 0. It implements the summation notation of Eq. 10 (§5.3.4.1), in which each sub-area is weighted with its own C_S from Table 9; the guideline itself does not number this intermediate sum.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-26' AND e.equation_number = 'A138-26-D1';
UPDATE fields f SET description = 'Prozentuale Abweichung des endgültigen Rechenwerts A_C (A138-24) vom vorläufigen Wert der Vorbemessung, vom Tool berechnet. Zeigt, ob sich das Flächenverzeichnis seit der Verfahrens- und Häufigkeitswahl so geändert hat, dass die 800-m²-Einstufung oder die Tabelle-8-Spalte neu zu prüfen ist. Die Richtlinie nennt keine zulässige Abweichung; A_C ist nach §5.3.3.5, Gl. 2 stets aus den aktuellen angeschlossenen Teilflächen zu bilden.
[EN] Percentage deviation of the final design value A_C (A138-24) from the preliminary value of the pre-design, computed by the tool. It shows whether the surface inventory has changed since the method and frequency selection to the extent that the 800 m² classification or the Table 8 column must be re-checked. The guideline gives no permissible deviation; per §5.3.3.5, Eq. 2, A_C must always be formed from the current connected sub-areas.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'preliminary_vs_final_A_C_dev_pct';
UPDATE fields f SET description = 'Prozentuale Abweichung des endgültigen Speichervolumens V_VA (A138-24) vom vorläufigen Volumen der allgemeinen Bemessung (A138-09), vom Tool berechnet. Große Abweichungen deuten auf geänderte Geometrie, k_i, f_Z oder Dauerstufe hin und sind im Design Review zu erklären. Die Richtlinie nennt keinen Grenzwert; nach §5.3.3.7 ist das erforderliche Speichervolumen nach Gl. 8 die Bemessungszielgröße und das Maximum über D maßgebend.
[EN] Percentage deviation of the final storage volume V_VA (A138-24) from the preliminary volume of the general design (A138-09), computed by the tool. Large deviations point to changed geometry, k_i, f_Z or duration and must be explained in the design review. The guideline sets no limit; per §5.3.3.7 the required storage volume per Eq. 8 is the design target and the maximum over D governs.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'preliminary_vs_final_storage_dev_pct';
UPDATE fields f SET description = 'Differenz zwischen dem verifizierten q_S,AC (A138-25) und dem Grenzwert 2 l/(s·ha), vom Tool berechnet (positiv = Reserve). Zeigt, wie robust die Anwendbarkeit des Einfachen Verfahrens gegenüber späteren Flächenerweiterungen oder einer nachlassenden Infiltrationsrate ist. §5.3.3.7, Gl. 9: q_S,AC ≥ 2 l/(s·ha); liegt q_S,AC ≤ 5 l/(s·ha), ist ein Zuschlagsfaktor f_Z = 1,2 erforderlich.
[EN] Difference between the verified q_S,AC (A138-25) and the threshold 2 l/(s·ha), computed by the tool (positive = margin). It shows how robust the applicability of the simple method is against later area extensions or a declining infiltration rate. §5.3.3.7, Eq. 9: q_S,AC ≥ 2 l/(s·ha); if q_S,AC ≤ 5 l/(s·ha), a surcharge factor f_Z = 1.2 is required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'qsac_deviation_from_threshold';
UPDATE fields f SET description = 'Bearbeitungsstand des internen Design Reviews (pending / in_review / approved / rejected), vom Prüfer gesetzt. Erst ''approved'' schließt die Abweichungsanalyse ab und gibt den Weg zur abschließenden Nachweiszusammenstellung (A138-28) frei; ''rejected'' erfordert korrektive Maßnahmen und eine erneute Prüfung. Die Richtlinie schreibt kein Review-Verfahren vor; Workflow-Feld.
[EN] Processing status of the internal design review (pending / in_review / approved / rejected), set by the reviewer. Only ''approved'' closes the deviation analysis and clears the way to the final verification compilation (A138-28); ''rejected'' requires corrective actions and a re-review. The guideline prescribes no review procedure; workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'design_review_status';
UPDATE fields f SET description = 'Name der Person, die das Design Review durchführt; sollte nicht mit dem Bearbeiter der Bemessung identisch sein (Vier-Augen-Prinzip des Workflows). Wird im Bericht als Prüfvermerk ausgewiesen. Die Richtlinie enthält hierzu keine Vorgabe; Workflow-Feld.
[EN] Name of the person performing the design review; should not be the same person who prepared the design (workflow four-eyes principle). Shown in the report as the review note. The guideline contains no requirement on this; workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'design_review_reviewer';
UPDATE fields f SET description = 'Datum des Design Reviews; vom Prüfer eintragen. Belegt, auf welchem Stand der Endwerte (A138-24/25/26) die Prüfung erfolgte. Kein Pflichtinhalt der Richtlinie; Workflow-Feld.
[EN] Date of the design review; entered by the reviewer. It records which state of the final values (A138-24/25/26) was reviewed. Not a mandatory content of the guideline; workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'design_review_date';
UPDATE fields f SET description = 'Freitext des Prüfers: festgestellte Abweichungen, Plausibilität der Eingangswerte (k_i, Abflussbeiwerte, KOSTRA-Werte), Hinweise für die Ausführungsplanung. Wird in den Bericht übernommen und begründet den Review-Status. Kein Pflichtinhalt der Richtlinie; Workflow-Feld.
[EN] Reviewer''s free text: deviations found, plausibility of input values (k_i, runoff coefficients, KOSTRA values), notes for the detailed design. Carried into the report and justifies the review status. Not a mandatory content of the guideline; workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'design_review_comments';
UPDATE fields f SET description = 'Angabe des Prüfers, ob aus dem Review korrektive Maßnahmen folgen (z. B. Anlage vergrößern, f_Z anpassen, Flächenverzeichnis korrigieren, Überflutungsnachweis wiederholen). Bei ''ja'' die Maßnahmen unten beschreiben und die betroffenen Blätter erneut durchlaufen, bevor A138-28 abgeschlossen wird. Kein Pflichtinhalt der Richtlinie; Workflow-Feld.
[EN] Reviewer''s statement whether corrective actions follow from the review (e.g. enlarge the facility, adjust f_Z, correct the surface inventory, repeat the flood proof). If ''yes'', describe the actions below and re-run the affected sheets before closing A138-28. Not a mandatory content of the guideline; workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'corrective_actions_required';
UPDATE fields f SET description = 'Beschreibung der korrektiven Maßnahmen mit betroffenem Arbeitsblatt, Verantwortlichem und Erledigungsstand. Dient als Nachweis, dass Review-Befunde abgearbeitet wurden, bevor die Konformität erklärt wird. Kein Pflichtinhalt der Richtlinie; Workflow-Feld.
[EN] Description of the corrective actions with the affected worksheet, responsible person and completion status. It serves as evidence that review findings were resolved before conformity is declared. Not a mandatory content of the guideline; workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-27' AND f.symbol = 'corrective_actions_description';
UPDATE fields f SET description = 'Abschließendes Konformitätsurteil des verantwortlichen Ingenieurs: compliant, compliant_with_conditions (mit benannten Auflagen) oder not_compliant. Es fasst die Tore der Phasen 2 bis 4, die Eignungsprüfung (A138-25) und den Überflutungsnachweis (A138-26) zusammen und ist Kernaussage der Konformitätserklärung; Gate A138-REQ-30 (warn) prüft, dass alle Phasentore PASS oder CONDITIONAL sind. Die Richtlinie kennt kein solches Urteil; maßgeblich sind §5 (Planung) und §6 (Anlagen).
[EN] Final conformity verdict of the responsible engineer: compliant, compliant_with_conditions (with named conditions) or not_compliant. It summarises the gate results of Phases 2 to 4, the adequacy check (A138-25) and the flood proof (A138-26) and appears as the core statement of the conformity declaration; gate A138-REQ-30 (warn) checks that all phase gates are PASS or CONDITIONAL. The guideline has no such verdict; the governing requirements are §5 (planning) and §6 (facilities).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'final_compliance_verdict';
UPDATE fields f SET description = 'Bestätigung, dass Phase 2 (Datenerhebung: Standort, Untergrund, MHGW, Flächen, Regenstatistik) abgeschlossen ist und das Phase-2-Tor PASS oder CONDITIONAL ergab. Ohne vollständige Datenbasis sind die Nachweise der späteren Phasen nicht belastbar. §5.1.1 nennt als Grundlagen der Ersteinschätzung u. a. den Abstand der Anlagensohle zum MHGW (≥ 1 m, sonst Abstimmung mit der Behörde) und Daten der Fachbehörden; fehlen Messdaten, sind ggf. qualifizierte Untersuchungen durchzuführen.
[EN] Confirmation that Phase 2 (data collection: site, subsoil, MHGW, surfaces, rainfall statistics) is complete and the Phase-2 gate gave PASS or CONDITIONAL. Without a complete data basis the proofs of the later phases are not reliable. §5.1.1 lists as bases of the initial assessment, among others, the distance from facility base to MHGW (≥ 1 m, otherwise agreement with the authority) and data from the authorities; if measured data are missing, qualified investigations may be required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'data_collection_phase_complete';
UPDATE fields f SET description = 'Bestätigung, dass Phase 3 (allgemeine Berechnungen nach §5.3: Rechenwert A_C, Zufluss, bemessungsrelevante Infiltrationsrate k_i, Versickerungsleistung Q_S, Bemessungshäufigkeit, Verfahrenswahl) abgeschlossen ist und das Phase-3-Tor PASS oder CONDITIONAL ergab. Diese Werte sind Eingang jeder anlagenspezifischen Gleichung in §6. §5.3.3.5 (Gl. 2, 3), §5.3.3.6 (Gl. 4 bis 7) und §5.3.3.7 (Gl. 8, 9) bilden die Bemessungsgrundsätze.
[EN] Confirmation that Phase 3 (general calculations per §5.3: design value A_C, inflow, design infiltration rate k_i, infiltration capacity Q_S, design frequency, method selection) is complete and the Phase-3 gate gave PASS or CONDITIONAL. These values are the input to every facility-specific equation in §6. §5.3.3.5 (Eq. 2, 3), §5.3.3.6 (Eq. 4 to 7) and §5.3.3.7 (Eq. 8, 9) form the sizing principles.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'general_calc_phase_complete';
UPDATE fields f SET description = 'Bestätigung, dass Phase 4 (anlagenspezifische Bemessung nach §6) abgeschlossen ist und das Phase-4-Tor in A138-23 PASS oder CONDITIONAL ergab. Damit liegen Anlagentyp, Speichervolumen und Geometrie endgültig vor. Nach §6.1 stellt Abschnitt 6 für ausgewählte Anlagen systemspezifische Bemessungsvorgaben als Bemessungsgleichungen bereit; Tabelle 14 (§6.9) fasst die Vorgaben aus §6.2 bis §6.8 zusammen.
[EN] Confirmation that Phase 4 (facility-specific design per §6) is complete and the Phase-4 gate in A138-23 gave PASS or CONDITIONAL. Facility type, storage volume and geometry are then final. Per §6.1, Section 6 provides system-specific design specifications as sizing equations for selected facilities; Table 14 (§6.9) compiles the specifications of §6.2 to §6.8.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'facility_design_phase_complete';
UPDATE fields f SET description = 'Bestätigung, dass Phase 5 abgeschlossen ist: Eignungsprüfung mit Gl. 9 (A138-25), Überflutungsnachweis nach Gl. 10 (A138-26, soweit erforderlich) und Design Review (A138-27) liegen vor. Diese Nachweise bilden den Kern der Konformitätserklärung. §5.3.3.7: q_S,AC ≥ 2 l/(s·ha); §5.3.4.1: Überflutungsnachweis nach DIN 1986-100 bei AC > 800 m², in der Regel für T_n = 30 a, mit Nachweis des schadlosen Verbleibs auf dem Grundstück.
[EN] Confirmation that Phase 5 is complete: adequacy check with Eq. 9 (A138-25), flood proof per Eq. 10 (A138-26, where required) and design review (A138-27) are in place. These proofs form the core of the conformity declaration. §5.3.3.7: q_S,AC ≥ 2 l/(s·ha); §5.3.4.1: flood proof per DIN 1986-100 when AC > 800 m², as a rule for T_n = 30 a, with proof of harmless retention on the plot.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'verification_phase_complete';
UPDATE fields f SET description = 'Bestätigung, dass die Anlagendokumentation vollständig ist und in das Betriebshandbuch übernommen werden kann. §7.4: Anlage und Funktionsweise sind als Bestandteil eines Betriebshandbuchs gemäß §8.3 zu dokumentieren (Plandarstellung, Wartungs- und Betriebshinweise, Genehmigungen und Erlaubnisse), erstellt von der planenden mit der ausführenden Person. §8.3.2 nennt u. a. Versickerungsfähigkeit, Bemessung (ggf. inkl. Überflutungsschutz), Wasserrechtsantrag, wasserrechtliche Erlaubnis und Bestandsplan.
[EN] Confirmation that the facility documentation is complete and can be transferred into the operating manual. §7.4: facility and function must be documented as part of an operating manual per §8.3 (plan drawings, maintenance and operating notes, permits and approvals), prepared by the planner together with the person responsible for execution. §8.3.2 lists, among others, infiltration capacity, the design (incl. flood protection where integrated), water-law application, water-law permit and as-built plan.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'final_documentation_complete';
UPDATE fields f SET description = 'Bestätigung, dass die Unterlagen für die wasserrechtliche Erlaubnis bzw. der Nachweis der erlaubnisfreien Versickerung nach Landesrecht vollständig vorliegen (Erläuterungsbericht, technische Nachweise, Pläne). Anhang B.2: Die gezielte Versickerung in das Grundwasser ist eine Gewässerbenutzung (§ 9 Abs. 1 Nr. 4 WHG) und bedarf im Regelfall einer Erlaubnis nach § 8 WHG; dazu sind Unterlagen vorzulegen. Die Ausführungsplanung (§5.3.5, Schluss) setzt die abschließende Prüfung von Baugenehmigung und Erlaubnis voraus.
[EN] Confirmation that the documents for the water-law permit, or the proof of permit-free infiltration under state law, are complete (explanatory report, technical proofs, plans). Annex B.2: targeted infiltration into groundwater is a use of a water body (§ 9(1) No. 4 WHG) and as a rule requires a water-law permit under § 8 WHG; documents must be submitted for it. The detailed design (end of §5.3.5) presupposes that building permit and water permit have been finally checked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'permitting_documentation_ready';
UPDATE fields f SET description = 'Datum der Endabnahme der Planungsnachweise durch den verantwortlichen Ingenieur; schließt den Workflow ab und wird in der Konformitätserklärung ausgewiesen. Spätere Änderungen an Flächen oder Anlage erfordern eine erneute Prüfung, da z. B. der Überflutungsnachweis nach §5.3.4.1 von den befestigten Flächen des Grundstücks abhängt. Die Richtlinie schreibt kein Datum vor; Workflow-Feld.
[EN] Date of the final sign-off of the design proofs by the responsible engineer; it closes the workflow and is shown in the conformity declaration. Later changes to surfaces or facility require a re-check, since e.g. the flood proof per §5.3.4.1 depends on the paved surfaces of the plot. The guideline does not prescribe a date; workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'final_signoff_date';
UPDATE fields f SET description = 'Name des Ingenieurs, der die Nachweise abschließend verantwortet und die Konformitätserklärung unterzeichnet. Wird im Bericht und im Betriebshandbuch als verantwortliche Planungsperson geführt. Die Richtlinie benennt keine Qualifikation hierfür; §7.4 spricht von der für die Planung zuständigen Person, die die Dokumentation mit dem Ausführungsverantwortlichen erstellt. Workflow-Feld.
[EN] Name of the engineer who finally takes responsibility for the proofs and signs the conformity declaration. Listed in the report and the operating manual as the responsible planner. The guideline names no qualification for this; §7.4 speaks of the person responsible for planning who prepares the documentation with the person responsible for execution. Workflow field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-A-138-1' AND w.code = 'A138-28' AND f.symbol = 'final_signoff_engineer';
COMMIT;
